/* 自动生成，请勿手工修改。来源：DSH chemistry/chem-equation；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"chem-equation-1","title":"质量守恒定律：内容、微观解释与应用","subtitle":"人教版九年级 · 第五单元 化学方程式 · 9a","grade":"9a","tags":["人教版九年级 · 第五单元 化学方程式"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第五单元 化学方程式 · 9a"},{"type":"note","title":"问题切入","text":"铁钉放进硫酸铜溶液里会变红，镁条在空气中烧完却比原来重了——化学反应前后的总质量到底变不变？为什么有的实验称出来变轻、有的实验称出来变重？"},{"type":"note","title":"一句话抓住关键","text":"参加化学反应的各物质的质量总和，等于反应后生成的各物质的质量总和。微观上之所以守恒，是因为反应前后原子的种类不变、数目不变、质量不变——分子可以重新组合，原子却不会凭空多出来或消失。称量时看的是「参加反应」的质量，不是「加进去」的质量。"},{"type":"h","text":"【宏观】一、先把三个实验的现象看清楚"},{"type":"p","text":"铁钉放入硫酸铜溶液：铁钉表面覆盖一层红色的铜，蓝色的溶液逐渐变成浅绿色，反应前后把整个装置放到托盘天平上称量，总质量没有变化。碳酸钠与稀盐酸：产生大量气泡，如果在敞口烧杯里反应完再称量，总质量变小了，因为生成的二氧化碳跑到了空气中。镁条在空气中燃烧：发出耀眼的白光，生成白色固体，称量后发现固体质量比原来的镁条大，因为空气中的氧气参加了反应，变成了固体的一部分。三个实验其实都遵守质量守恒定律，差别只在「有没有气体跑掉或跑进来」。"},{"type":"figure","figure":{"id":"fig-chem-equation-1-macro","title":"铁钉与硫酸铜溶液反应","caption":"反应前后把整个装置放到托盘天平上称量，总质量相等","view":"wide","alt":"锥形瓶中盛着蓝色的硫酸铜溶液，一根铁钉浸在溶液里，瓶口塞着橡皮塞，铁钉表面覆盖一层红色的铜","prims":[{"t":"flask","x":34,"y":36,"kind":"conical","h":30,"w":26,"liquid":0.55,"color":"blue","label":"锥形瓶"},{"t":"line","x1":30,"y1":28,"x2":38,"y2":42,"width":1.6},{"t":"text","x":20,"y":26,"text":"铁钉","size":3.4},{"t":"rect","x":30,"y":23.5,"w":8,"h":3.5,"fill":true,"tone":"main"},{"t":"text","x":74,"y":22,"text":"铁钉表面覆盖","size":3.2},{"t":"text","x":74,"y":29,"text":"一层红色物质","size":3.2},{"t":"text","x":74,"y":36,"text":"蓝色溶液逐渐","size":3.2},{"t":"text","x":74,"y":43,"text":"变成浅绿色","size":3.2}]}},{"type":"note","title":"","text":"描述现象要分清「溶液的颜色」和「固体的颜色」：溶液由蓝色变成浅绿色，铁钉表面覆盖的是红色的铜，不能说成「铁钉变绿」。"},{"type":"h","text":"【微观】二、微观上到底什么没变"},{"type":"p","text":"反应前有 2 个氢分子和 1 个氧分子，反应后有 2 个水分子。变化的是分子的种类（氢分子、氧分子变成了水分子），没变的是原子：反应前后都是 4 个氢原子、2 个氧原子，一个不多、一个不少，每个原子的质量也没有变。所以「原子的种类不变、数目不变、质量不变」这三条，就是质量守恒定律的微观解释；由此还推出元素种类、元素质量也不变。"},{"type":"figure","figure":{"id":"fig-chem-equation-1-micro","title":"氢气燃烧的微观过程","caption":"分子分成原子、原子重新组合，原子的种类、数目、质量都不变","view":"wide","alt":"左边是两个氢分子和一个氧分子，中间标着点燃的箭头，右边是两个水分子，反应前后氢原子都是四个、氧原子都是两个","prims":[{"t":"molecule","x":12,"y":14,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":12,"y":36,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":32,"y":25,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"arrow","x1":44,"y1":25,"x2":56,"y2":25,"label":"点燃","labelDy":-4},{"t":"molecule","x":72,"y":16,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":72,"y":38,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":50,"y":57,"text":"H 原子 4 个、O 原子 2 个，反应前后一样多","size":3.1}]}},{"type":"note","title":"","text":"「三不变」记原子：原子种类不变、原子数目不变、原子质量不变。分子种类一定改变，分子数目可能改变（本反应由 3 个分子变成 2 个分子）。"},{"type":"h","text":"【符号】三、用符号把守恒「算」出来"},{"type":"p","text":"把红磷燃烧的方程式拿来数原子：4P + 5O₂ —点燃→ 2P₂O₅。左边磷原子 4 个、氧原子 5×2 = 10 个；右边 2 个 P₂O₅ 里有磷原子 2×2 = 4 个、氧原子 2×5 = 10 个。两边原子种类相同、数目相等，质量自然相等。数原子时要用「系数 × 下标」：P₂O₅ 前配 2，磷原子就是 2×2 个，这一条既是配平的依据，也是判断方程式对错的依据。"},{"type":"figure","figure":{"id":"fig-chem-equation-1-symbol","title":"方程式两边的原子个数","caption":"某元素原子个数 = 化学式前面的系数 × 该元素符号右下角的下标","view":"wide","alt":"红磷燃烧的方程式两边分别标出磷原子与氧原子的个数，左边四个磷原子十个氧原子，右边也是四个磷原子十个氧原子","prims":[{"t":"text","x":50,"y":10,"text":"4P + 5O₂ —点燃→ 2P₂O₅","size":5},{"t":"text","x":50,"y":22,"text":"反应前：P 4 个，O 5×2 = 10 个","size":3.4},{"t":"text","x":50,"y":30,"text":"反应后：P 2×2 = 4 个，O 2×5 = 10 个","size":3.4},{"t":"molecule","x":18,"y":40,"atoms":[{"dx":-2.6,"dy":0,"symbol":"O","color":"red","r":2.4},{"dx":2.6,"dy":0,"symbol":"O","color":"red","r":2.4}],"bonds":[[0,1]],"label":"O₂"},{"t":"text","x":76,"y":38,"text":"P₂O₅ 中 P 与 O 的个数比是 2 : 5","size":3},{"t":"text","x":50,"y":58,"text":"两边原子个数相等，这就是配平的依据","size":3.2}]}},{"type":"note","title":"","text":"最常见的计数错误是漏乘系数：把 2P₂O₅ 里的磷原子数写成 2 个。凡带系数的化学式，数原子时先把系数乘进去。"},{"type":"h","text":"【应用】四、应用：算质量、推组成、选装置"},{"type":"p","text":"第一类应用是算质量：已知反应中几种物质的质量，用质量守恒可以直接求剩下那种物质的质量（反应物质量总和 = 生成物质量总和）。第二类应用是推断组成：某物质燃烧只生成二氧化碳和水，说明它一定含碳、氢元素，是否含氧要用元素质量守恒去算。第三类应用是判断装置：有气体参加或生成的反应，必须在密闭容器中进行，否则跑掉或进来的气体让总质量改变，实验就说明不了问题。"},{"type":"figure","figure":{"id":"fig-chem-equation-1-airtight","title":"密闭容器与敞口容器","caption":"有气体参加或生成的反应，验证质量守恒必须用密闭容器","view":"wide","alt":"左边是瓶口套着气球的密闭锥形瓶，右边是敞口烧杯，杯中有气泡冒出","prims":[{"t":"flask","x":26,"y":36,"kind":"conical","h":30,"w":26,"liquid":0.5,"color":"colorless","label":"锥形瓶"},{"t":"rect","x":22,"y":23.5,"w":8,"h":3.5,"fill":true,"tone":"main"},{"t":"circle","cx":26,"cy":12,"r":6,"tone":"accent","label":"气球"},{"t":"beaker","x":62,"y":28,"w":24,"h":22,"fill":0.5,"label":"敞口烧杯"},{"t":"dot","x":68,"y":40,"hollow":true},{"t":"dot","x":74,"y":34,"hollow":true},{"t":"dot","x":80,"y":43,"hollow":true},{"t":"text","x":26,"y":60,"text":"密闭：总质量不变","size":3.3},{"t":"text","x":74,"y":60,"text":"敞口：气体逸出，质量变小","size":3.1}]}},{"type":"note","title":"","text":"判断装置能不能用来验证质量守恒，只看一句话：这个反应有没有气体参加或生成。有，就必须密闭；没有（如铁与硫酸铜溶液、氢氧化钠与硫酸铜溶液），敞口也可以。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["质量守恒定律","参加化学反应的各物质的质量总和 = 反应后生成的各物质的质量总和","各物质的质量单位统一（都用 g 或都用 kg） · 只适用于化学变化，不能用于物理变化（冰熔化、水蒸发、气体膨胀都不是化学反应）。式中的质量是「参加反应」的质量，过量未反应的部分不计入；有气体或沉淀参与时，必须把气体和沉淀也算进总和里。"],["原子守恒（微观解释）","反应前后原子的种类不变、数目不变、质量不变","数目以「个」计，不必换算 · 用来判断微观粒子示意图题、判断某方程式是否配平、推断未知物质的化学式：把两边各原子的个数相减，差额就是未知物里含有的原子数。注意分子种类一定改变，分子数目可能改变，不能用分子守恒代替原子守恒。"],["元素质量守恒","反应前后各元素的质量不变；生成物中某元素的质量 = 生成物质量 × 该元素的质量分数","质量单位统一为 g · 用来推断物质的元素组成（燃烧生成二氧化碳和水 ⇒ 一定含碳、氢，是否含氧要用碳、氢质量之和与样品质量比较）。以化合物形式存在的元素质量要按化合物中该元素的质量分数折算，不能直接把化合物质量当成元素质量。"],["原子个数 = 系数 × 下标","某元素原子的个数 = 化学式前面的系数 × 该元素符号右下角的下标","个数以「个」计 · 用于数原子、配平与判断方程式对错。如 2P₂O₅ 中磷原子为 2×2 = 4 个、氧原子为 2×5 = 10 个。系数为 1 时省略不写，但不能漏乘；括号里的原子团要先乘括号内的数目再乘系数，如 3Ca(OH)₂ 中氧原子为 3×2 = 6 个。"]]},{"type":"h","text":"应用 · 由质量守恒求参加反应的氧气质量"},{"type":"note","title":"情境","text":"6 g 镁条在空气中完全燃烧，生成 10 g 氧化镁。求参加反应的氧气质量。"},{"type":"list","title":"解答步骤","items":["写出化学方程式：2Mg + O₂ —点燃→ 2MgO。","由质量守恒定律：m(镁) + m(氧气) = m(氧化镁)，即 6 g + m(氧气) = 10 g。","解得 m(氧气) = 10 g − 6 g = 4 g。","用相对质量比检验：2Mg 为 48，O₂ 为 32，2MgO 为 80，48 : 32 : 80 化简后是 6 g : 4 g : 10 g，与计算结果一致。"]},{"type":"figure","figure":{"id":"fig-chem-equation-1-app1","title":"镁条燃烧前后的质量关系","caption":"固体质量增大的部分来自空气中的氧气","view":"wide","alt":"镁条在空气中燃烧发出白光，生成白色固体粉末，旁边标出 6 克镁与 4 克氧气生成 10 克氧化镁","prims":[{"t":"text","x":50,"y":12,"text":"6 g 镁 + 4 g 氧气 —点燃→ 10 g 氧化镁","size":4},{"t":"text","x":50,"y":26,"text":"固体质量比原来大：增大的部分是空气中的氧气","size":3.2},{"t":"text","x":50,"y":38,"text":"把氧气也算进去，反应前后总质量相等","size":3.2},{"t":"text","x":50,"y":52,"text":"质量守恒定律对一切化学反应都成立","size":3.2,"tone":"accent"}]}},{"type":"note","title":"结论","text":"参加反应的氧气质量为 4 g。"},{"type":"h","text":"应用 · 敞口容器中反应后质量变小怎么解释"},{"type":"note","title":"情境","text":"家里用食醋浸泡小苏打（碳酸氢钠）时，杯子里冒出大量气泡，放在厨房秤上发现数值越来越小。是不是反应不遵守质量守恒定律？"},{"type":"list","title":"解答步骤","items":["写出反应实质：碳酸氢钠与酸反应生成二氧化碳气体。","明确称量对象：敞口杯子里剩下的物质质量 = 反应前总质量 − 逸出气体的质量。","换成密闭容器（如带气球的锥形瓶）重复实验，总质量不再改变。","结论：质量守恒定律成立，减少的质量等于逸出气体的质量。"]},{"type":"note","title":"结论","text":"减少的质量就是逸出的二氧化碳的质量，质量守恒定律仍然成立。"},{"type":"h","text":"应用 · 由燃烧产物推断物质的元素组成"},{"type":"note","title":"情境","text":"4.6 g 某物质在氧气中完全燃烧，只生成 8.8 g 二氧化碳和 5.4 g 水。判断该物质中一定含有什么元素。"},{"type":"list","title":"解答步骤","items":["8.8 g 二氧化碳中碳元素的质量 = 8.8 g × 12/44 = 2.4 g。","5.4 g 水中氢元素的质量 = 5.4 g × 2/18 = 0.6 g。","碳、氢元素质量之和 = 2.4 g + 0.6 g = 3.0 g，小于 4.6 g。","差值 4.6 g − 3.0 g = 1.6 g 只能是氧元素（这部分氧既可能来自该物质，也可能来自氧气，但生成物中的氧多于氧气提供的氧，故该物质中一定含氧）。","结论：该物质一定含碳、氢、氧三种元素。"]},{"type":"note","title":"结论","text":"一定含有碳、氢、氧三种元素，其中碳 2.4 g、氢 0.6 g、氧 1.6 g。"},{"type":"h","text":"实验 1 · 铁钉与硫酸铜溶液反应前后质量的测定"},{"type":"note","title":"实验目的","text":"通过没有气体参加或生成的反应，验证化学反应前后物质的总质量不变"},{"type":"list","title":"实验器材","items":["托盘天平","锥形瓶","橡皮塞","铁钉（用砂纸打磨光亮）","硫酸铜溶液"]},{"type":"figure","figure":{"id":"fig-chem-equation-1-exp1","title":"铁钉与硫酸铜溶液反应","caption":"锥形瓶带橡皮塞，反应前后称量整个装置的总质量","view":"wide","alt":"锥形瓶中装蓝色的硫酸铜溶液，一根铁钉浸在溶液中，瓶口塞着橡皮塞","prims":[{"t":"flask","x":34,"y":36,"kind":"conical","h":30,"w":26,"liquid":0.55,"color":"blue","label":"锥形瓶"},{"t":"line","x1":30,"y1":28,"x2":38,"y2":42,"width":1.6},{"t":"text","x":20,"y":26,"text":"铁钉","size":3.4},{"t":"rect","x":30,"y":23.5,"w":8,"h":3.5,"fill":true,"tone":"main"},{"t":"text","x":74,"y":26,"text":"先称量装置与药品","size":3.1},{"t":"text","x":74,"y":34,"text":"的总质量，反应后再","size":3.1},{"t":"text","x":74,"y":42,"text":"称量并比较","size":3.1}]}},{"type":"list","title":"实验步骤","items":["把托盘天平放在水平台上，游码归零，调节平衡螺母使横梁平衡。","把铁钉放入锥形瓶，倒入适量硫酸铜溶液，塞紧橡皮塞。","把整个锥形瓶放在天平左盘上称量，记录质量 m₁。","取下锥形瓶，倾斜并轻轻振荡，使铁钉与溶液充分接触，观察现象。","反应一段时间后把锥形瓶放回天平左盘，再次称量，记录质量 m₂。"]},{"type":"note","title":"实验现象","text":"铁钉表面覆盖一层红色的铜，蓝色溶液逐渐变成浅绿色；两次称量的总质量相等（m₁ = m₂）。"},{"type":"note","title":"实验结论","text":"化学反应前后物质的总质量不变，Fe + CuSO₄ —→ FeSO₄ + Cu。"},{"type":"list","title":"注意事项","items":["铁钉要先用砂纸打磨除去表面的铁锈，否则铁锈会先与硫酸铜反应，影响观察。","橡皮塞要塞紧，反应中不要打开塞子，避免溶液洒出或外界物质进入。","天平称量前必须先调平，称量时砝码用镊子夹取，不能用手拿。"]},{"type":"h","text":"实验 2 · 碳酸钠与稀盐酸在密闭容器中反应前后质量的测定"},{"type":"note","title":"实验目的","text":"说明有气体生成的反应必须在密闭容器中称量，才能验证质量守恒定律"},{"type":"list","title":"实验器材","items":["托盘天平","锥形瓶","单孔橡皮塞","气球","碳酸钠粉末","稀盐酸"]},{"type":"figure","figure":{"id":"fig-chem-equation-1-exp2","title":"密闭容器中碳酸钠与稀盐酸反应","caption":"瓶口套紧气球，生成的二氧化碳被收集在气球里，总质量不变","view":"wide","alt":"锥形瓶中盛有无色的稀盐酸溶液，瓶口塞着带气球的橡皮塞，溶液中不断冒出气泡","prims":[{"t":"flask","x":34,"y":38,"kind":"conical","h":30,"w":26,"liquid":0.5,"color":"colorless","label":"锥形瓶"},{"t":"rect","x":30,"y":25.5,"w":8,"h":3.5,"fill":true,"tone":"main"},{"t":"circle","cx":34,"cy":14,"r":6,"tone":"accent","label":"气球"},{"t":"dot","x":28,"y":44,"hollow":true},{"t":"dot","x":34,"y":40,"hollow":true},{"t":"dot","x":40,"y":45,"hollow":true},{"t":"text","x":76,"y":30,"text":"碳酸钠与稀盐酸","size":3.1},{"t":"text","x":76,"y":37,"text":"反应放出二氧化碳","size":3.1},{"t":"text","x":76,"y":44,"text":"气体被气球收集，","size":3.1},{"t":"text","x":76,"y":51,"text":"总质量不变","size":3.1}]}},{"type":"list","title":"实验步骤","items":["把盛有碳酸钠粉末的小试管小心放入锥形瓶，倒入适量稀盐酸（两者暂时不接触）。","塞紧带气球的单孔橡皮塞，把锥形瓶放在天平上称量，记录质量 m₁。","取下锥形瓶，倾斜使碳酸钠与稀盐酸接触，观察气泡与气球的变化。","待反应结束后放回天平再次称量，记录质量 m₂。"]},{"type":"note","title":"实验现象","text":"溶液中产生大量气泡，气球逐渐胀大；两次称量的总质量相等（m₁ = m₂）。"},{"type":"note","title":"实验结论","text":"有气体生成的化学反应，在密闭容器中总质量不变，Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑。"},{"type":"list","title":"注意事项","items":["气球必须套紧在瓶口，不能漏气，否则气体逸出会导致总质量变小。","气球胀大后体积变大，受到的空气浮力略有增加，初中阶段忽略这一影响，实验装置不宜做得过大。","如果去掉气球敞口称量，减少的质量就是逸出的二氧化碳的质量，不能据此说反应不遵守质量守恒定律。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["Fe + CuSO₄ —→ FeSO₄ + Cu","常温（不需加热）","铁钉表面覆盖一层红色的铜，蓝色溶液逐渐变成浅绿色，铁钉质量增大","配平要点：系数全为 1，两边铁、铜、硫、氧原子个数相等，无需调整。此反应没有气体参加或生成，敞口容器中也能验证质量守恒。"],["Na₂CO₃ + 2HCl —→ 2NaCl + H₂O + CO₂↑","常温（不需加热）","固体逐渐溶解，产生大量气泡，把气体通入澄清石灰水会变浑浊","配平要点：钠 2、碳 1、氧 3、氢 2、氯 2，两边个数相等，系数为 1、2、2、1、1。生成的气体要标 ↑；敞口称量时二氧化碳逸出，总质量变小，验证质量守恒必须密闭。"],["2Mg + O₂ —点燃→ 2MgO","点燃","发出耀眼的白光，放出大量的热，生成白色固体","配平要点：先配氧。右边 MgO 中氧原子 1 个（奇数），在 MgO 前配 2 使氧原子变偶数，再在 Mg 前配 2。镁条燃烧后固体质量增大，增大的部分就是参加反应的氧气。"],["4P + 5O₂ —点燃→ 2P₂O₅","点燃","产生大量白烟（五氧化二磷固体小颗粒），放出大量的热","配平要点：最小公倍数法。左边每 1 个 O₂ 含 2 个氧原子，右边每 1 个 P₂O₅ 含 5 个氧原子，2 与 5 的最小公倍数是 10，故 O₂ 前配 5、P₂O₅ 前配 2，最后在 P 前配 4。现象写「白烟」不写「白雾」。"],["2H₂O₂ —MnO₂→ 2H₂O + O₂↑","二氧化锰作催化剂","有大量气泡产生，把带火星的木条伸入瓶中木条复燃","配平要点：奇偶配平法。右边的氧原子总数为奇数（H₂O 里 1 个加 O₂ 里 2 个），先在 H₂O 前配 2，再在 H₂O₂ 前配 2、O₂ 前配 1。二氧化锰是催化剂，写在箭头上方，反应前后质量与化学性质都不变。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["10 g 冰熔化成 10 g 水，说明质量守恒定律成立","质量守恒定律只适用于化学变化，冰熔化是物理变化，不能用它来解释","质量守恒定律描述的是化学反应中原子重新组合带来的质量关系。冰熔化只是分子间隔改变，没有新物质生成，虽然质量也不变，但那不属于质量守恒定律的适用范围，中考这样答不给分。"],["镁条燃烧后固体质量变大了，说明质量守恒定律不成立","增大的质量来自参加反应的氧气，把氧气算进去总质量仍然相等","镁与空气中的氧气化合生成了氧化镁，氧气变成了固体的一部分。称量时只称了固体，漏掉了参加反应的气体，于是显得「质量变大」。改成密闭容器并把氧气一起称量，结果就守恒了。"],["碳酸钠与稀盐酸在敞口烧杯中反应后质量减小，所以这个反应不遵守质量守恒定律","生成的二氧化碳逸散到空气中，减少的质量正是这部分气体，密闭后总质量不变","质量守恒说的是参加反应与生成的物质总质量，不含已经离开容器的气体。凡是有气体生成的反应，验证质量守恒都必须用密闭容器。"],["化学反应前后，分子的种类和数目都不变","分子种类一定改变；分子数目可能改变","化学变化的实质是分子分成原子、原子重新组合成新分子，分子种类必然改变。如 2H₂ + O₂ —点燃→ 2H₂O 中分子由 3 个变成 2 个，分子数目也变了，只有原子才是「三不变」。"],["把反应物按任意质量混合，反应后各物质质量之和一定等于加进去的质量之和","只有参加了反应的那部分质量才参与守恒关系，过量未反应的部分不参与","若两种反应物没有恰好完全反应，剩余的那部分没有参加反应，仍以原来的形式存在。用质量守恒计算时，代入的必须是真正参加反应的质量。"]]},{"type":"table","title":"密闭容器与敞口容器（验证质量守恒定律时容器该怎么选）","head":["比较项","密闭容器","敞口容器"],"rows":[["适用反应","有气体参加或有气体生成的反应（Mg + O₂、Na₂CO₃ + HCl、Mg + 稀盐酸）","反应物和生成物中都没有气体的反应（Fe + CuSO₄、NaOH + CuSO₄）"],["称量结果","反应前后总质量相等，可以验证质量守恒","有气体逸出时质量变小，有气体参加时质量变大"],["典型现象","气球胀大（收集气体），总质量不变","杯口冒气泡，总质量减少"],["答题要点","强调「密闭」是为了把气体留在称量范围内","强调「若敞口则不能验证」，并指出减少的质量是逸出气体的质量"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["从微观粒子示意图判断是否遵守质量守恒","给出反应前后的粒子模型，要求数出各原子的个数并判断说法正误，或要求补画反应后的粒子模型。做题的固定动作是先数清每种原子的个数（反应前后必须相等），再看分子的种类与个数是否改变。"],["用质量守恒定律推断质量或元素组成","给出一组质量数据求某种物质的质量，或由燃烧产物反推物质的元素组成。前者用「反应物质量总和 = 生成物质量总和」，后者要先算生成物中碳、氢元素的质量再与样品质量比较，判断有无氧元素。"],["实验装置能否验证质量守恒的评价","给出敞口烧杯、带气球的锥形瓶、带玻璃片的集气瓶等装置图，要求判断能否验证质量守恒并说明理由。答题口诀：先看有没有气体参加或生成，再判断容器是否密闭，最后说明质量偏大或偏小的原因。"]]},{"type":"quote","text":"【材料一】甲组把打磨光亮的铁钉放入盛有硫酸铜溶液的锥形瓶中，塞紧橡皮塞，放在托盘天平上称量并记录质量；反应一段时间后再次称量，两次示数相同。\n【材料二】乙组把碳酸钠粉末与稀盐酸放入锥形瓶，瓶口套一只气球，称量后使两者接触，反应结束后再次称量，两次示数相同。丙组把镁条放在坩埚中在酒精灯上点燃，燃烧完全后称量白色固体，发现比原来的镁条重。\n【材料三】某同学做完上述实验后总结说：凡是反应后质量变大的，都是因为空气中的物质参加了反应；凡是质量变小的，都是因为质量守恒定律不适用。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】写出甲组实验中发生反应的化学方程式，并说明甲组实验观察到的溶液颜色变化。（3 分）","【设问】乙组为什么要在瓶口套一只气球？如果去掉气球，反应后称量的结果会怎样变化？为什么？（4 分）","【设问】用质量守恒定律解释丙组镁条燃烧后固体质量增大的现象，并判断材料三中那位同学的总结是否正确，说明理由。（4 分）"]}],"questions":[{"id":"chem-equation-1-q1","type":"choice","stem":"图是一氧化碳在氧气中燃烧生成二氧化碳的微观示意图。下列说法正确的是","answer":"B","explain":"反应前 2 个 CO 分子中有 2 个氧原子，1 个 O₂ 分子中有 2 个氧原子，共 4 个；反应后 2 个 CO₂ 分子中有 2×2 = 4 个氧原子，数目确实不变，B 正确。A 错：分解反应是「一变多」，这里是两种物质生成一种物质，属于化合反应。C 错：分子的种类一定改变，CO、O₂ 变成了 CO₂。D 错：化学反应前后总质量守恒，生成气体不会使总质量增大，气体若留在密闭容器里质量也不变。","options":["该反应属于分解反应，因为反应后生成了新的分子","反应前后氧原子的数目都是 4 个，没有改变","反应前后分子的种类不变，只是排列方式变了","反应前后物质的总质量增大，因为生成了气体"],"difficulty":1,"tags":["质量守恒定律","微观粒子","原子个数"],"figure":{"id":"fig-chem-equation-1-q1","title":"一氧化碳燃烧的微观示意图","caption":"","view":"wide","alt":"反应前是两个一氧化碳分子和一个氧分子，反应后是两个二氧化碳分子，反应前后碳原子都是两个、氧原子都是四个","prims":[{"t":"molecule","x":12,"y":16,"atoms":[{"dx":-2.6,"dy":0,"symbol":"C","color":"black"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"CO"},{"t":"molecule","x":12,"y":42,"atoms":[{"dx":-2.6,"dy":0,"symbol":"C","color":"black"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"CO"},{"t":"molecule","x":32,"y":29,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"arrow","x1":44,"y1":29,"x2":56,"y2":29,"label":"点燃","labelDy":-4},{"t":"molecule","x":74,"y":16,"atoms":[{"dx":-3.2,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":0,"symbol":"C","color":"black"},{"dx":3.2,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"molecule","x":74,"y":42,"atoms":[{"dx":-3.2,"dy":0,"symbol":"O","color":"red"},{"dx":0,"dy":0,"symbol":"C","color":"black"},{"dx":3.2,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1],[1,2]],"label":"CO₂"},{"t":"text","x":50,"y":58,"text":"O 原子：反应前 2 + 2 = 4 个，反应后 2×2 = 4 个","size":3}]}},{"id":"chem-equation-1-q2","type":"choice","stem":"下列关于质量守恒定律的说法，正确的是","answer":"C","explain":"化学变化的微观实质是原子重新组合，原子种类、数目、质量都不变，这正是质量守恒的原因，C 正确。A 错：冰熔化是物理变化，不属于质量守恒定律的适用范围。B 错：镁燃烧时空气中的氧气参加了反应变成了固体，把氧气算进去总质量不变，定律仍然成立。D 错：分子种类一定改变，分子数目也可能改变，如 2H₂ + O₂ —点燃→ 2H₂O 中分子由 3 个变成 2 个。","options":["10 g 冰完全熔化成 10 g 水，说明质量守恒定律成立","镁条在空气中燃烧后固体质量增大，说明质量守恒定律不成立","化学反应前后，原子的种类、数目和质量都不变","化学反应前后，分子的种类和数目都不变"],"difficulty":1,"tags":["质量守恒定律","微观解释"]},{"id":"chem-equation-1-q3","type":"choice","stem":"4.6 g 某物质在氧气中完全燃烧，只生成 8.8 g 二氧化碳和 5.4 g 水。下列关于该物质组成的判断正确的是","answer":"D","explain":"8.8 g 二氧化碳中碳元素的质量 = 8.8 g × 12/44 = 2.4 g；5.4 g 水中氢元素的质量 = 5.4 g × 2/18 = 0.6 g。两者之和为 3.0 g，小于样品的 4.6 g，说明该物质中还含有氧元素 4.6 g − 3.0 g = 1.6 g，D 正确。A 错在漏掉了氧：若只含碳、氢，样品质量应等于 3.0 g。B 错：生成物中有水，说明一定含氢元素。C 错的正是那个 1.6 g 的氧，凡是「碳、氢质量之和小于样品质量」就说明含氧。","options":["只含碳、氢两种元素","只含碳元素，不含氢元素","一定含碳、氢元素，且不含氧元素","一定含有碳、氢、氧三种元素"],"difficulty":2,"tags":["质量守恒定律","元素质量守恒","元素组成"]},{"id":"chem-equation-1-q4","type":"choice","stem":"把盛有碳酸钠粉末的烧杯放在天平上称量，再加入足量稀盐酸，充分反应后再次称量，发现总质量减小了。下列解释正确的是","answer":"A","explain":"碳酸钠与稀盐酸反应生成氯化钠、水和二氧化碳，敞口放置时二氧化碳跑到空气中，称到的总质量当然变小，但把逸出的气体算进来依然守恒，A 正确。B 错：质量与能量不能混为一谈，化学变化中物质的质量不会变成能量而消失。C 错：一切化学反应都遵守质量守恒定律，没有例外。D 错：加入的稀盐酸质量远大于减少的质量，减少的质量只等于逸出的二氧化碳的质量（反应物中还有碳酸钠）。","options":["生成的二氧化碳逸散到空气中，该反应仍然遵守质量守恒定律","反应放出了热量，一部分物质变成了能量，所以质量减小","碳酸钠与稀盐酸的反应不遵守质量守恒定律","减少的质量等于加入的稀盐酸的质量"],"difficulty":1,"tags":["质量守恒定律","气体逸出","实验解释"]},{"id":"chem-equation-1-q5","type":"choice","stem":"甲、乙两套装置如图所示。要验证质量守恒定律，可以选用的装置及理由是","answer":"B","explain":"碳酸钠与稀盐酸反应生成二氧化碳，甲是敞口烧杯，气体逸出后总质量变小，不能验证；乙用带气球的锥形瓶把气体收集在装置内，反应前后称量对象相同，总质量不变，可以用来验证，B 正确。A 错在只看现象明显，忽略了气体逸出。C 错：敞口装置有气体跑掉，两次称量结果不相等。D 错：有气体参加或生成的反应只要在密闭容器中进行，同样可以验证质量守恒。","options":["选甲，因为反应在烧杯中进行，现象最明显","选乙，因为反应生成气体，必须在密闭容器中称量，气体不会跑掉","甲和乙都可以，只要反应前后各称量一次就行","甲和乙都不行，质量守恒定律只能用没有气体参加的反应验证"],"difficulty":2,"tags":["质量守恒定律","装置评价","密闭容器"],"figure":{"id":"fig-chem-equation-1-q5","title":"甲、乙两套实验装置","caption":"甲是敞口烧杯，乙是瓶口套气球的密闭锥形瓶","view":"wide","alt":"左边甲是盛有液体的敞口烧杯，液面上有气泡冒出，右边乙是瓶口套着气球的锥形瓶，瓶内液体冒气泡","prims":[{"t":"text","x":23,"y":18,"text":"甲","size":4},{"t":"beaker","x":10,"y":24,"w":26,"h":24,"fill":0.45},{"t":"dot","x":16,"y":40,"hollow":true},{"t":"dot","x":22,"y":34,"hollow":true},{"t":"dot","x":28,"y":43,"hollow":true},{"t":"text","x":23,"y":58,"text":"敞口烧杯","size":3.2},{"t":"text","x":70,"y":6,"text":"乙","size":4},{"t":"flask","x":70,"y":36,"kind":"conical","h":30,"w":24,"liquid":0.5,"color":"colorless"},{"t":"rect","x":66.3,"y":23.5,"w":7.4,"h":3.5,"fill":true,"tone":"main"},{"t":"circle","cx":70,"cy":14,"r":5.5,"tone":"accent","label":"气球"},{"t":"text","x":70,"y":58,"text":"密闭锥形瓶","size":3.2}]}},{"id":"chem-equation-1-q6","type":"fill","stem":"加热 24.5 g 氯酸钾与 1 g 二氧化锰的混合物制取氧气，完全反应后冷却，称得剩余固体的质量为 15.9 g，则生成氧气的质量为 ______ g。","answer":"9.6|9.6g|9.6 g","explain":"二氧化锰是催化剂，反应前后质量不变，反应前后固体减少的质量就是逸出的氧气：24.5 g + 1 g − 15.9 g = 9.6 g。用方程式核对：2KClO₃ 为 245，生成的 3O₂ 为 96，245 : 96 = 24.5 g : 9.6 g，正好相符。若把 24.5 g − 15.9 g = 8.6 g 当作氧气质量，就漏掉了二氧化锰这 1 g。","difficulty":2,"tags":["质量守恒定律","质量差法"]},{"id":"chem-equation-1-q7","type":"short","stem":"实验室加热 24.5 g 氯酸钾与 1 g 二氧化锰的混合物制取氧气，完全反应后冷却，称得剩余固体的质量为 15.9 g。请计算：（1）生成氧气的质量；（2）生成氯化钾的质量。","answer":"（1）生成氧气 9.6 g；（2）生成氯化钾 14.9 g。","explain":"两步都靠同一个方程式：2KClO₃ 为 245，2KCl 为 149，3O₂ 为 96，三者之和 149 + 96 = 245，说明配平正确。求氧气时用质量差最快，因为二氧化锰作为催化剂质量不变，减少的固体质量只来自逸出的氧气；求氯化钾时必须用比例式，因为剩余固体 15.9 g 里还含着 1 g 二氧化锰，不能直接把 15.9 g 当成氯化钾的质量。","difficulty":2,"tags":["质量守恒定律","化学方程式计算","质量差法"],"rubric":["设未知量，写清物质与单位（设生成氯化钾 x、生成氧气 y）","化学方程式配平且条件（二氧化锰作催化剂、加热）正确","相对分子质量乘系数：2KClO₃ 为 245、2KCl 为 149、3O₂ 为 96","用质量差法或质量守恒求出氧气 9.6 g","列比例式 245/149 = 24.5 g/x 并解出 14.9 g","答案带单位、有完整答句"],"steps":["设未知量：设生成氯化钾的质量为 x，生成氧气的质量为 y。","写出化学方程式：2KClO₃ —MnO₂、加热→ 2KCl + 3O₂↑。","算相对分子质量总和：2KClO₃ 为 2×(39 + 35.5 + 16×3) = 245，2KCl 为 2×(39 + 35.5) = 149，3O₂ 为 3×32 = 96。","求氧气质量：二氧化锰是催化剂，质量不变，固体减少的质量就是逸出的氧气，y = 24.5 g + 1 g − 15.9 g = 9.6 g。","列比例式求氯化钾：245/149 = 24.5 g/x，解得 x = 24.5 g × 149 ÷ 245 = 14.9 g。","作答：生成氧气 9.6 g，生成氯化钾 14.9 g；用质量守恒检验 14.9 g + 1 g = 15.9 g，与题给的剩余固体质量相符。"]},{"id":"chem-equation-1-q8","type":"short","stem":"把 10 g 碳酸钙放入足量稀盐酸中，充分反应后碳酸钙全部溶解。请计算：（1）生成二氧化碳的质量；（2）生成氯化钙的质量。","answer":"（1）生成二氧化碳 4.4 g；（2）生成氯化钙 11.1 g。","explain":"盐酸是足量的，说明 10 g 碳酸钙全部参加反应，可以直接代入方程式。两个比例式的分母都是 CaCO₃ 的 100，分子分别换成 CO₂ 的 44 与 CaCl₂ 的 111。常见错误是把 CaCl₂ 写成 CaCl（下标漏写），那样相对分子质量会算成 75.5，结果全错。","difficulty":2,"tags":["质量守恒定律","化学方程式计算"],"rubric":["设未知量并写清物质与单位","化学方程式配平（CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑），气体符号正确","算对相对分子质量：100、111、44","列出正确的比例式并解出 4.4 g","求出氯化钙 11.1 g","答案带单位、有完整答句"],"steps":["设未知量：设生成二氧化碳的质量为 x，生成氯化钙的质量为 y。","写出化学方程式：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量：CaCO₃ 为 40 + 12 + 48 = 100，CaCl₂ 为 40 + 35.5×2 = 111，CO₂ 为 12 + 32 = 44。","列比例式求二氧化碳：100/44 = 10 g/x，解得 x = 10 g × 44 ÷ 100 = 4.4 g。","列比例式求氯化钙：100/111 = 10 g/y，解得 y = 10 g × 111 ÷ 100 = 11.1 g。","作答：生成二氧化碳 4.4 g，生成氯化钙 11.1 g。"]},{"id":"chem-equation-1-q9","type":"short","stem":"某小组想用有气体生成的化学反应验证质量守恒定律。请帮他们设计实验方案：写出选用的药品与装置、主要操作步骤、观察到的现象和结论，并说明装置为什么这样选择。","answer":"药品与装置：碳酸钠粉末、稀盐酸、锥形瓶、单孔橡皮塞、气球、托盘天平。操作：把盛有碳酸钠的小试管斜放入锥形瓶，倒入稀盐酸使两者暂不接触，塞紧带气球的橡皮塞，称量总质量 m₁；取下锥形瓶并倾斜，使碳酸钠与稀盐酸接触，观察现象；待反应结束后再称量总质量 m₂。现象：溶液中产生大量气泡，气球胀大，m₁ = m₂。结论：有气体生成的化学反应同样遵守质量守恒定律。装置这样选是因为反应会放出二氧化碳，必须用密闭装置把气体留在称量范围内，否则气体逸出会使总质量变小。","explain":"这道题的关键不是「怎么做」，而是「为什么这样做」：凡是气体参加或生成的反应，只有在密闭容器中才能把参加反应与生成的物质全部纳入称量范围。若只写「把碳酸钠和盐酸放进烧杯称量」，气体逸出后质量变小，实验结论就与质量守恒定律矛盾，属于方案性错误。","difficulty":2,"tags":["质量守恒定律","实验探究","密闭容器"],"rubric":["药品选择有气体生成的反应，装置中有密闭措施（带塞子与气球的锥形瓶）","写清操作顺序：先称量、再让药品接触、反应后再次称量","写出观察到的现象（产生气泡、气球胀大、两次质量相等）","由现象得出结论：有气体生成的反应也遵守质量守恒定律","说明装置理由：二氧化碳必须留在装置内，敞口会使质量偏小"]},{"id":"chem-equation-1-q10","type":"short","stem":"图中左边的方框里画出了反应前 2 个氢分子和 1 个氧分子的粒子模型。请在右边的方框中画出它们恰好完全反应后的粒子模型，并写出该反应的化学方程式（标出反应条件）。","answer":"反应后生成 2 个水分子，每个水分子由 1 个氧原子和 2 个氢原子构成，共 4 个氢原子、2 个氧原子，与反应前完全一致。化学方程式为 2H₂ + O₂ —点燃→ 2H₂O。","explain":"作图题先数原子再画分子：反应前有 4 个氢原子、2 个氧原子，反应后必须还是这 6 个原子，只能组成 2 个水分子。写方程式时系数要与图一致——图画了 2 个 H₂、1 个 O₂、2 个 H₂O，方程式就必须是 2H₂ + O₂ —点燃→ 2H₂O，写成 H₂ + O₂ —点燃→ H₂O 既没配平也与图不符。","difficulty":2,"tags":["质量守恒定律","微观粒子","作图题"],"rubric":["画出 2 个水分子，每个水分子由 1 个氧原子和 2 个氢原子组成（原子种类与个数正确）","反应后氢原子共 4 个、氧原子共 2 个，与反应前相等（体现质量守恒）","写出 2H₂ + O₂ —点燃→ 2H₂O，系数正确","标出反应条件「点燃」，不标气体符号（水在常温下是液体）"],"figure":{"id":"fig-chem-equation-1-q10","title":"反应前的粒子模型（反应后的方框待画）","caption":"左边方框是反应前的粒子，右边方框留空，请画出反应后的粒子模型","view":"wide","alt":"左边方框里有两个氢分子和一个氧分子，右边是空方框，等待画出反应后的粒子模型","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":40,"dashed":true},{"t":"text","x":26,"y":8,"text":"反应前","size":3.6},{"t":"molecule","x":14,"y":22,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":36,"y":22,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":24,"y":44,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"rect","x":54,"y":12,"w":40,"h":40,"dashed":true},{"t":"text","x":74,"y":8,"text":"反应后（请画）","size":3.6}]},"answerFigure":{"id":"fig-chem-equation-1-q10-a","title":"参考答案：反应后的粒子模型","caption":"反应后生成 2 个水分子，与 2H₂ + O₂ —点燃→ 2H₂O 一一对应","view":"wide","alt":"左边方框是反应前的两个氢分子和一个氧分子，右边方框里画了两个水分子，每个水分子由一个氧原子和两个氢原子构成","prims":[{"t":"rect","x":6,"y":12,"w":40,"h":40,"dashed":true},{"t":"text","x":26,"y":8,"text":"反应前","size":3.6},{"t":"molecule","x":14,"y":22,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":36,"y":22,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":24,"y":44,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"rect","x":54,"y":12,"w":40,"h":40,"dashed":true},{"t":"text","x":74,"y":8,"text":"反应后","size":3.6},{"t":"molecule","x":66,"y":22,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":84,"y":40,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":74,"y":58,"text":"2H₂ + O₂ —点燃→ 2H₂O","size":3.4}]}},{"id":"chem-equation-1-m1-q1","type":"short","stem":"写出甲组实验中发生反应的化学方程式，并说明甲组实验观察到的溶液颜色变化。（3 分）","answer":"Fe + CuSO₄ —→ FeSO₄ + Cu；蓝色溶液逐渐变成浅绿色。","explain":"","tags":["质量守恒定律","化学方程式","现象描述"],"rubric":["化学式与下标正确，方程式配平（1 分）","写出「蓝色溶液变成浅绿色」，并指出铁钉表面覆盖红色的铜（2 分）"]},{"id":"chem-equation-1-m1-q2","type":"short","stem":"乙组为什么要在瓶口套一只气球？如果去掉气球，反应后称量的结果会怎样变化？为什么？（4 分）","answer":"碳酸钠与稀盐酸反应生成二氧化碳气体，气球把气体收集在密闭装置内，保证反应前后称量的对象相同，总质量不变。去掉气球后，二氧化碳逸散到空气中，反应后称得的总质量比反应前小，减少的质量就是逸出的二氧化碳的质量；这不是质量守恒定律不成立，而是气体离开了称量范围。","explain":"","tags":["质量守恒定律","实验评价","密闭容器"],"rubric":["指出反应生成二氧化碳，需要密闭（1 分）","说明去掉气球后质量变小（1 分）","给出原因是二氧化碳逸散到空气中（1 分）","说明质量守恒定律仍然成立，减少的质量等于逸出气体的质量（1 分）"]},{"id":"chem-equation-1-m1-q3","type":"short","stem":"用质量守恒定律解释丙组镁条燃烧后固体质量增大的现象，并判断材料三中那位同学的总结是否正确，说明理由。（4 分）","answer":"镁在空气中燃烧时与氧气化合生成氧化镁，参加反应的氧气变成了固体的一部分，所以固体质量比原来的镁条大；把参加反应的氧气也算进去，反应前后总质量相等。材料三的总结不正确：质量变小的原因通常是气体逸出（如二氧化碳、氢气跑掉），并不是质量守恒定律不适用；一切化学反应都遵守质量守恒定律。","explain":"","tags":["质量守恒定律","说理","元素守恒"],"rubric":["写出 2Mg + O₂ —点燃→ 2MgO 并指出氧气参加了反应（2 分）","指出质量变小是因为气体逸出，而不是定律不适用（1 分）","明确「一切化学反应都遵守质量守恒定律」（1 分）"]}]},{"id":"chem-equation-2","title":"化学方程式的意义与书写","subtitle":"人教版九年级 · 第五单元 化学方程式 · 9a","grade":"9a","tags":["人教版九年级 · 第五单元 化学方程式"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第五单元 化学方程式 · 9a"},{"type":"note","title":"问题切入","text":"化学式已经能表示一种物质了，为什么还要写化学方程式？一个式子凭什么能同时告诉我们「发生了什么反应」和「能生成多少物质」？"},{"type":"note","title":"一句话抓住关键","text":"化学方程式是用化学式表示化学反应的式子，它同时给出三重信息：质的关系（哪些物质参加、生成哪些物质、什么条件）、量的关系（各物质的粒子个数比与质量比）、以及微观的原子守恒。书写口诀是「写、配、标、等」：写化学式、配平、标条件与↑↓、把短线改成等号。"},{"type":"h","text":"【宏观】一、化学方程式告诉了我们什么"},{"type":"p","text":"以 2H₂ + O₂ —点燃→ 2H₂O 为例。质的关系：氢气和氧气在点燃的条件下反应，生成水；量的关系：每 2 个氢分子与 1 个氧分子反应，生成 2 个水分子；质量关系：每 4 份质量的氢气与 32 份质量的氧气反应，生成 36 份质量的水，化简为 1 : 8 : 9。式子里还藏着条件「点燃」，这是方程式与数学方程最大的不同——数学方程只讲数量关系，化学方程式必须先讲清事实。"},{"type":"figure","figure":{"id":"fig-chem-equation-2-meaning","title":"化学方程式的三重信息","caption":"同一行式子读出「质」「量」「微观」三层含义","view":"wide","alt":"氢气燃烧的方程式下方依次列出粒子个数比二比一比二、质量比一比八比九，以及反应条件点燃","prims":[{"t":"text","x":50,"y":10,"text":"2H₂ + O₂ —点燃→ 2H₂O","size":5},{"t":"text","x":50,"y":22,"text":"粒子个数比：2 : 1 : 2","size":3.4},{"t":"text","x":50,"y":31,"text":"质量比：4 : 32 : 36 = 1 : 8 : 9","size":3.4},{"t":"text","x":50,"y":40,"text":"条件：点燃（写在箭头上方的位置）","size":3.4},{"t":"text","x":50,"y":50,"text":"反应前后原子个数相等，遵循质量守恒定律","size":3.2,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"凡是化学方程式都要同时把这三层读出来","size":3}]}},{"type":"note","title":"","text":"「质的关系」必须与实验事实一致：氢气燃烧生成水，不能写成生成过氧化氢。「量的关系」读的时候要带单位说清是「份质量」，不能把质量比说成相对分子质量之比。"},{"type":"h","text":"【微观】二、微观上一看就明白"},{"type":"p","text":"把式子翻译成粒子：2 个氢分子和 1 个氧分子在点燃时破裂成原子，4 个氢原子和 2 个氧原子重新组合成 2 个水分子。式子前面的系数就是分子的个数，化学式中的下标就是一个分子里原子的个数。理解了这一层，就明白为什么「系数不能随便改、下标更动不得」——系数是分子个数，改下标就是把物质都改掉了。"},{"type":"figure","figure":{"id":"fig-chem-equation-2-micro","title":"系数是分子个数，下标是原子个数","caption":"2 个 H₂ 与 1 个 O₂ 生成 2 个 H₂O，两边各 4 个氢原子、2 个氧原子","view":"wide","alt":"左边两个氢分子和一个氧分子，右边两个水分子，两边氢原子都是四个、氧原子都是两个","prims":[{"t":"molecule","x":12,"y":14,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":12,"y":36,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":32,"y":25,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"arrow","x1":44,"y1":25,"x2":56,"y2":25,"label":"点燃","labelDy":-4},{"t":"molecule","x":72,"y":16,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":72,"y":38,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":50,"y":57,"text":"系数 = 分子个数，下标 = 一个分子里的原子个数","size":3}]}},{"type":"note","title":"","text":"系数与下标是两个完全不同的东西：2H₂O 中「2」表示 2 个水分子，「2」在 H 的右下角表示每个水分子含 2 个氢原子。数原子时要同时用上它们。"},{"type":"h","text":"【符号】三、书写原则与「写、配、标、等」四步"},{"type":"p","text":"两条原则：一是必须以客观事实为依据，不能凭空臆造不存在的反应和物质（如不能写「水变成汽油」）；二是必须遵守质量守恒定律，等号两边的原子种类与数目必须相等。具体步骤是四步——写：正确写出反应物与生成物的化学式，中间用短线连接；配：配平，使两边原子个数相等，只能改化学式前面的系数；标：标出反应条件，生成气体标 ↑、生成沉淀标 ↓；等：把短线改成等号，得到完整的化学方程式。"},{"type":"figure","figure":{"id":"fig-chem-equation-2-steps","title":"书写四步：写、配、标、等","caption":"每一步都要过关，缺一步就扣分","view":"wide","alt":"板书列出书写化学方程式的四个步骤，写化学式、配平、标条件与气体沉淀符号、把短线改成等号","prims":[{"t":"text","x":50,"y":10,"text":"写、配、标、等","size":5},{"t":"text","x":50,"y":22,"text":"写：写出反应物、生成物的化学式，中间用短线","size":3.2},{"t":"text","x":50,"y":31,"text":"配：配平，使两边各元素原子个数相等（只改系数）","size":3.2},{"t":"text","x":50,"y":40,"text":"标：标出反应条件，气体标 ↑、沉淀标 ↓","size":3.2},{"t":"text","x":50,"y":49,"text":"等：把短线改成等号，完成化学方程式","size":3.2},{"t":"text","x":50,"y":58,"text":"原则：以客观事实为依据 + 遵守质量守恒定律","size":3,"tone":"accent"}]}},{"type":"note","title":"","text":"「标」这一步最容易漏：漏写条件、该标 ↑ 不标、不该标 ↑ 乱标，是中考化学用语题最常见的三类失分点。"},{"type":"h","text":"【应用】四、常见错误与检查办法"},{"type":"p","text":"写完方程式后按三步自查：第一查化学式对不对（下标有没有写错，如 CaCl₂ 不能写成 CaCl、Fe₂O₃ 不能写成 FeO）；第二查配平（两边每种元素的原子个数是否相等，系数是否最简整数比）；第三查条件与符号（条件有没有漏、气体沉淀符号用得对不对）。把这三个动作固定下来，方程式书写题基本不会丢分。"},{"type":"figure","figure":{"id":"fig-chem-equation-2-check","title":"方程式自查三步","caption":"先查化学式，再查配平，最后查条件与符号","view":"wide","alt":"板书列出检查化学方程式的三个步骤，检查化学式、检查配平、检查条件与气体沉淀符号","prims":[{"t":"text","x":50,"y":12,"text":"查化学式：下标不能错","size":4},{"t":"text","x":50,"y":26,"text":"查配平：两边每种元素的原子个数相等","size":4},{"t":"text","x":50,"y":40,"text":"查条件与符号：点燃、加热、高温、通电、催化剂，↑ 与 ↓","size":3.4},{"t":"text","x":50,"y":55,"text":"三查都通过，才是规范的化学方程式","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"不写条件的方程式在中考直接不给分，所以「条件」不是可写可不写的补充说明，而是方程式的一部分。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["化学方程式的意义（质量比）","各物质的质量比 = 各物质的相对分子质量（或相对原子质量）×化学式前面的系数之比","质量比是无单位的比值，也可读成「每 4 份质量的氢气与 32 份质量的氧气生成 36 份质量的水」 · 用于读方程式、按方程式做计算、判断质量增减。一定要乘系数：2H₂ + O₂ —点燃→ 2H₂O 中氢气与氧气的质量比是 4 : 32 = 1 : 8，而不是 2 : 32。"],["书写四步（写、配、标、等）","写化学式 → 配平 → 标条件与 ↑↓ → 把短线改成等号","无 · 适用于一切化学方程式的书写与检查。配平只能改化学式前面的系数；条件必须写对（点燃、加热、高温、通电、催化剂）；反应物中没有气体而生成物中有气体时标 ↑，溶液中生成沉淀标 ↓。"],["↑ 与 ↓ 的使用规则","气体符号 ↑：反应物中无气体、生成物中有气体时标；沉淀符号 ↓：溶液中反应生成沉淀时标","无 · 反应物中已有气体（如 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂ 中的 CO）时，生成的气体不标 ↑；不在溶液中进行的反应（如固体加热）生成的固体不标 ↓。这两种符号用于说明物质的状态，不能随意添加。"],["方程式与数学方程的区别","化学方程式表示客观存在的化学反应，条件与物质都必须真实；数学方程只表示数量关系","无 · 用来提醒自己两条原则：以客观事实为依据，不能臆造物质；遵守质量守恒定律，两边原子个数必须相等。凡是「为了配平面改下标」的写法都违反第一条原则。"]]},{"type":"h","text":"应用 · 从现象到方程式的完整流程"},{"type":"note","title":"情境","text":"把一段光亮的铜丝放在酒精灯上加热，铜丝表面变黑。请写出反应的化学方程式，并说明你是怎么确定产物与条件的。"},{"type":"list","title":"解答步骤","items":["确定反应物与生成物：Cu + O₂ → CuO。","配平：先配氧，右边 1 个氧原子是奇数，CuO 前配 2，再在 Cu 前配 2。","标条件：「加热」写在箭头上方，反应物中有气体（氧气），产物是固体，不标 ↑。","写成完整方程式：2Cu + O₂ —加热→ 2CuO。"]},{"type":"note","title":"结论","text":"2Cu + O₂ —加热→ 2CuO，铜丝表面变黑是生成了氧化铜。"},{"type":"h","text":"应用 · 用电解水的数据检验方程式"},{"type":"note","title":"情境","text":"电解水实验中，正极收集到 8 mL 气体，负极收集到 16 mL 气体。写出方程式，并说明能不能把体积比 1 : 2 当作质量比用。"},{"type":"list","title":"解答步骤","items":["写出方程式：2H₂O —通电→ 2H₂↑ + O₂↑。","标出条件「通电」，反应物中没有气体，因此生成的两种气体都要标 ↑。","算质量比：2H₂ 为 4，O₂ 为 32，质量比 4 : 32 = 1 : 8。","结论：体积比 2 : 1（氢气 : 氧气）与质量比 8 : 1（氢气 : 氧气）完全不同，不能混用。"]},{"type":"note","title":"结论","text":"2H₂O —通电→ 2H₂↑ + O₂↑；体积比 1 : 2 说的是「正极 : 负极」，质量比是氢气 : 氧气 = 1 : 8。"},{"type":"h","text":"应用 · 按质量比计算生成水的质量"},{"type":"note","title":"情境","text":"4 g 氢气在足量氧气中完全燃烧，能生成多少克水？"},{"type":"list","title":"解答步骤","items":["写出方程式：2H₂ + O₂ —点燃→ 2H₂O。","算相对分子质量总和：2H₂ 为 4，2H₂O 为 36，质量比 4 : 36 = 1 : 9。","列比例式：4/36 = 4 g/x，解得 x = 4 g × 36 ÷ 4 = 36 g。","同时可求氧气的质量：4/32 = 4 g/y，y = 32 g；检验 4 g + 32 g = 36 g，与质量守恒相符。"]},{"type":"note","title":"结论","text":"生成水 36 g（同时消耗氧气 32 g）。"},{"type":"h","text":"实验 1 · 加热高锰酸钾制取氧气（从现象写出化学方程式）"},{"type":"note","title":"实验目的","text":"通过实验现象确认反应事实，并据此写出规范、配平、条件正确的化学方程式"},{"type":"list","title":"实验器材","items":["铁架台","试管","单孔橡皮塞","导管","水槽","集气瓶","酒精灯","高锰酸钾","棉花"]},{"type":"figure","figure":{"id":"fig-chem-equation-2-exp1","title":"加热高锰酸钾制取氧气","caption":"试管口略向下倾斜，试管口塞一团棉花，用排水法收集氧气","view":"wide","alt":"铁架台夹住倾斜的试管，试管口略向下倾斜，酒精灯在试管下方加热，导管伸到水槽中倒置的集气瓶口","prims":[{"t":"stand","x":20,"y":44,"h":34,"clamps":[0.62]},{"t":"testTube","x":38,"y":22,"h":34,"w":10,"tilt":80},{"t":"circle","cx":45,"cy":17,"r":2,"tone":"muted"},{"t":"alcoholLamp","x":34,"y":42,"lit":true,"label":"酒精灯"},{"t":"curve","points":[[42,18],[62,14],[66,30]],"arrow":true},{"t":"gasJar","x":72,"y":40,"w":18,"h":24,"liquid":0.6,"color":"colorless","label":"集气瓶"},{"t":"text","x":90,"y":18,"text":"棉花","size":3.2}]}},{"type":"list","title":"实验步骤","items":["检查装置的气密性：把导管口浸入水中，用手紧握试管，看导管口是否有气泡冒出。","把高锰酸钾装入试管，在试管口放一团棉花，用带导管的单孔橡皮塞塞紧。","把试管固定在铁架台上，试管口略向下倾斜，导管口伸到水槽中集气瓶口。","点燃酒精灯，先均匀预热再对准药品部位集中加热，用排水法收集氧气。","收集满后先把导管移出水面，再熄灭酒精灯。"]},{"type":"note","title":"实验现象","text":"紫黑色固体逐渐减少，导管口有连续气泡冒出；集气瓶中的水被排尽，收集到的气体能使带火星的木条复燃。"},{"type":"note","title":"实验结论","text":"加热高锰酸钾能生成氧气，化学方程式为 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。"},{"type":"list","title":"注意事项","items":["试管口必须略向下倾斜，防止冷凝水倒流到热的试管底部使试管炸裂。","试管口要放一团棉花，防止高锰酸钾粉末进入导管造成堵塞。","实验结束必须先把导管移出水面再熄灭酒精灯，顺序颠倒会引起水倒吸使试管炸裂。","导管只需伸到集气瓶口，伸入瓶内会使收集的气体不纯、也不便观察。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2H₂ + O₂ —点燃→ 2H₂O","点燃","产生淡蓝色火焰，放出大量的热，干冷烧杯内壁出现水雾","配平要点：右边 H₂O 中氧原子是 1 个（奇数），先在 H₂O 前添 2 使氧原子变偶数，再在 H₂ 前配 2。质量比 4 : 32 : 36 = 1 : 8 : 9，粒子个数比 2 : 1 : 2，两者不要混。"],["C + O₂ —点燃→ CO₂","点燃","剧烈燃烧，发出白光，放出热量，生成能使澄清石灰水变浑浊的气体","配平要点：系数全为 1，化学式前面的系数 1 省略不写。碳在氧气不足时生成一氧化碳，方程式为 2C + O₂ —点燃→ 2CO，条件相同但产物不同，书写必须以事实为依据。"],["2H₂O —通电→ 2H₂↑ + O₂↑","通电","两极上都有气泡产生；负极产生的气体能燃烧并发出淡蓝色火焰，正极产生的气体能使带火星的木条复燃，两种气体的体积比约为 2 : 1","配平要点：先在 H₂ 前配 2，再数氧原子确认两边都是 2 个。反应物中没有气体，生成的气体都要标 ↑；氢气与氧气的体积比是 2 : 1，质量比是 4 : 32 = 1 : 8，不要把体积比当质量比。"],["CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","常温（不需加热）","固体逐渐溶解，表面产生大量气泡，气体通入澄清石灰水会变浑浊","配平要点：系数为 1、2、1、1、1，两边钙、碳、氧、氢、氯原子个数相等；化学式要点：氯化钙中钙与氯的个数比是 1 : 2，必须写成 CaCl₂，写成 CaCl 就是教错；生成的气体标 ↑。这就是实验室制取二氧化碳的原理。"],["CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O","点燃","产生明亮的蓝色火焰，放出大量的热，干冷烧杯内壁出现水雾，澄清石灰水变浑浊","配平要点：观察法，从组成最复杂的 CH₄ 入手——先看碳配 1 个 CO₂，再看氢 4 个配 2 个 H₂O，最后数右边氧原子 2 + 2 = 4，在 O₂ 前配 2。本式与 2H₂ + O₂ —点燃→ 2H₂O 都体现「含氢物质燃烧生成水」。"],["2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑","加热","紫黑色固体逐渐减少，导管口有连续气泡冒出，集气瓶中收集到能使带火星木条复燃的气体","配平要点：先配钾——右边 K₂MnO₄ 中钾有 2 个，KMnO₄ 前配 2；再数氧原子，左边 2×4 = 8 个，右边 4 + 2 + 2 = 8 个，自动配平。生成的气体标 ↑，试管口要放一团棉花。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["为了把 H₂ + O₂ —点燃→ H₂O 配平，可以把 H₂O 写成 H₂O₂","只能改化学式前面的系数，写成 2H₂ + O₂ —点燃→ 2H₂O","H₂O₂ 是过氧化氢，与水是两种完全不同的物质，改下标等于把生成物改掉了，违反「以客观事实为依据」这条原则。配平的唯一手段是在化学式前面添系数。"],["化学方程式里两边原子个数已经相等了，反应条件可以不写","条件必须写，而且写错或不写在中考直接不给分","同一个反应在不同条件下产物可能不同（碳在氧气充足时生成 CO₂，不足时生成 CO），条件本身就是化学方程式所表达的事实的一部分，不是补充说明。"],["只要生成物中有气体，就要在化学式后面标 ↑","只有反应物中没有气体而生成物中有气体时才标 ↑","↑ 的作用是说明气体是新生成并逸出的。像 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂ 中 CO 本身是气体，生成的 CO₂ 也是气体，就没有必要标 ↑。"],["化学方程式两边的质量比就是相对分子质量之比","质量比是「相对分子质量 × 系数」之比","系数表示分子的个数，2 个水分子当然比 1 个水分子重一倍。漏乘系数会把 2H₂ 的质量算成 2 而不是 4，比例式随之全错。"]]},{"type":"table","title":"化学方程式与数学方程（两种「式子」表达的东西有什么不同）","head":["比较项","化学方程式","数学方程"],"rows":[["表示什么","客观存在的化学反应，含物质、条件、现象","数量之间的相等关系"],["等号的含义","两边原子种类与数目相等（质量守恒）","等号两边数值相等"],["能不能改","系数可配平，下标绝对不能改","可以移项、合并同类项、两边同乘同除"],["必须写清","反应条件、气体与沉淀符号","未知数与解的范围"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["判断化学方程式书写正误（配图或不配图）","给出四个方程式选出书写正确的一个，或指出某个方程式错在哪里。错误往往集中在这几处：化学式下标写错（CaCl、FeO）、没配平、漏写或写错条件、↑↓ 用错。答题要指出错误类别，不能只说「错了」。"],["由实验现象或微观示意图写方程式","给出实验现象描述或粒子模型图，要求写出对应的化学方程式。做题顺序：先确定反应物与生成物，再配平，最后补条件与符号。粒子模型题还要让方程式系数与图中粒子个数一一对应。"],["方程式意义的表述（质量比与粒子个数比）","要求写出某方程式中各物质的质量比、粒子个数比，或判断对读法的描述是否规范。质量比要乘系数，粒子个数比就是系数比，两者不能互换，这是最常见的失分点。"]]},{"type":"quote","text":"【材料一】化学小组做了三个实验：① 在酒精灯上加热铜丝，铜丝表面变黑；② 电解水，负极收集到可燃气体、正极收集到能使带火星木条复燃的气体；③ 把石灰石放入稀盐酸中，固体溶解并产生大量气泡。\n【材料二】作业中出现了下列三种写法：\n甲：H₂ + O₂ —点燃→ H₂O\n乙：2H₂O —通电→ 2H₂ + O₂\n丙：CaCO₃ + HCl —→ CaCl₂ + H₂O + CO₂↑","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】写出实验①②③对应的化学方程式（要标出反应条件，气体与沉淀符号按规范标注）。（6 分）","【设问】指出材料二中甲、乙、丙三个方程式各自的错误，并写出改正后的方程式。（5 分）","【设问】根据 2H₂O —通电→ 2H₂↑ + O₂↑ 计算：36 g 水完全分解，可得到氢气和氧气各多少克？（4 分）"]}],"questions":[{"id":"chem-equation-2-q1","type":"choice","stem":"图是氢气在氧气中燃烧的粒子模型示意图。下列说法正确的是","answer":"C","explain":"图中 2 个氢分子与 1 个氧分子反应生成 2 个水分子，分子个数比是 2 : 1 : 2，C 正确。A 错：2 : 1 是分子个数比，质量比要用 2H₂ 的 4 与 O₂ 的 32 相比，是 4 : 32 = 1 : 8，把个数比当成质量比是本题最大的陷阱。B 错：反应前 3 个分子、反应后 2 个分子，分子总数改变了。D 错：2 个水分子中共有 4 个氢原子和 2 个氧原子，氢原子数漏乘了系数与下标。","options":["参加反应的氢气与氧气的质量比是 2 : 1","反应前后分子的总数保持不变","参加反应的氢气与氧气的分子个数比是 2 : 1","生成的 2 个水分子中共含有 2 个氢原子和 2 个氧原子"],"difficulty":2,"tags":["化学方程式","微观粒子","质量比"],"figure":{"id":"fig-chem-equation-2-q1","title":"氢气燃烧的粒子模型","caption":"2 个氢分子与 1 个氧分子生成 2 个水分子","view":"wide","alt":"左边两个氢分子和一个氧分子，右边两个水分子，两边氢原子都是四个、氧原子都是两个","prims":[{"t":"molecule","x":12,"y":16,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":12,"y":42,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":32,"y":29,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"arrow","x1":44,"y1":29,"x2":56,"y2":29,"label":"点燃","labelDy":-4},{"t":"molecule","x":74,"y":16,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":74,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":50,"y":58,"text":"分子个数比 2 : 1 : 2，质量比 4 : 32 : 36","size":3.1}]}},{"id":"chem-equation-2-q2","type":"choice","stem":"关于化学方程式 2H₂O —通电→ 2H₂↑ + O₂↑，下列说法正确的是","answer":"D","explain":"2H₂O 的相对分子质量总和是 36，2H₂ 是 4，O₂ 是 32，质量比 36 : 4 : 32，所以 D 正确。A 错：2 : 1 是氢分子与氧分子的个数比（也是体积比），质量比是 4 : 32 = 1 : 8。B 错：把粒子个数当成了质量份数，2 个水分子质量是 36 份而不是 2 份。C 错：水是纯净物，由氢、氧两种元素组成，不能说由氢气和氧气组成。","options":["水在通电的条件下分解，生成氢气与氧气的质量比是 2 : 1","每 2 份质量的水完全分解，生成 2 份质量的氢气和 1 份质量的氧气","该方程式说明水是由氢气和氧气组成的","每 36 份质量的水完全分解，生成 4 份质量的氢气和 32 份质量的氧气"],"difficulty":2,"tags":["化学方程式","意义","质量比"]},{"id":"chem-equation-2-q3","type":"choice","stem":"下列关于化学方程式书写的说法，正确的是","answer":"A","explain":"化学方程式是客观事实的符号表达，物质与反应都必须真实存在，A 正确。B 错：改下标等于换了物质，配平只能改化学式前面的系数。C 错：反应条件必须写，漏写条件在中考直接不给分。D 错：↑ 只在「反应物中没有气体、生成物中有气体」时使用，乱标与漏标一样算错。","options":["必须以客观事实为依据，不能凭空臆造不存在的反应和物质","为了配平，可以改动化学式中元素符号右下角的数字","只要两边各元素的原子个数相等，反应条件就可以省略不写","只要两边原子个数相等，生成物中的气体就可以随意标注 ↑"],"difficulty":1,"tags":["化学方程式","书写原则"]},{"id":"chem-equation-2-q4","type":"choice","stem":"下列有关化学方程式中「↑」「↓」使用的说法，正确的是","answer":"B","explain":"↑ 表示新生成的气体逸出，所以条件是「反应物中没有气体」，B 正确。A 错：反应物本身有气体时（如 CO 还原氧化铁），生成的气体不标 ↑。C 错：↑↓ 都标在化学式的后面，标在前面就成了系数，意思完全变了。D 错：反应物中有气体时反而不能标 ↑。","options":["只要生成物中有气体，就必须在气体化学式后面标 ↑","反应物中没有气体、生成物中有气体时，生成的气体要标 ↑","在溶液中进行的反应，生成的沉淀要标在化学式前面","反应物中有气体时，生成的气体也必须标 ↑ 以说明状态"],"difficulty":2,"tags":["化学方程式","书写规范","气体符号"]},{"id":"chem-equation-2-q5","type":"choice","stem":"下列化学方程式中，书写完全正确的是","answer":"C","explain":"C 化学式正确、配平正确、条件「通电」写对，且反应物中没有气体所以两种气体都标了 ↑，完全正确。A 错：两边原子个数不相等，没有配平，应写成 2H₂ + O₂ —点燃→ 2H₂O。B 错：漏写了反应条件「点燃」。D 错：配平虽然正确，但生成的气体漏标 ↑（反应物水不是气体）。","options":["H₂ + O₂ —点燃→ H₂O","2H₂ + O₂ —→ 2H₂O","2H₂O —通电→ 2H₂↑ + O₂↑","2H₂O —通电→ 2H₂ + O₂"],"difficulty":2,"tags":["化学方程式","书写正误","配平"]},{"id":"chem-equation-2-q6","type":"fill","stem":"根据 2Mg + O₂ —点燃→ 2MgO，2.4 g 镁在氧气中完全燃烧，需要氧气的质量是 ______ g。","answer":"1.6|1.6g|1.6 g","explain":"2Mg 的相对原子质量总和为 48，O₂ 为 32，质量比 48 : 32 = 3 : 2。设需要氧气质量为 x，48/32 = 2.4 g/x，解得 x = 1.6 g。检验：生成氧化镁 2.4 g + 1.6 g = 4 g，而 2MgO 为 80，48 : 80 = 2.4 g : 4 g，也相符。若算成 2.4 × 32 ÷ 24 = 3.2 g，就是把镁前面的系数 2 漏掉了。","difficulty":2,"tags":["化学方程式","质量比","化学方程式计算"]},{"id":"chem-equation-2-q7","type":"short","stem":"4 g 氢气在足量氧气中完全燃烧，能生成多少克水？","answer":"能生成 36 g 水。","explain":"本题最容易错在「漏乘系数」：若把 H₂ 的相对分子质量当成 2、水当成 18，比例式就变成 2/18 = 4 g/x，算出 36 g 是巧合，但换成别的数据一定错。正确的做法是把 2H₂ 当作 4、2H₂O 当作 36，这样比例式与质量守恒（4 g + 32 g = 36 g）才能互相对上。","difficulty":2,"tags":["化学方程式","化学方程式计算"],"rubric":["设未知量并写清物质与单位","化学方程式配平、条件「点燃」正确","相对分子质量乘系数：2H₂ 为 4、2H₂O 为 36","列比例式并解出 36 g","答案带单位、有完整答句"],"steps":["设未知量：设生成水的质量为 x。","写出化学方程式：2H₂ + O₂ —点燃→ 2H₂O。","算相对分子质量总和：2H₂ 为 2×2 = 4，2H₂O 为 2×18 = 36。","列比例式：4/36 = 4 g/x，解得 x = 4 g × 36 ÷ 4 = 36 g。","作答：生成水 36 g。（可用质量守恒检验：消耗氧气 32 g，4 g + 32 g = 36 g。）"]},{"id":"chem-equation-2-q8","type":"short","stem":"18 g 水完全电解，可以得到氢气和氧气各多少克？","answer":"可得到氢气 2 g、氧气 16 g。","explain":"电解水的三个质量 36、4、32 成比例缩放，18 g 正好是 36 g 的一半，所以氢气是 4 g 的一半即 2 g、氧气是 32 g 的一半即 16 g，这个倍数关系可以用来快速检验。若把氢气和氧气的质量写反（写成 16 g 与 2 g），说明没有对应好「2H₂ 对应 4、O₂ 对应 32」。","difficulty":1,"tags":["化学方程式","化学方程式计算"],"rubric":["设未知量并写出配平、条件正确的方程式","算对相对分子质量 36、4、32","列比例式求出氢气 2 g","求出氧气 16 g 并作答，带单位"],"steps":["设未知量：设生成氢气的质量为 x，生成氧气的质量为 y。","写出化学方程式：2H₂O —通电→ 2H₂↑ + O₂↑。","算相对分子质量：2H₂O 为 36，2H₂ 为 4，O₂ 为 32。","列比例式：36/4 = 18 g/x，得 x = 2 g；36/32 = 18 g/y，得 y = 16 g。","作答：得到氢气 2 g、氧气 16 g（检验 2 g + 16 g = 18 g）。"]},{"id":"chem-equation-2-q9","type":"short","stem":"某同学把铁钉放入硫酸铜溶液中，观察到铁钉表面出现红色物质、溶液由蓝色逐渐变成浅绿色，于是他写下 Fe + CuSO₄ —→ FeSO₄ + Cu。请评价这个方程式是否规范完整，并说明书写化学方程式的一般步骤，以及怎样用微观粒子的变化解释现象。","answer":"这个方程式是规范的：硫酸亚铁写作 FeSO₄（铁显 +2 价），铜的化学式 Cu，两边铁、铜各 1 个，硫、氧各 1 个和 4 个，已经配平；反应在常温下进行，没有气体生成也不在溶液中生成沉淀，因此不写条件、不标 ↑↓ 都是对的。书写步骤是写、配、标、等：写化学式 → 配平 → 标条件与 ↑↓ → 把短线改成等号。微观解释：铁原子把溶液中的铜离子置换出来，铁原子变成亚铁离子进入溶液，铜离子得到电子变成铜原子附着在铁钉表面，所以铁钉表面出现红色的铜，溶液中铜离子减少、亚铁离子增多，蓝色逐渐变成浅绿色；反应前后原子种类与数目不变，质量守恒。","explain":"「不写条件」不等于「漏写条件」：常温下即可进行的反应本来就没有条件可标，这与漏写「点燃」是两回事。答题时要把判断理由说清：先看反应是否真的存在，再查化学式与配平，最后查条件与符号，这样才是一套完整的评价思路。","difficulty":2,"tags":["化学方程式","实验探究","微观解释"],"rubric":["判断方程式规范完整，并说明不写条件与不标 ↑↓ 的理由（2 分）","写出书写四步（写、配、标、等）（2 分）","用微观粒子（原子与离子）的变化解释现象（2 分）","指出反应前后原子种类与数目不变（1 分）"]},{"id":"chem-equation-2-q10","type":"short","stem":"补齐并配平下列化学方程式，并在箭头上方标出反应条件（若常温下即可反应，写「常温」）。\n（1）__H₂ + __O₂ —→ __H₂O\n（2）__C + __O₂ —→ __CO₂\n（3）__H₂O —→ __H₂↑ + __O₂↑\n（4）__KMnO₄ —→ __K₂MnO₄ + __MnO₂ + __O₂↑","answer":"（1）2H₂ + O₂ —点燃→ 2H₂O；（2）C + O₂ —点燃→ CO₂；（3）2H₂O —通电→ 2H₂↑ + O₂↑；（4）2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。","explain":"四题覆盖四类常见条件，配平方法各不相同：（1）用奇偶配平法，先把 H₂O 前配 2 再配氢；（2）系数全为 1；（3）直接配氢再数氧；（4）先配钾——右边钾有 2 个，故 KMnO₄ 前配 2，再数氧自动平衡。四个小题都要检查条件有没有漏、气体符号该不该标。","difficulty":2,"tags":["化学方程式","书写规范","配平"],"rubric":["（1）配平正确并标出「点燃」（2 分）","（2）系数为 1、条件「点燃」（1 分）","（3）配平正确、条件「通电」、两种气体标 ↑（2 分）","（4）KMnO₄ 前配 2，条件「加热」，气体标 ↑（2 分）"],"answerFigure":{"id":"fig-chem-equation-2-q10-a","title":"参考答案：补齐并配平后的四个方程式","caption":"条件写在箭头上方，气体符号不遗漏","view":"wide","alt":"板书列出四个配平后的化学方程式，分别是氢气燃烧、碳燃烧、电解水和高锰酸钾受热分解","prims":[{"t":"text","x":50,"y":12,"text":"（1）2H₂ + O₂ —点燃→ 2H₂O","size":3.8},{"t":"text","x":50,"y":24,"text":"（2）C + O₂ —点燃→ CO₂","size":3.8},{"t":"text","x":50,"y":36,"text":"（3）2H₂O —通电→ 2H₂↑ + O₂↑","size":3.8},{"t":"text","x":50,"y":48,"text":"（4）2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑","size":3.8},{"t":"text","x":50,"y":58,"text":"系数为 1 的不写；常温反应不必标条件","size":3.1,"tone":"muted"}]}},{"id":"chem-equation-2-m1-q1","type":"short","stem":"写出实验①②③对应的化学方程式（要标出反应条件，气体与沉淀符号按规范标注）。（6 分）","answer":"① 2Cu + O₂ —加热→ 2CuO；② 2H₂O —通电→ 2H₂↑ + O₂↑；③ CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑（常温，不需写条件）。","explain":"","tags":["化学方程式","书写规范"],"rubric":["① 化学式正确、配平（2 分）","② 配平正确，两种气体都标 ↑，条件写「通电」（2 分）","③ 化学式 CaCl₂ 与 CaCO₃ 下标正确、配平、气体标 ↑（2 分）"]},{"id":"chem-equation-2-m1-q2","type":"short","stem":"指出材料二中甲、乙、丙三个方程式各自的错误，并写出改正后的方程式。（5 分）","answer":"甲没配平，应改为 2H₂ + O₂ —点燃→ 2H₂O。乙生成的气体没有标 ↑（反应物中没有气体），应改为 2H₂O —通电→ 2H₂↑ + O₂↑。丙有两个错误：一是盐酸的化学式漏了下标，应写 HCl 前配 2，二是氯化钙漏写下标，应写 CaCl₂；改正后为 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","explain":"","tags":["化学方程式","常见错误","配平"],"rubric":["甲：指出未配平并改正（1 分）","乙：指出生成气体未标 ↑ 并改正（2 分）","丙：指出 HCl 前要配 2（1 分）","丙：指出 CaCl₂ 下标错误并改正（1 分）"]},{"id":"chem-equation-2-m1-q3","type":"short","stem":"根据 2H₂O —通电→ 2H₂↑ + O₂↑ 计算：36 g 水完全分解，可得到氢气和氧气各多少克？（4 分）","answer":"可得到氢气 4 g、氧气 32 g。","explain":"","tags":["化学方程式","化学方程式计算"],"rubric":["设未知量并写出配平正确的方程式（1 分）","算对相对分子质量 36、4、32（1 分）","列出比例式并求出氢气 4 g（1 分）","求出氧气 32 g，答案带单位（1 分）"],"steps":["设未知量：设生成氢气的质量为 x，生成氧气的质量为 y。","写出化学方程式：2H₂O —通电→ 2H₂↑ + O₂↑。","算相对分子质量：2H₂O 为 36，2H₂ 为 4，O₂ 为 32。","列比例式：36/4 = 36 g/x，得 x = 4 g；36/32 = 36 g/y，得 y = 32 g。","作答：生成氢气 4 g，生成氧气 32 g（检验 4 g + 32 g = 36 g，符合质量守恒）。"]}]},{"id":"chem-equation-3","title":"化学方程式的配平：四种常用方法","subtitle":"人教版九年级 · 第五单元 化学方程式 · 9a","grade":"9a","tags":["人教版九年级 · 第五单元 化学方程式"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 第五单元 化学方程式 · 9a"},{"type":"note","title":"问题切入","text":"方程式两边的原子个数不相等时，到底能在哪里动手？为什么改下标就错了，改系数就对了？四种配平方法分别该在什么时候用？"},{"type":"note","title":"一句话抓住关键","text":"配平的实质是让等号两边每种元素的原子的总数相等，而分子是由原子组成的，所以能动的只有「化学式前面的系数」（表示分子个数），绝对不能动化学式中的下标。常用方法四种：观察法、最小公倍数法、奇偶配平法、原子团整体配平；配完之后系数要化成最简整数比。"},{"type":"h","text":"【宏观】一、为什么必须配平"},{"type":"p","text":"如果不配平，「H₂ + O₂ —点燃→ H₂O」就说成「1 个氢分子加 1 个氧分子生成 1 个水分子」，可实际上反应后多出来的那个氧原子无处可去——这等于说反应前后原子凭空消失了，直接违反质量守恒定律。配平就是让式子说出的「粒子账目」与真实反应对得上。"},{"type":"figure","figure":{"id":"fig-chem-equation-3-why","title":"没配平的式子在微观上说不通","caption":"左边有 2 个氧原子，右边只有 1 个，多出来的氧原子没有去处","view":"wide","alt":"左边一个氢分子和一个氧分子，右边一个水分子，右边的氧原子比左边少一个，说明式子没有配平","prims":[{"t":"text","x":50,"y":10,"text":"H₂ + O₂ —点燃→ H₂O（未配平）","size":4},{"t":"molecule","x":20,"y":26,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":44,"y":26,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"arrow","x1":56,"y1":26,"x2":64,"y2":26},{"t":"molecule","x":82,"y":26,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":50,"y":48,"text":"右边只剩 1 个氧原子：原子数目不相等","size":3.4,"tone":"danger"},{"t":"text","x":50,"y":58,"text":"配平后：2H₂ + O₂ —点燃→ 2H₂O，两边各 4 个氢原子、2 个氧原子","size":3}]}},{"type":"note","title":"","text":"判断配平只看一件事：等号两边每种元素的原子总数是否相等。与分子的个数是否相等无关。"},{"type":"h","text":"【微观】二、系数是「分子个数」，下标是「原子个数」"},{"type":"p","text":"在 H₂O 前面写 2，表示 2 个水分子，氢原子随之增加到 4 个；把 H₂O 写成 H₂O₂，那是过氧化氢，是另一种物质，反应也就不再是这个反应了。所以配平时手上只有一件工具——在化学式前面添系数，添的系数表示分子的个数，数原子时用「系数 × 下标」。"},{"type":"figure","figure":{"id":"fig-chem-equation-3-coefficient","title":"只改系数，不改下标","caption":"H₂O 前添系数 2 得到 2 个水分子，共 4 个氢原子、2 个氧原子","view":"wide","alt":"一个水分子和两个水分子的对比，两个水分子中共有四个氢原子和两个氧原子","prims":[{"t":"text","x":22,"y":12,"text":"H₂O：1 个水分子","size":3.6},{"t":"molecule","x":22,"y":30,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"text","x":22,"y":52,"text":"2 个氢原子、1 个氧原子","size":3.2},{"t":"arrow","x1":44,"y1":30,"x2":54,"y2":30,"label":"前面添 2","labelDy":-4},{"t":"text","x":78,"y":12,"text":"2H₂O：2 个水分子","size":3.6},{"t":"molecule","x":68,"y":30,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]]},{"t":"molecule","x":88,"y":30,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]]},{"t":"text","x":78,"y":52,"text":"4 个氢原子、2 个氧原子","size":3.2}]}},{"type":"note","title":"","text":"配平后的系数必须是整数，且为最简整数比。系数 1 省略不写，但心里要记住它是 1，数原子时不能漏。"},{"type":"h","text":"【符号】三、最小公倍数法：先配出现次数少的那种原子"},{"type":"p","text":"最小公倍数法适合「一种元素在两边各只出现在一种物质里」的方程式，步骤是：找出两边该元素原子个数的最小公倍数，用最小公倍数分别除以两边的原子个数，得到两种物质的系数，再配其他元素。以铁在氧气中燃烧为例：Fe + O₂ —→ Fe₃O₄，右边氧原子 4 个、左边每 1 个 O₂ 提供 2 个，最小公倍数 4，所以 O₂ 前配 2、Fe₃O₄ 前配 1，最后看铁：右边 3 个铁原子，Fe 前配 3，得到 3Fe + 2O₂ —点燃→ Fe₃O₄。铝与氧气反应同理：Al + O₂ —→ Al₂O₃，氧两边 2 与 3 的最小公倍数是 6，O₂ 前配 3、Al₂O₃ 前配 2，再配铝得 4Al + 3O₂ —→ 2Al₂O₃。"},{"type":"figure","figure":{"id":"fig-chem-equation-3-lcm","title":"最小公倍数法配氧原子","caption":"氧原子个数 2 与 3 的最小公倍数是 6，故 O₂ 前配 3、Al₂O₃ 前配 2","view":"wide","alt":"板书给出铝与氧气反应的配平过程，先标出两边氧原子个数与最小公倍数，再确定系数四和三和二","prims":[{"t":"text","x":50,"y":10,"text":"Al + O₂ —→ Al₂O₃","size":4.4},{"t":"text","x":50,"y":22,"text":"氧原子：左边 2 个，右边 3 个，最小公倍数 6","size":3.2},{"t":"text","x":50,"y":32,"text":"O₂ 前配 6÷2 = 3，Al₂O₃ 前配 6÷3 = 2","size":3.2},{"t":"text","x":50,"y":42,"text":"再配铝：右边 2×2 = 4，Al 前配 4","size":3.2},{"t":"text","x":50,"y":54,"text":"4Al + 3O₂ —→ 2Al₂O₃","size":4.4,"tone":"accent"},{"t":"text","x":50,"y":61,"text":"铁在氧气中燃烧：3Fe + 2O₂ —点燃→ Fe₃O₄","size":3}]}},{"type":"note","title":"","text":"最小公倍数法要挑「两边各只出现一次」的那种元素，通常是氧。若某元素在两边出现多次，改用观察法。"},{"type":"h","text":"【符号】四、观察法与奇偶配平法"},{"type":"p","text":"观察法从组成最复杂的化学式入手：先定它的系数为 1，再依次配其他元素。甲烷燃烧 CH₄ + O₂ —点燃→ CO₂ + H₂O：先配碳（1 个 CO₂），再配氢（4 个氢原子配 2 个 H₂O），最后数右边氧原子 2 + 2 = 4，O₂ 前配 2。奇偶配平法专门对付「某元素原子个数一边是奇数、一边是偶数」的情形：先在含奇数个该原子的化学式前配 2 变成偶数，再依次配平。如 2C + O₂ —点燃→ 2CO，就是先把 CO 前配 2 把氧原子凑成偶数；H₂O₂ 分解 2H₂O₂ —MnO₂→ 2H₂O + O₂↑ 也是同样的思路。"},{"type":"figure","figure":{"id":"fig-chem-equation-3-odd-even","title":"奇偶配平法","caption":"先把含奇数氧原子的物质前配 2，使氧原子总数变为偶数","view":"wide","alt":"板书给出奇偶配平法的步骤，先给化学式前配二把奇数原子变偶数，再配平其它元素","prims":[{"t":"text","x":50,"y":10,"text":"奇偶配平法：先让奇数变偶数","size":4},{"t":"text","x":50,"y":24,"text":"C + O₂ —→ CO：右边氧原子 1 个（奇数）","size":3.2},{"t":"text","x":50,"y":34,"text":"先在 CO 前配 2：C + O₂ —→ 2CO","size":3.2},{"t":"text","x":50,"y":44,"text":"再配碳：2C + O₂ —点燃→ 2CO","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":56,"text":"过氧化氢分解同理：2H₂O₂ —MnO₂→ 2H₂O + O₂↑","size":3}]}},{"type":"note","title":"","text":"奇偶配平法的关键动作是「先配 2」：含奇数个原子的那种物质前先添系数 2，后面自然都是整数。若配完出现分数，把全式系数同乘一个数化成整数即可。"},{"type":"h","text":"【应用】五、原子团整体配平与检查"},{"type":"p","text":"有些反应里某种原子团（SO₄、OH、CO₃、NO₃）在两边都原样出现，就把它当成一个整体来配，能省很多事。如 Fe₂O₃ + H₂SO₄ —→ Fe₂(SO₄)₃ + H₂O：SO₄ 在右边有 3 个，左边 H₂SO₄ 前就配 3，再数氢：左边 6 个氢原子，H₂O 前配 3，氧原子自动对上。配完后的检查顺序是：每种元素的原子个数是否相等、系数是否为最简整数比、有没有出现分数系数。"},{"type":"figure","figure":{"id":"fig-chem-equation-3-radical","title":"原子团整体配平","caption":"把 SO₄ 当成一个整体，右边有 3 个，左边 H₂SO₄ 前就配 3","view":"wide","alt":"板书给出氧化铁与硫酸反应的原子团整体配平过程，硫酸前面的系数由硫酸根的个数决定","prims":[{"t":"text","x":50,"y":10,"text":"Fe₂O₃ + H₂SO₄ —→ Fe₂(SO₄)₃ + H₂O","size":3.8},{"t":"text","x":50,"y":24,"text":"把 SO₄ 当成一个整体：右边 3 个","size":3.2},{"t":"text","x":50,"y":34,"text":"H₂SO₄ 前配 3；左边氢 6 个，H₂O 前配 3","size":3.2},{"t":"text","x":50,"y":46,"text":"Fe₂O₃ + 3H₂SO₄ —→ Fe₂(SO₄)₃ + 3H₂O","size":3.8,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"检查：铁 2、硫 3、氧 15、氢 6，两边相等","size":3}]}},{"type":"note","title":"","text":"检查原子个数时不要忘记原子团里的原子：3H₂SO₄ 中氧原子是 3×4 = 12 个，加上 Fe₂O₃ 里的 3 个，左边共 15 个氧原子。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["配平的两条铁律","只能改化学式前面的系数；系数必须是最简整数比","系数是无单位的整数 · 适用于一切化学方程式的配平。改下标等于换了物质（H₂O 与 H₂O₂ 不是一种物质），所以下标不能动；配平后若出现分数（如 1/2 O₂），把全式系数同乘 2 化为整数。系数为 1 时省略不写。"],["最小公倍数法","某元素在两边各只出现一次时：该元素原子个数的最小公倍数 ÷ 左边原子个数 = 左边物质的系数","系数为整数 · 适用于两边各只出现一次的那种元素（通常是氧），如 Fe + O₂ —→ Fe₃O₄、Al + O₂ —→ Al₂O₃。若某元素在两边出现在多种物质里，或两边原子个数之比已经很简单，就不要硬套，改用观察法或奇偶配平法。"],["奇偶配平法","某元素原子个数一边为奇数、一边为偶数时，先在含奇数个该原子的化学式前配 2","系数为整数 · 适用于「一边奇数、一边偶数」的式子，如 C + O₂ —→ CO、H₂O₂ —→ H₂O + O₂。这个方法的动作只有一步——把奇数变偶数，之后按观察法依次配平其他元素。"],["原子团整体配平","把在两边都原样出现的原子团（SO₄、OH、CO₃、NO₃）当成一个整体来计数","系数为整数 · 适用于原子团没有拆开的反应，如 Fe₂O₃ + H₂SO₄ —→ Fe₂(SO₄)₃ + H₂O、Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH。注意复分解反应中原子团一般不变，而置换反应（Fe + H₂SO₄）中原子团也只是位置变化，不影响整体计数。"]]},{"type":"h","text":"应用 · 配平后按方程式进行计算"},{"type":"note","title":"情境","text":"4.8 g 镁在氧气中完全燃烧，需要消耗多少克氧气？生成多少克氧化镁？"},{"type":"list","title":"解答步骤","items":["配平：Mg + O₂ —→ MgO 中右边氧原子是奇数，MgO 前配 2，Mg 前配 2，得 2Mg + O₂ —点燃→ 2MgO。","算相对分子质量总和：2Mg 为 48，O₂ 为 32，2MgO 为 80。","列比例式求氧气：48/32 = 4.8 g/x，解得 x = 3.2 g。","列比例式求氧化镁：48/80 = 4.8 g/y，解得 y = 8 g；用质量守恒检验 4.8 g + 3.2 g = 8 g，相符。"]},{"type":"note","title":"结论","text":"需要氧气 3.2 g，生成氧化镁 8 g。"},{"type":"h","text":"应用 · 由文字信息写方程式并配平"},{"type":"note","title":"情境","text":"酒精（乙醇，化学式 C₂H₅OH）在空气中燃烧生成二氧化碳和水。请写出并配平这个反应的化学方程式。"},{"type":"list","title":"解答步骤","items":["写出骨架：C₂H₅OH + O₂ —点燃→ CO₂ + H₂O。","配碳：左边 2 个碳原子，CO₂ 前配 2。","配氢：左边 6 个氢原子，H₂O 前配 3。","配氧：右边氧原子 2×2 + 3×1 = 7 个，乙醇分子本身含 1 个氧原子，需要氧气提供 6 个，O₂ 前配 3。","检验：左边氧原子 1 + 6 = 7 个，右边 4 + 3 = 7 个，配平完成。"]},{"type":"note","title":"结论","text":"C₂H₅OH + 3O₂ —点燃→ 2CO₂ + 3H₂O。"},{"type":"h","text":"实验 1 · 铁丝在氧气中燃烧（用最小公倍数法配平方程式）"},{"type":"note","title":"实验目的","text":"观察铁丝在氧气中燃烧的现象，并由实验事实写出、配平化学方程式"},{"type":"list","title":"实验器材","items":["集气瓶（预先盛少量水或铺一层细沙）","铁丝","砂纸","火柴","酒精灯","氧气"]},{"type":"figure","figure":{"id":"fig-chem-equation-3-exp1","title":"铁丝在氧气中燃烧","caption":"铁丝在氧气中剧烈燃烧，火星四射，生成黑色固体四氧化三铁；瓶底预先放少量水或细沙","view":"wide","alt":"一根绕成螺旋状的铁丝伸入盛有氧气的集气瓶中燃烧，火星四射，瓶底预先放了少量水","prims":[{"t":"text","x":26,"y":12,"text":"铁丝绕成螺旋状","size":3.2},{"t":"text","x":26,"y":20,"text":"一端系一根火柴","size":3.2},{"t":"curve","points":[[46,8],[42,14],[50,18],[44,24],[54,30],[66,36]]},{"t":"gasJar","x":74,"y":36,"w":22,"h":26,"liquid":0.2,"color":"colorless","label":"集气瓶"},{"t":"dot","x":68,"y":30},{"t":"dot","x":76,"y":26},{"t":"dot","x":72,"y":22},{"t":"text","x":74,"y":58,"text":"瓶底放少量水或细沙","size":3}]}},{"type":"list","title":"实验步骤","items":["用砂纸打磨铁丝，除去表面的铁锈，再把铁丝绕成螺旋状，末端系一根火柴。","在集气瓶底部预先放入少量水或铺一层细沙，收集一瓶纯净的氧气。","点燃火柴，待火柴快燃尽时把铁丝缓慢伸入集气瓶中。","观察燃烧现象，燃烧结束后把铁丝取出，观察集气瓶内的现象。"]},{"type":"note","title":"实验现象","text":"铁丝剧烈燃烧，火星四射，放出大量的热，生成黑色固体；集气瓶内壁温度升高。"},{"type":"note","title":"实验结论","text":"铁与氧气在点燃条件下反应生成四氧化三铁，3Fe + 2O₂ —点燃→ Fe₃O₄。"},{"type":"list","title":"注意事项","items":["集气瓶底必须预先放少量水或铺一层细沙，防止熔融物溅落使瓶底炸裂。","铁丝要先用砂纸打磨，绕成螺旋状是为了增大与氧气的接触面积和受热面积。","必须等火柴快燃尽时再伸入，否则火柴燃烧会消耗瓶内的氧气，铁丝可能烧不起来。","铁丝不能接触瓶壁，也不能插入瓶底的水或细沙中，瓶内氧气要事先收集满。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["3Fe + 2O₂ —点燃→ Fe₃O₄","点燃","剧烈燃烧，火星四射，放出大量的热，生成黑色固体","配平要点：最小公倍数法。右边氧原子 4 个、左边每 1 个 O₂ 提供 2 个，最小公倍数 4，故 O₂ 前配 2、Fe₃O₄ 前配 1，最后配铁得系数 3。写成 2Fe + O₂ 或 Fe + O₂ 都是没配平。"],["4Al + 3O₂ —→ 2Al₂O₃","常温（不需加热）","铝表面逐渐变暗，生成一层致密的氧化铝薄膜","配平要点：最小公倍数法。氧原子左边 2 个、右边 3 个，最小公倍数 6，O₂ 前配 3、Al₂O₃ 前配 2，再配铝得 4。这层氧化膜能保护内部的铝，所以铝制品耐腐蚀。"],["CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O","点燃","产生明亮的蓝色火焰，放出大量的热，干冷烧杯内壁出现水雾","配平要点：观察法。从最复杂的 CH₄ 入手，先配碳（1 个 CO₂）、再配氢（4 个氢原子配 2 个 H₂O），最后数右边氧原子 2 + 2 = 4，O₂ 前配 2。"],["2C + O₂ —点燃→ 2CO","点燃","碳在氧气不足时不完全燃烧，生成无色无味的有毒气体一氧化碳","配平要点：奇偶配平法。右边 CO 中氧原子只有 1 个（奇数），先在 CO 前配 2 把氧原子变成偶数，再在 C 前配 2。碳完全燃烧生成二氧化碳，写成 C + O₂ —点燃→ CO₂，条件相同、产物不同，要看题目给的氧气是否充足。"],["Fe₂O₃ + 3H₂SO₄ —→ Fe₂(SO₄)₃ + 3H₂O","常温（不需加热）","红棕色固体逐渐溶解，溶液变成黄色","配平要点：原子团整体配平。把 SO₄ 当成一个整体，右边 Fe₂(SO₄)₃ 中有 3 个，左边 H₂SO₄ 前就配 3；再数氢，左边 6 个氢原子，H₂O 前配 3。检查氧原子：左边 3 + 12 = 15 个，右边 12 + 3 = 15 个。"],["3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂","高温","红棕色粉末逐渐变成黑色，澄清石灰水变浑浊，尾气中有一氧化碳","配平要点：先看右边 Fe₂O₃ 中的氧原子 3 个，每个 CO 只能夺走 1 个氧原子，故 CO 前配 3、CO₂ 前配 3，最后配铁得 2。反应物中有气体 CO，所以生成的 CO₂ 不标 ↑。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["配平时可以适当改动化学式中元素符号右下角的数字，只要两边原子相等就行","下标绝不能改，只能改化学式前面的系数","下标是物质的身份证：把 H₂O 改成 H₂O₂ 就变成了过氧化氢，与原来的反应完全不是一回事。改下标属于「臆造物质」，违反书写化学方程式的第一条原则。"],["2H₂ + O₂ —点燃→ 2H₂O 可以约成 H₂ + O₂ —点燃→ H₂O，这样更简单","系数已经是最简整数比 2 : 1 : 2，不能再约，约了就不配平了","约分是把系数同时缩小，缩到 1 : 1 : 1 之后两边氧原子就不再相等（左 2 右 1），式子又变成没配平的状态。配平的目的是原子相等，不是数字好看。"],["Fe₂O₃ + H₂SO₄ —→ Fe₂(SO₄)₃ + H₂O 里 Fe₂(SO₄)₃ 的硫原子数按 1 个算","要按括号外的下标算：Fe₂(SO₄)₃ 中有 3 个硫原子、12 个氧原子","括号右下角的数字是对整个原子团的倍数。忽视括号会把硫原子数算错，后面的系数就全错。数原子时先数括号内的，再乘括号外的数字，最后乘化学式前面的系数。"],["配平只要保证原子个数相等，系数是分数也可以保留","化学方程式中的系数必须是整数，出现分数要把全式系数同乘分母","系数表示分子的个数，不存在「半个分子参加反应」的说法。若配平时得到 1/2，说明前面的选择不够巧妙，把全式同乘 2 化成整数即可。"]]},{"type":"table","title":"最小公倍数法与奇偶配平法（两种配平方法分别在什么时候用）","head":["比较项","最小公倍数法","奇偶配平法"],"rows":[["适用情形","一种元素在两边各只出现在一种物质里，且两边原子个数不同","某元素原子个数一边是奇数、一边是偶数"],["关键动作","求最小公倍数，再分别除以两边的原子个数得到系数","先在含奇数个该原子的化学式前配 2，把奇数变成偶数"],["典型例子","3Fe + 2O₂ —点燃→ Fe₃O₄；4Al + 3O₂ —→ 2Al₂O₃","2C + O₂ —点燃→ 2CO；2H₂O₂ —MnO₂→ 2H₂O + O₂↑"],["容易出错处","把最小公倍数直接当成系数，填错位置","配完忘记回头检查其他元素是否还要调系数"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["配平结果的正误判断与系数填空","给出四个方程式判断哪个配平正确，或留出系数让学生填写。常见错误是漏乘系数、把最小公倍数直接当系数、下标写错。做这类题先数最复杂的那种元素的原子，再看系数是否最简整数比。"],["配平方法的选择与过程表述","要求写出配平过程或说明用了哪种方法（观察法、最小公倍数法、奇偶配平法、原子团整体配平）。答题要写出「先看哪种元素、两边各几个原子、最小公倍数是多少、系数怎么定」这几步，只说结果往往拿不到过程分。"],["把方程式配平后用于简单计算","实验题或计算题里先要求写出并配平方程式，再按方程式计算。方程式没配平，后面的比例式一定错，这是一道题里最容易连带失分的地方，所以计算前先回头检查配平。"]]},{"type":"quote","text":"【材料一】化学课上老师展示了四组没有配平的方程式：\n① Fe + O₂ —点燃→ Fe₃O₄\n② Al + O₂ —→ Al₂O₃\n③ C + O₂ —点燃→ CO\n④ Fe₂O₃ + H₂SO₄ —→ Fe₂(SO₄)₃ + H₂O\n【材料二】某同学配平第 ① 组时写成 Fe + O₂ —点燃→ Fe₃O₄，理由是「铁在氧气中燃烧生成四氧化三铁，物质没错就行」；配平第 ③ 组时他把 CO 改写成 CO₂，理由是「这样氧原子个数就相等了」。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】写出①②③④四组方程式配平后的结果，并说明每一组分别用了哪种配平方法。（6 分）","【设问】材料二中的两处做法分别错在哪里？请说明理由并写出正确的方程式。（4 分）","【设问】按配平后的 3Fe + 2O₂ —点燃→ Fe₃O₄ 计算：16.8 g 铁丝完全燃烧，需要消耗多少克氧气？生成多少克四氧化三铁？（5 分）"]}],"questions":[{"id":"chem-equation-3-q1","type":"choice","stem":"图是镁在氧气中燃烧的粒子模型示意图。下列化学方程式中，与该图相符且书写正确的是","answer":"D","explain":"图中反应前有 2 个镁原子和 1 个氧分子，反应后生成 2 个氧化镁「粒子」，即 2Mg + O₂ —点燃→ 2MgO，D 正确。A 错：两边氧原子与镁原子个数都不相等，没有配平。B 错：配平正确但漏写了反应条件「点燃」。C 错：左边只有 1 个镁原子，右边 MgO 前写了 2 就有 2 个镁原子，镁没有配平（氧原子两边虽然都是 2 个，但镁不相等，方程式仍然不成立）。","options":["Mg + O₂ —点燃→ MgO","2Mg + O₂ —→ 2MgO","Mg + O₂ —点燃→ 2MgO","2Mg + O₂ —点燃→ 2MgO"],"difficulty":2,"tags":["配平","微观粒子","化学方程式"],"figure":{"id":"fig-chem-equation-3-q1","title":"镁在氧气中燃烧的粒子模型","caption":"反应前 2 个镁原子与 1 个氧分子，反应后生成 2 个氧化镁粒子","view":"wide","alt":"左边是两个镁原子和一个氧分子，右边是两个由镁原子和氧原子构成的氧化镁粒子","prims":[{"t":"atom","x":12,"y":16,"symbol":"Mg"},{"t":"atom","x":12,"y":40,"symbol":"Mg"},{"t":"molecule","x":30,"y":28,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"arrow","x1":42,"y1":28,"x2":54,"y2":28,"label":"点燃","labelDy":-4},{"t":"molecule","x":74,"y":16,"atoms":[{"dx":-2.6,"dy":0,"symbol":"Mg"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"MgO"},{"t":"molecule","x":74,"y":40,"atoms":[{"dx":-2.6,"dy":0,"symbol":"Mg"},{"dx":2.6,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"MgO"},{"t":"text","x":50,"y":57,"text":"反应前后：Mg 原子 2 个、O 原子 2 个，都没有改变","size":3}]}},{"id":"chem-equation-3-q2","type":"choice","stem":"用最小公倍数法配平 4P + 5O₂ —点燃→ 2P₂O₅ 时，下列说法正确的是","answer":"A","explain":"最小公倍数法的做法就是求最小公倍数再分别除以两边的原子个数，A 的每一步都正确。B 错：P₂O₅ 前配 4 会使右边氧原子变成 20 个，与左边对不上，配平要先处理出现次数少的元素（这里是氧）。C 错：O₂ 前配 2 只有 4 个氧原子，右边 5 个，仍然不相等。D 错：改下标等于换了物质，P₂O₄ 不是五氧化二磷。","options":["先配氧原子：左边每个 O₂ 含 2 个氧原子，右边每个 P₂O₅ 含 5 个氧原子，2 与 5 的最小公倍数是 10，所以 O₂ 前配 5、P₂O₅ 前配 2","先配磷原子，直接在 P₂O₅ 前配 4，使两边磷原子都是 4 个","因为左边的氧原子比右边多，把 O₂ 前的系数改成 2 就能配平","把 P₂O₅ 改写成 P₂O₄，两边的氧原子个数就相等了"],"difficulty":2,"tags":["配平","最小公倍数法"]},{"id":"chem-equation-3-q3","type":"choice","stem":"下列关于配平化学方程式的说法，正确的是","answer":"B","explain":"系数表示分子个数，可以改；下标是物质的组成，改了就等于换了物质，所以 B 正确。A 错在动了下标，属于臆造物质。C 错：系数只要求是最简整数比，奇数完全正常，如 2H₂ + O₂ —点燃→ 2H₂O 中 O₂ 的系数就是 1。D 错：系数还要满足最简整数比，且不能出现分数，随便取值会出现「2H₂ + 2O₂ —点燃→ 4H₂O」这类虽然原子相等但不规范的写法。","options":["为了配平，可以把化学式中元素符号右下角的数字改成合适的数值","配平只能改变化学式前面的系数，而且系数必须是最简整数比","配平后的系数必须都是偶数，遇到奇数系数要整体乘 2 改成偶数","只要两边各元素原子的总数相等，系数取什么值都可以"],"difficulty":2,"tags":["配平","书写规范"]},{"id":"chem-equation-3-q4","type":"choice","stem":"乙醇燃烧的方程式为 C₂H₅OH + __O₂ —点燃→ __CO₂ + __H₂O，配平后氧气前面的系数是","answer":"C","explain":"先配碳：左边 2 个碳原子，CO₂ 前配 2；再配氢：左边 6 个氢原子，H₂O 前配 3；最后数右边氧原子 2×2 + 3×1 = 7 个，乙醇分子本身含 1 个氧原子，需要氧气提供 6 个氧原子，O₂ 前配 3，C 正确。A 错、B 错：只看到乙醇分子里那 1 个氧原子，漏算了生成物中氧原子的总数；D 错：把氧原子总数 7 直接当成了 O₂ 的系数，忘记每个 O₂ 分子含 2 个氧原子，系数 3 才是「提供 6 个氧原子」的那个数。","options":["1","2","3","4"],"difficulty":3,"tags":["配平","观察法"]},{"id":"chem-equation-3-q5","type":"choice","stem":"下列化学方程式配平正确的是","answer":"D","explain":"D 中两边铁原子都是 3 个、氧原子都是 4 个，条件也正确，配平正确。A 错：右边有 3 个铁原子，左边只有 2 个，铁没有配平。B 错：左边 4 个磷原子，右边只有 2 个，磷没有配平。C 错：左边 4 个氢原子，右边只有 2 个，氢没有配平，应写成 2H₂O₂ —MnO₂→ 2H₂O + O₂↑。","options":["2Fe + O₂ —点燃→ Fe₃O₄","4P + 5O₂ —点燃→ P₂O₅","2H₂O₂ —MnO₂→ H₂O + O₂↑","3Fe + 2O₂ —点燃→ Fe₃O₄"],"difficulty":2,"tags":["配平","书写正误"]},{"id":"chem-equation-3-q6","type":"fill","stem":"配平 __Fe₂O₃ + __CO —高温→ __Fe + __CO₂ 后，一氧化碳前面的系数是 ______。","answer":"3","explain":"每个 CO 只能夺走 1 个氧原子，Fe₂O₃ 中有 3 个氧原子，所以 CO 前配 3、CO₂ 前配 3，再配铁得 2，即 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂。检验：铁 2 与 2，氧 3 + 3 = 6 与 3×2 = 6，碳 3 与 3，全部相等。若填 2 是把铁前面的系数当成了 CO 的系数，填 6 则是把氧原子的个数当成了 CO₂ 的系数。","difficulty":1,"tags":["配平","观察法"]},{"id":"chem-equation-3-q7","type":"short","stem":"16.8 g 铁丝在氧气中完全燃烧，需要消耗多少克氧气？生成多少克四氧化三铁？","answer":"需要消耗氧气 6.4 g，生成四氧化三铁 23.2 g。","explain":"本题的成败在方程式：若写成 Fe + O₂ —点燃→ Fe₃O₄（没配平），相对分子质量就会错用成 56 与 32，结果全错。配平后一定要把系数乘进相对分子质量：3Fe 是 168 而不是 56，2O₂ 是 64 而不是 32。","difficulty":2,"tags":["配平","化学方程式计算"],"rubric":["设未知量并写清物质与单位","化学方程式配平正确、条件「点燃」正确","相对分子质量乘系数：3Fe 为 168、2O₂ 为 64、Fe₃O₄ 为 232","列比例式并解出氧气 6.4 g","求出四氧化三铁 23.2 g，答案带单位、有答句"],"steps":["设未知量：设消耗氧气的质量为 x，生成四氧化三铁的质量为 y。","写出并配平化学方程式：3Fe + 2O₂ —点燃→ Fe₃O₄。","算相对分子质量总和：3Fe 为 168，2O₂ 为 64，Fe₃O₄ 为 232。","列比例式求氧气：168/64 = 16.8 g/x，解得 x = 6.4 g。","列比例式求四氧化三铁：168/232 = 16.8 g/y，解得 y = 23.2 g。","作答：消耗氧气 6.4 g，生成四氧化三铁 23.2 g（16.8 g + 6.4 g = 23.2 g，与质量守恒相符）。"]},{"id":"chem-equation-3-q8","type":"short","stem":"3.2 g 硫粉在足量氧气中完全燃烧，需要消耗多少克氧气？生成多少克二氧化硫？","answer":"需要消耗氧气 3.2 g，生成二氧化硫 6.4 g。","explain":"硫与氧气的相对分子质量（相对原子质量）都是 32，所以消耗的氧气质量与硫的质量相等，这是本题的一个巧合，不能当成规律推广到别的题目。二氧化硫中硫与氧的质量比是 32 : 32 = 1 : 1，因此 6.4 g 二氧化硫里硫、氧各 3.2 g，与质量守恒完全对应。","difficulty":2,"tags":["配平","化学方程式计算"],"rubric":["设未知量并写清物质与单位","写出配平、条件正确的方程式 S + O₂ —点燃→ SO₂","算对相对分子质量 32、32、64","列比例式并求出氧气 3.2 g","求出二氧化硫 6.4 g，答案带单位、有答句"],"steps":["设未知量：设消耗氧气的质量为 x，生成二氧化硫的质量为 y。","写出化学方程式并检查配平：S + O₂ —点燃→ SO₂（系数全为 1）。","算相对分子质量：S 为 32，O₂ 为 32，SO₂ 为 64。","列比例式求氧气：32/32 = 3.2 g/x，解得 x = 3.2 g。","列比例式求二氧化硫：32/64 = 3.2 g/y，解得 y = 6.4 g。","作答：消耗氧气 3.2 g，生成二氧化硫 6.4 g。"]},{"id":"chem-equation-3-q9","type":"short","stem":"某同学做铁丝在氧气中燃烧的实验：铁丝没有绕成螺旋状就直接伸入集气瓶，结果铁丝没有燃烧起来。请分析可能的原因（至少写出两条），说明集气瓶底部预先放少量水或铺一层细沙的作用，并写出该反应的化学方程式。","answer":"可能的原因：一是铁丝表面有铁锈，没有用砂纸打磨，铁锈阻碍铁与氧气接触；二是铁丝没有绕成螺旋状，受热面积小、散热快，温度达不到着火点；三是伸入集气瓶时火柴已经烧完或铁丝伸入太早，火柴燃烧消耗了瓶内的氧气；四是收集的氧气不纯或瓶内氧气太少。集气瓶底部放少量水或铺一层细沙，是为了防止燃烧生成的高温熔融物溅落下来使瓶底炸裂。化学方程式为 3Fe + 2O₂ —点燃→ Fe₃O₄。","explain":"铁丝燃烧需要三个条件同时满足：与氧气充分接触、温度达到着火点、氧气浓度足够。未打磨、未绕成螺旋状、伸入时机不对，分别破坏的是接触面积、保温效果和瓶内氧气含量。回答这类题要「原因 + 后果」成对写，只说「操作不对」不给分。","difficulty":2,"tags":["配平","实验探究","铁丝燃烧"],"rubric":["写出至少两条合理原因（铁丝未打磨、未绕成螺旋状、火柴燃尽后才伸入、氧气不纯等），每条 1 分","说明瓶底放水或细沙是防止熔融物溅落炸裂瓶底","写出 3Fe + 2O₂ —点燃→ Fe₃O₄，配平正确","标出反应条件「点燃」，并指出生成物是黑色的四氧化三铁"]},{"id":"chem-equation-3-q10","type":"short","stem":"用适当的方法配平下列化学方程式，并在括号里写出所用的配平方法。\n（1）__Fe + __O₂ —点燃→ __Fe₃O₄（ ）\n（2）__Al + __O₂ —→ __Al₂O₃（ ）\n（3）__C + __O₂ —点燃→ __CO（ ）\n（4）__Fe₂O₃ + __H₂SO₄ —→ __Fe₂(SO₄)₃ + __H₂O（ ）","answer":"（1）3Fe + 2O₂ —点燃→ Fe₃O₄，最小公倍数法；（2）4Al + 3O₂ —→ 2Al₂O₃，最小公倍数法；（3）2C + O₂ —点燃→ 2CO，奇偶配平法；（4）Fe₂O₃ + 3H₂SO₄ —→ Fe₂(SO₄)₃ + 3H₂O，原子团整体配平。","explain":"四题的共同点是「先配氧」：（1）（2）用最小公倍数法把氧原子凑成最小公倍数；（3）用奇偶配平法先把奇数氧原子的 CO 前配 2；（4）用原子团整体法数 SO₄ 的个数。写方法时要写清判断依据，如「氧原子左边 2 个、右边 3 个，最小公倍数 6」，只写方法名称是拿不到过程分的。","difficulty":3,"tags":["配平","配平方法","书写题"],"rubric":["（1）配平正确并写出最小公倍数法（2 分）","（2）配平正确并写出最小公倍数法，指出 2 与 3 的最小公倍数是 6（2 分）","（3）配平正确并写出奇偶配平法（2 分）","（4）配平正确并写出原子团整体配平（2 分）"],"answerFigure":{"id":"fig-chem-equation-3-q10-a","title":"参考答案：配平结果与方法","caption":"四种方法对应四种典型式子","view":"wide","alt":"板书列出四个配平后的化学方程式以及各自使用的配平方法","prims":[{"t":"text","x":50,"y":12,"text":"（1）3Fe + 2O₂ —点燃→ Fe₃O₄　最小公倍数法","size":3.2},{"t":"text","x":50,"y":24,"text":"（2）4Al + 3O₂ —→ 2Al₂O₃　最小公倍数法","size":3.2},{"t":"text","x":50,"y":36,"text":"（3）2C + O₂ —点燃→ 2CO　奇偶配平法","size":3.2},{"t":"text","x":50,"y":48,"text":"（4）Fe₂O₃ + 3H₂SO₄ —→ Fe₂(SO₄)₃ + 3H₂O","size":3.2},{"t":"text","x":50,"y":58,"text":"（4）用的是原子团整体配平：先数 SO₄ 的个数","size":3,"tone":"muted"}]}},{"id":"chem-equation-3-m1-q1","type":"short","stem":"写出①②③④四组方程式配平后的结果，并说明每一组分别用了哪种配平方法。（6 分）","answer":"① 3Fe + 2O₂ —点燃→ Fe₃O₄（最小公倍数法，先配氧）；② 4Al + 3O₂ —→ 2Al₂O₃（最小公倍数法，氧原子 2 与 3 的最小公倍数是 6）；③ 2C + O₂ —点燃→ 2CO（奇偶配平法，先在 CO 前配 2）；④ Fe₂O₃ + 3H₂SO₄ —→ Fe₂(SO₄)₃ + 3H₂O（原子团整体配平，把 SO₄ 当成一个整体）。","explain":"","tags":["配平","配平方法"],"rubric":["① 配平正确并说明用最小公倍数法配氧（1.5 分）","② 配平正确并说明 2 与 3 的最小公倍数是 6（1.5 分）","③ 配平正确并说明奇偶配平法（1.5 分）","④ 配平正确并说明原子团整体配平（1.5 分）"]},{"id":"chem-equation-3-m1-q2","type":"short","stem":"材料二中的两处做法分别错在哪里？请说明理由并写出正确的方程式。（4 分）","answer":"第一处：只保证物质正确不够，还必须遵守质量守恒定律，两边原子个数要相等，正确的写法是 3Fe + 2O₂ —点燃→ Fe₃O₄。第二处：把 CO 改成 CO₂ 是改动化学式，等于换了生成物，违反「以客观事实为依据」的原则；碳不完全燃烧的产物是一氧化碳，正确写法是 2C + O₂ —点燃→ 2CO，配平只能改化学式前面的系数。","explain":"","tags":["配平","书写原则","常见错误"],"rubric":["指出「物质对不等于配平」，写出 3Fe + 2O₂ —点燃→ Fe₃O₄（2 分）","指出改化学式等于换了物质，违反客观事实原则（1 分）","写出正确的 2C + O₂ —点燃→ 2CO（1 分）"]},{"id":"chem-equation-3-m1-q3","type":"short","stem":"按配平后的 3Fe + 2O₂ —点燃→ Fe₃O₄ 计算：16.8 g 铁丝完全燃烧，需要消耗多少克氧气？生成多少克四氧化三铁？（5 分）","answer":"需要消耗氧气 6.4 g，生成四氧化三铁 23.2 g。","explain":"","tags":["配平","化学方程式计算"],"rubric":["设未知量并写出配平、条件正确的方程式（1 分）","算对相对分子质量总和 168、64、232（1.5 分）","列比例式求出氧气 6.4 g（1 分）","求出四氧化三铁 23.2 g（1 分）","答案带单位、有用质量守恒检验的意识（0.5 分）"],"steps":["设未知量：设消耗氧气的质量为 x，生成四氧化三铁的质量为 y。","写出配平且条件正确的化学方程式：3Fe + 2O₂ —点燃→ Fe₃O₄。","算相对分子质量总和：3Fe 为 3×56 = 168，2O₂ 为 2×32 = 64，Fe₃O₄ 为 3×56 + 4×16 = 232。","列比例式求氧气：168/64 = 16.8 g/x，解得 x = 16.8 g × 64 ÷ 168 = 6.4 g。","列比例式求四氧化三铁：168/232 = 16.8 g/y，解得 y = 16.8 g × 232 ÷ 168 = 23.2 g。","作答：需要氧气 6.4 g，生成四氧化三铁 23.2 g（检验 16.8 g + 6.4 g = 23.2 g）。"]}]},{"id":"chem-equation-4","title":"依据化学方程式的简单计算","subtitle":"人教版九年级 · 中考专题 · 化学方程式与计算 · all","grade":"all","tags":["人教版九年级 · 中考专题 · 化学方程式与计算"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 中考专题 · 化学方程式与计算 · all"},{"type":"note","title":"问题切入","text":"化学方程式既能表示反应，又能表示质量比，那怎么用它算出「需要多少原料」「能生成多少产品」？一道计算题在卷面上到底该按什么格式写才不丢分？"},{"type":"note","title":"一句话抓住关键","text":"化学方程式计算的依据是各物质之间固定的质量比（相对分子质量 × 系数之比）。规范格式六步：设、写、算、列、答（外加一步「用质量守恒检验」）。三条硬要求：方程式必须配平、相对分子质量要乘系数、代入的必须是参加反应的纯物质质量且单位统一。"},{"type":"h","text":"【符号】一、计算的依据藏在方程式里"},{"type":"p","text":"以电解水为例：2H₂O —通电→ 2H₂↑ + O₂↑。把相对分子质量乘上系数：2H₂O 是 36，2H₂ 是 4，O₂ 是 32，于是任何质量的水电解时，生成的氢气与水都按 4 : 36 = 1 : 9 的比例对应。这个比例是固定的，与加多少水无关，这就是「已知一种物质的质量求另一种物质的质量」能够成立的道理。"},{"type":"figure","figure":{"id":"fig-chem-equation-4-ratio","title":"方程式给出的质量比","caption":"相对分子质量乘系数，得到固定的质量比 36 : 4 : 32","view":"wide","alt":"板书列出电解水的方程式与三种物质的相对分子质量总和，标出质量比三十六比四比三十二","prims":[{"t":"text","x":50,"y":10,"text":"2H₂O —通电→ 2H₂↑ + O₂↑","size":4.6},{"t":"text","x":50,"y":24,"text":"2H₂O：2×18 = 36　2H₂：2×2 = 4　O₂：32","size":3.2},{"t":"text","x":50,"y":36,"text":"质量比 36 : 4 : 32 = 9 : 1 : 8","size":3.6,"tone":"accent"},{"t":"text","x":50,"y":48,"text":"18 g 水完全分解 ⇔ 2 g 氢气 + 16 g 氧气","size":3.2},{"t":"text","x":50,"y":58,"text":"比例固定，与水的多少无关","size":3.2}]}},{"type":"note","title":"","text":"质量比一定要乘系数：氢气的质量比是 2×2 = 4，不是 2；水的质量比是 2×18 = 36，不是 18。这是计算题最常见的失分点。"},{"type":"h","text":"【微观】二、微观上一目了然"},{"type":"p","text":"为什么水与氢气的质量比是 36 : 4？因为 2 个水分子（每个 18）质量共 36，分解后得到 2 个氢分子（每个 2）共 4 和 1 个氧分子 32。粒子个数比是 2 : 2 : 1，质量比则是「个数比 × 每个分子的质量」，所以出现系数。理解了这一层，就明白「为什么系数要乘进去」而不是死记格式。"},{"type":"figure","figure":{"id":"fig-chem-equation-4-micro","title":"个数比与质量比","caption":"2 个水分子分解成 2 个氢分子和 1 个氧分子，质量 36 : 4 : 32","view":"wide","alt":"左边两个水分子，右边两个氢分子和一个氧分子，标出分子个数比二比二比一与质量比三十六比四比三十二","prims":[{"t":"molecule","x":12,"y":18,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"molecule","x":12,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":3},{"dx":-3.2,"dy":-3.6,"symbol":"H","r":2.3},{"dx":3.2,"dy":-3.6,"symbol":"H","r":2.3}],"bonds":[[0,1],[0,2]],"label":"H₂O"},{"t":"arrow","x1":28,"y1":30,"x2":40,"y2":30,"label":"通电","labelDy":-4},{"t":"molecule","x":58,"y":16,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":58,"y":40,"atoms":[{"dx":-2.4,"dy":0,"symbol":"H"},{"dx":2.4,"dy":0,"symbol":"H"}],"bonds":[[0,1]],"label":"H₂"},{"t":"molecule","x":84,"y":28,"atoms":[{"dx":-2.8,"dy":0,"symbol":"O","color":"red"},{"dx":2.8,"dy":0,"symbol":"O","color":"red"}],"bonds":[[0,1]],"label":"O₂"},{"t":"text","x":50,"y":56,"text":"个数比 2 : 2 : 1，质量比 36 : 4 : 32","size":3.1}]}},{"type":"note","title":"","text":"个数比就是系数比，质量比要用相对分子质量（或相对原子质量）乘系数。题目里给出的体积比（如电解水 1 : 2）不能直接当作质量比使用。"},{"type":"h","text":"【应用】三、规范格式：设、写、算、列、解、答"},{"type":"p","text":"中考化学计算题按步骤给分，格式比结果更重要。第一步「设」：设未知量，写清是哪种物质的什么物理量并带单位，如「设生成氧气的质量为 x」；第二步「写」：写出配平且条件正确的方程式；第三步「算」：在方程式对应物质的下方写出相对分子质量乘系数的值；第四步「列」：列比例式，同种物质上下对应；第五步「解」：求出结果；第六步「答」：写答句并带单位。"},{"type":"figure","figure":{"id":"fig-chem-equation-4-format","title":"计算题的规范格式","caption":"设、写、算、列、解、答六步，每一步都对应一个得分点","view":"wide","alt":"板书展示一道化学计算题的规范书写格式，包括设未知量、写方程式、算相对分子质量、列比例式、求解和作答","prims":[{"t":"text","x":50,"y":9,"text":"设：设生成氧气的质量为 x","size":3.2},{"t":"text","x":50,"y":18,"text":"写：2KClO₃ —MnO₂、加热→ 2KCl + 3O₂↑","size":3.2},{"t":"text","x":50,"y":27,"text":"算：245　　　　　　　　　　96","size":3.2},{"t":"text","x":50,"y":36,"text":"列：245/96 = 24.5 g/x","size":3.2},{"t":"text","x":50,"y":45,"text":"解：x = 9.6 g","size":3.2},{"t":"text","x":50,"y":54,"text":"答：生成氧气的质量为 9.6 g","size":3.2},{"t":"text","x":50,"y":61,"text":"单位统一，只代入纯物质的质量","size":3,"tone":"muted"}]}},{"type":"note","title":"","text":"比例式要把「同一种物质」写在同一条对角线上：左边分子是已知物质的相对分子质量总和，分母是它的实际质量；右边同理。写反了就会出现「大比小」的自相矛盾结果。"},{"type":"h","text":"【应用】四、单位、纯量与结果的检查"},{"type":"p","text":"三条检查：一是单位是否统一（题目给 g 就用 g，不要把 g 与 kg 混着算，最终结果要带单位）；二是代入的是不是纯物质的质量（样品里含杂质、溶液里含水，都要先换算成参加反应的纯物质质量）；三是结果是否合理（用质量守恒检验：反应物质量总和应等于生成物质量总和；也可用「倍数关系」快速核对，如水的质量是 18 g 时氧气应为 16 g）。"},{"type":"figure","figure":{"id":"fig-chem-equation-4-check","title":"计算前的三个检查","caption":"单位统一、纯量代入、结果用质量守恒检验","view":"wide","alt":"板书列出化学方程式计算前的三个检查要点，分别是单位统一、代入纯物质质量和用质量守恒检验结果","prims":[{"t":"text","x":50,"y":14,"text":"查单位：g 与 g 对应，热量的单位不要混进来","size":3.4},{"t":"text","x":50,"y":30,"text":"查纯量：杂质、水都不能代入，先换算成纯物质","size":3.4},{"t":"text","x":50,"y":46,"text":"查结果：反应物质量总和 = 生成物质量总和","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"三查通过再写答句","size":3.2}]}},{"type":"note","title":"","text":"题目给的「足量」「过量」意味着另一种反应物完全反应，可以用它来计算；题目给的「恰好完全反应」说明两种反应物都刚好用完，用哪一种算都可以。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["方程式计算的质量比","物质甲的质量 / 物质乙的质量 = (甲的相对分子质量 × 甲前面的系数) / (乙的相对分子质量 × 乙前面的系数)","两侧质量单位必须相同；相对分子质量是无单位的数值 · 适用于一切已知一种物质质量求另一种物质质量的题目。使用前提是方程式已配平、条件是真实的；系数必须乘进去；若题目给出的是样品质量或溶液质量，必须先换算成参加反应的纯物质质量。"],["解题六步格式","设未知量 → 写方程式 → 算相对分子质量 → 列比例式 → 求解 → 作答","设未知量与作答都要带单位 · 适用于所有化学计算题的卷面书写，中考按步骤给分。缺「设」或缺「答」都会扣分；方程式未配平或漏条件则本题不给分，因此计算前先回头检查方程式。"],["单位与纯量要求","代入方程式的只能是参加反应的纯物质质量，且各量单位统一","质量一般用 g，体积用 L 或 mL，溶液中溶质质量用 g · 适用于含杂质样品、溶液、气体体积等一切非纯量情形：样品要先按纯度换算，溶液要先按溶质质量分数换算，气体体积要先按密度换算成质量。单位不统一（g 与 kg 混用）是最常见的隐性错误。"],["结果检验（质量守恒）","参加反应的各物质质量总和 = 生成的各物质质量总和","各量单位统一为 g · 用于算完之后的自查：把求出的各物质质量按「反应物之和 = 生成物之和」核对。若两边差得很多，通常是方程式没配平、相对分子质量漏乘系数，或者代入的数据不是纯量。"]]},{"type":"h","text":"应用 · 电解水：已知水的质量求氢气和氧气"},{"type":"note","title":"情境","text":"实验室电解 36 g 水，可以得到氢气和氧气各多少克？"},{"type":"list","title":"解答步骤","items":["设未知量：设生成氢气的质量为 x，生成氧气的质量为 y。","写出化学方程式：2H₂O —通电→ 2H₂↑ + O₂↑。","算相对分子质量总和：2H₂O 为 36，2H₂ 为 4，O₂ 为 32。","列比例式：36/4 = 36 g/x，得 x = 4 g；36/32 = 36 g/y，得 y = 32 g。","检验：4 g + 32 g = 36 g，符合质量守恒。"]},{"type":"note","title":"结论","text":"得到氢气 4 g、氧气 32 g。"},{"type":"h","text":"应用 · 锌与稀硫酸：已知金属质量求氢气质量"},{"type":"note","title":"情境","text":"13 g 锌与足量稀硫酸充分反应，可以生成多少克氢气？消耗多少克硫酸？"},{"type":"list","title":"解答步骤","items":["设未知量：设生成氢气的质量为 x，消耗硫酸的质量为 y。","写出化学方程式：Zn + H₂SO₄ —→ ZnSO₄ + H₂↑。","算相对分子质量：Zn 为 65，H₂SO₄ 为 98，H₂ 为 2。","列比例式：65/2 = 13 g/x，得 x = 0.4 g；65/98 = 13 g/y，得 y = 19.6 g。","检验：13 g + 19.6 g = 32.6 g，等于生成的硫酸锌 32.2 g 与氢气 0.4 g 之和。"]},{"type":"note","title":"结论","text":"生成氢气 0.4 g，消耗硫酸 19.6 g。"},{"type":"h","text":"应用 · 加热高锰酸钾：已知药品质量求氧气质量"},{"type":"note","title":"情境","text":"实验室要制取 3.2 g 氧气，需要完全分解多少克高锰酸钾？"},{"type":"list","title":"解答步骤","items":["设未知量：设需要高锰酸钾的质量为 x。","写出化学方程式：2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。","算相对分子质量总和：2KMnO₄ 为 316，O₂ 为 32。","列比例式：316/32 = x/3.2 g，解得 x = 3.2 g × 316 ÷ 32 = 31.6 g。","作答：需要高锰酸钾 31.6 g。"]},{"type":"note","title":"结论","text":"需要完全分解高锰酸钾 31.6 g。"},{"type":"h","text":"实验 1 · 加热氯酸钾制取氧气并用质量差法求氧气质量"},{"type":"note","title":"实验目的","text":"通过称量反应前后固体质量的变化，得到氧气的质量，再用化学方程式计算生成氯化钾的质量"},{"type":"list","title":"实验器材","items":["托盘天平","试管","铁架台","酒精灯","单孔橡皮塞","导管","水槽","集气瓶","氯酸钾","二氧化锰"]},{"type":"figure","figure":{"id":"fig-chem-equation-4-exp1","title":"加热氯酸钾制取氧气","caption":"试管口略向下倾斜，用排水法收集氧气；反应前后称量试管内固体的质量","view":"wide","alt":"铁架台夹住倾斜的试管，试管中有白色固体，酒精灯在试管下方加热，导管通到水槽中倒置的集气瓶口","prims":[{"t":"stand","x":20,"y":44,"h":34,"clamps":[0.62]},{"t":"testTube","x":38,"y":22,"h":34,"w":10,"tilt":80},{"t":"alcoholLamp","x":34,"y":42,"lit":true,"label":"酒精灯"},{"t":"curve","points":[[42,18],[62,14],[66,30]],"arrow":true},{"t":"gasJar","x":74,"y":40,"w":18,"h":24,"liquid":0.6,"color":"colorless","label":"集气瓶"},{"t":"text","x":20,"y":12,"text":"氯酸钾 + 二氧化锰","size":3.2}]}},{"type":"list","title":"实验步骤","items":["称量空试管与药品（氯酸钾和二氧化锰的混合物）的总质量，记为 m₁。","按装置图装好仪器，检查气密性，试管口略向下倾斜，用排水法收集氧气。","点燃酒精灯加热，收集气体；收集满后先把导管移出水面，再熄灭酒精灯。","冷却后取下试管，连同管内固体一起称量，记为 m₂。","由 m₁ − m₂ 得到氧气的质量，再按化学方程式计算生成的氯化钾质量。"]},{"type":"note","title":"实验现象","text":"固体逐渐熔化并产生气泡，集气瓶中的水被排尽，收集到的气体能使带火星的木条复燃；冷却后试管内固体质量比反应前减少。"},{"type":"note","title":"实验结论","text":"减少的质量就是逸出的氧气质量，用 2KClO₃ —MnO₂、加热→ 2KCl + 3O₂↑ 可算出生成的氯化钾质量。"},{"type":"list","title":"注意事项","items":["试管口要略向下倾斜，防止冷凝水倒流引起试管炸裂。","必须先把导管移出水面再熄灭酒精灯，否则水会倒吸进试管。","称量必须在冷却后进行，热的固体放在天平上会产生气流影响读数，也可能损坏天平。","二氧化锰是催化剂，反应前后质量不变，计算时不能把它算成生成物。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2H₂O —通电→ 2H₂↑ + O₂↑","通电","两极都有气泡产生，负极气体能燃烧，正极气体能使带火星木条复燃","配平要点：先在 H₂ 前配 2，使两边氧原子都是 2 个，再核对氢原子。计算要点：2H₂O 为 36，2H₂ 为 4，O₂ 为 32，质量比 36 : 4 : 32 = 9 : 1 : 8。系数必须乘进相对分子质量，否则 18 g 水会算成生成 4 g 氢气（正确是 2 g）。"],["2KClO₃ —MnO₂、加热→ 2KCl + 3O₂↑","二氧化锰作催化剂、加热","固体逐渐熔化并产生气体，导管口有气泡冒出，木条复燃","配平要点：先配氧——右边 3O₂ 有 6 个氧原子，左边 KClO₃ 前配 2 正好提供 6 个氧原子，钾、氯随之自动配平。计算要点：2KClO₃ 为 245，2KCl 为 149，3O₂ 为 96，245 = 149 + 96，可用于检验配平。用二氧化锰作催化剂时其质量不变，若题目给出混合物的质量，注意减去催化剂的质量。"],["2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑","加热","紫黑色固体逐渐减少，导管口有气泡冒出，收集到能使木条复燃的气体","配平要点：先配钾——右边 K₂MnO₄ 中钾有 2 个，KMnO₄ 前配 2，再数氧原子（左边 8 个，右边 4 + 2 + 2 = 8 个）即自动配平。计算要点：2KMnO₄ 为 316，K₂MnO₄ 为 197，MnO₂ 为 87，O₂ 为 32；197 + 87 + 32 = 316。已知高锰酸钾质量求氧气时，316 : 32 = m(KMnO₄) : m(O₂)。"],["CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","常温（不需加热）","固体溶解，产生大量气泡，气体使澄清石灰水变浑浊","配平要点：系数为 1、2、1、1、1。计算要点：CaCO₃ 为 100，2HCl 为 73，CaCl₂ 为 111，H₂O 为 18，CO₂ 为 44。用稀盐酸时只有溶质 HCl 的质量能代入，需先按溶质质量分数把溶液质量换算成 HCl 的质量。"],["Zn + H₂SO₄ —→ ZnSO₄ + H₂↑","常温（不需加热）","锌粒表面产生大量气泡，锌粒逐渐溶解，放出的气体能燃烧","配平要点：系数全为 1，两边锌、氢、硫、氧原子个数相等。计算要点：Zn 为 65，H₂SO₄ 为 98，ZnSO₄ 为 161，H₂ 为 2；65 + 98 = 161 + 2，可用于检验。反应物中没有气体，生成的氢气要标 ↑。"],["Fe + 2HCl —→ FeCl₂ + H₂↑","常温（不需加热）","铁逐渐溶解，溶液由无色变成浅绿色，产生大量气泡","配平要点：在盐酸前配 2，使两边氢原子都是 2 个、氯原子都是 2 个。计算要点：Fe 为 56，2HCl 为 73，FeCl₂ 为 127，H₂ 为 2；56 + 73 = 127 + 2。铁与盐酸反应生成的是氯化亚铁（FeCl₂），不是 FeCl₃，写成 FeCl₃ 相对分子质量会全错。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["已知 18 g 水电解，按 2H₂O —通电→ 2H₂↑ + O₂↑ 直接算成生成 4 g 氢气、32 g 氧气","18 g 水对应的氢气是 2 g、氧气是 16 g","36 : 4 : 32 是 2 个水分子、2 个氢分子、1 个氧分子的质量比。18 g 水只是 36 g 的一半，生成物也要按一半算。直接把 36 的比例当成 18 g 的结果，等于把系数丢掉了。"],["计算时可以把题目给的样品质量（含杂质）直接代入方程式","必须先换算成参加反应的纯物质质量","方程式描述的是纯净物之间的质量关系，杂质根本不参加反应，把它算进去会使结果偏大。同理，溶液中的水也不参加反应，只能用溶质的质量代入。"],["电解水时正负极气体的体积比是 1 : 2，所以氢气与氧气的质量比也是 2 : 1","体积比 1 : 2 是正极氧气与负极氢气之比；质量比是氢气 4 : 氧气 32 = 1 : 8","体积比由分子个数决定，质量比还要乘上每个分子的质量。氢分子与氧分子的质量相差 16 倍，所以体积比与质量比完全不同，题目里给出体积时要先看它是不是能直接使用。"],["结果算成小数就是没算对，必须凑成整数","结果按题目要求保留有效数字即可，如 0.4 g、19.6 g 都是正确答案","化学计算的结果由数据决定，不一定整除。为了「凑整数」而改动相对分子质量或系数，反而会把正确的过程算错。做题时先用质量守恒检验结果是否合理，而不是看它像不像整数。"]]},{"type":"table","title":"化学计算与数学应用题（同样是「已知一个量求另一个量」，做法有什么不同）","head":["比较项","化学计算","数学应用题"],"rows":[["依据","化学方程式中各物质固定的质量比","题目给出的数量关系或公式"],["必须先做的事","写出并配平化学方程式，标出反应条件","设未知数、找等量关系"],["数据要求","只能是参加反应的纯物质质量，单位统一","题目给什么数就用什么数"],["结果检验","用质量守恒（反应物总和 = 生成物总和）核对","代回原方程检验"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["按步骤给分的格式题","给出情境与数据要求完整解答，评分标准就是六步：设未知量、写方程式、算相对分子质量、列比例式、求解、作答。评分时方程式与配平占分最重，漏写「答」或单位不写都要扣分。"],["判断解题过程的正误并改正","给出一份有错误的解题过程（漏乘系数、方程式未配平、单位不统一、代入了含杂质的质量），要求指出错误并改正。答题要按「错在哪一步 + 应该怎么写」的格式回答。"],["说理型问题：为什么这样算","要求解释质量比为什么等于「相对分子质量 × 系数」之比、为什么只能用纯量代入。答这类题要结合微观粒子（分子个数比）与质量守恒，只背格式拿不到分。"]]},{"type":"quote","text":"【材料一】某同学解一道化学计算题，题目是「加热 24.5 g 氯酸钾与 1 g 二氧化锰的混合物，完全反应后可生成多少克氧气」。他的解答过程是：\n2KClO₃ —MnO₂、加热→ 2KCl + 3O₂↑\n122.5　96\n24.5 g　x\n122.5/96 = 24.5 g/x，x = 19.2 g\n答：生成氧气 19.2 g。\n【材料二】教师批改时指出，这道题的规范解法还应当体现质量守恒，并提醒他「催化剂的质量不参与反应，但要算在称量范围内」。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】指出材料一中解答过程的错误并改正，说明规范的解题格式应当包括哪几步。（5 分）","【设问】另取 13 g 锌与足量稀硫酸充分反应，求生成氢气的质量和消耗硫酸的质量。（5 分）","【设问】请解释：为什么计算时要把相对分子质量乘上化学式前面的系数？为什么样品中的杂质质量不能直接代入？（4 分）"]}],"questions":[{"id":"chem-equation-4-q1","type":"choice","stem":"用化学方程式进行计算时，下列说法正确的是","answer":"A","explain":"方程式只描述纯净物之间的质量关系，杂质不参加反应，必须换算成纯量，A 正确。B 错：质量比要用「相对分子质量 × 系数」，与系数直接有关，如 2H₂ 是 4 而不是 2。C 错：同一条质量比既能求其他反应物，也能求生成物。D 错：单位必须统一，g 与 kg 混用会算出错误结果。","options":["只有真正参加反应的纯物质的质量才能代入方程式，含杂质的样品质量必须先换算","化学方程式中各物质的质量比就是它们的相对分子质量之比，与化学式前面的系数无关","已知一种反应物的质量，可以求出另一种反应物的质量，但不能求生成物的质量","代入方程式计算的各物质质量，单位可以不同，只要数字上下对应即可"],"difficulty":1,"tags":["化学方程式计算","纯量","单位"]},{"id":"chem-equation-4-q2","type":"choice","stem":"在 2H₂O —通电→ 2H₂↑ + O₂↑ 中，水、氢气、氧气的质量比是","answer":"C","explain":"质量比 = 相对分子质量 × 系数之比：水 2×18 = 36，氢气 2×2 = 4，氧气 1×32 = 32，即 36 : 4 : 32 = 9 : 1 : 8，C 正确。A 错：2 : 2 : 1 是分子个数比，不是质量比。B 错：氢气漏乘了系数，2H₂ 应是 4 而不是 2。D 错：水漏乘了系数，2H₂O 应是 36 而不是 18。","options":["2 : 2 : 1","36 : 2 : 32","9 : 1 : 8","18 : 2 : 32"],"difficulty":2,"tags":["化学方程式计算","质量比"]},{"id":"chem-equation-4-q3","type":"choice","stem":"电解 9 g 水，可以生成氧气的质量是","answer":"B","explain":"2H₂O 为 36，O₂ 为 32，36/32 = 9 g/x，解得 x = 8 g，B 正确。A 错：把 9 g 水当作 36 g 的一半之后又与氢气弄混，4 g 是生成氢气的质量，不是氧气。C 错：16 g 是 18 g 水生成的氧气质量，题目给的是 9 g，比例算错了。D 错：1 g 是把质量比 8 : 1 反过来用错的结果，9 g 水不可能只生成 1 g 氧气。","options":["4 g","8 g","16 g","1 g"],"difficulty":2,"tags":["化学方程式计算","电解水"]},{"id":"chem-equation-4-q4","type":"choice","stem":"在 4P + 5O₂ —点燃→ 2P₂O₅ 中，磷与氧气的质量比是","answer":"D","explain":"磷的相对原子质量是 31，4P 为 124；氧气 5O₂ 为 5×32 = 160，质量比 124 : 160 = 31 : 40，D 正确。A 错：4 : 5 是系数比，不是质量比。B 错：只用了 1 个磷原子与 1 个氧分子，没有乘系数。C 错：把 5O₂ 算成了 320（相当于 10 个氧分子），氧气部分多乘了一次 2。","options":["4 : 5","31 : 32","124 : 320","31 : 40"],"difficulty":2,"tags":["化学方程式计算","质量比"]},{"id":"chem-equation-4-q5","type":"choice","stem":"用如图装置加热 31.6 g 高锰酸钾，完全反应后，生成氧气的质量是","answer":"A","explain":"2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑，316/32 = 31.6 g/x，解得 x = 3.2 g，A 正确。B 错：6.4 g 是把 31.6 g 当成 63.2 g 来算的结果。C 错：1.6 g 相当于把质量比当成了 316 : 16，氧气的相对分子质量用错了。D 错：直接把氧气的相对分子质量 32 当成质量，没有列比例式，属于张冠李戴。剩余固体 31.6 g − 3.2 g = 28.4 g，正好等于 K₂MnO₄ 的 19.7 g 与 MnO₂ 的 8.7 g 之和，可以用来检验。","options":["3.2 g","6.4 g","1.6 g","32 g"],"difficulty":2,"tags":["化学方程式计算","高锰酸钾制氧气"],"figure":{"id":"fig-chem-equation-4-q5","title":"加热高锰酸钾制取氧气","caption":"试管口略向下倾斜，试管口塞一团棉花，用排水法收集氧气","view":"wide","alt":"铁架台夹住倾斜的试管，试管口略向下倾斜，酒精灯加热，导管伸到水槽中倒置的集气瓶口","prims":[{"t":"stand","x":20,"y":44,"h":34,"clamps":[0.62]},{"t":"testTube","x":38,"y":22,"h":34,"w":10,"tilt":80},{"t":"circle","cx":45,"cy":17,"r":2,"tone":"muted"},{"t":"alcoholLamp","x":34,"y":42,"lit":true,"label":"酒精灯"},{"t":"curve","points":[[42,18],[62,14],[66,30]],"arrow":true},{"t":"gasJar","x":74,"y":40,"w":18,"h":24,"liquid":0.6,"color":"colorless","label":"集气瓶"}]}},{"id":"chem-equation-4-q6","type":"fill","stem":"6.5 g 锌与足量稀硫酸完全反应，生成氢气的质量是 ______ g。","answer":"0.2|0.2g|0.2 g","explain":"Zn + H₂SO₄ —→ ZnSO₄ + H₂↑，65/2 = 6.5 g/x，解得 x = 0.2 g。检验：6.5 g 锌对应硫酸 9.8 g，生成硫酸锌 16.1 g 与氢气 0.2 g，16.1 g + 0.2 g = 16.3 g = 6.5 g + 9.8 g，符合质量守恒。若填 0.1 g，是把氢气当成了氧气（相对分子质量 32）来算。","difficulty":1,"tags":["化学方程式计算","锌与稀硫酸"]},{"id":"chem-equation-4-q7","type":"short","stem":"实验室要制取 1.6 g 氧气，需要完全分解多少克高锰酸钾？","answer":"需要完全分解高锰酸钾 15.8 g。","explain":"已知生成物求反应物，比例式的写法不变，只是把未知量 x 放在左侧。要注意 2KMnO₄ 的相对分子质量是 316 而不是 158。可用质量守恒核对：15.8 g 高锰酸钾分解后剩余固体为 15.8 g − 1.6 g = 14.2 g，正好是锰酸钾 9.85 g 与二氧化锰 4.35 g 之和，可以看出数据自洽。","difficulty":2,"tags":["化学方程式计算","高锰酸钾"],"rubric":["设未知量并写清物质与单位","化学方程式配平、条件「加热」正确","算对 2KMnO₄ 为 316、O₂ 为 32（系数已乘入）","列比例式并解出 15.8 g","答案带单位、有完整答句"],"steps":["设未知量：设需要高锰酸钾的质量为 x。","写出化学方程式：2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。","算相对分子质量总和：2KMnO₄ 为 2×(39 + 55 + 16×4) = 316，O₂ 为 32。","列比例式：316/32 = x/1.6 g，解得 x = 1.6 g × 316 ÷ 32 = 15.8 g。","作答：需要完全分解高锰酸钾 15.8 g。"]},{"id":"chem-equation-4-q8","type":"short","stem":"要得到 2 g 氢气，需要电解多少克水？同时生成多少克氧气？","answer":"需要电解水 18 g，同时生成氧气 16 g。","explain":"第一问的比例式把未知量放在分母上，也可以先求它们之间的固定比：水与氢气的质量比是 36 : 4 = 9 : 1，所以 2 g 氢气对应 18 g 水。第二问注意左右对应：氢气的 4 对应 2 g，氧气的 32 对应 y，不能把 36 与 16 写在同一侧。","difficulty":2,"tags":["化学方程式计算","电解水"],"rubric":["设未知量并写出配平、条件正确的方程式","算对 36、4、32（系数已乘入）","列比例式并求出水 18 g","求出氧气 16 g","答案带单位、有完整答句"],"steps":["设未知量：设需要电解水的质量为 x，生成氧气的质量为 y。","写出化学方程式：2H₂O —通电→ 2H₂↑ + O₂↑。","算相对分子质量：2H₂O 为 36，2H₂ 为 4，O₂ 为 32。","列比例式求水：36/4 = x/2 g，解得 x = 2 g × 36 ÷ 4 = 18 g。","列比例式求氧气：4/32 = 2 g/y，解得 y = 2 g × 32 ÷ 4 = 16 g。","作答：需要电解水 18 g，同时生成氧气 16 g（检验 2 g + 16 g = 18 g）。"]},{"id":"chem-equation-4-q9","type":"short","stem":"请解释为什么化学方程式中的质量比要用「相对分子质量 × 化学式前面的系数」，并以 2H₂O —通电→ 2H₂↑ + O₂↑ 为例说明；再说说解题格式中「设、写、算、列、答」每一步各自起什么作用。","answer":"化学式前面的系数表示分子的个数，每个水分子质量为 18，2 个水分子就是 36，所以水的相对质量总和要用 2×18 = 36；同理生成的氢气是 2×2 = 4，氧气是 32，质量比 36 : 4 : 32 = 9 : 1 : 8，与粒子个数比 2 : 2 : 1 对应。「设」是明确要求的量与单位，是列比例式的目标；「写」提供正确的质量比，方程式配平错了后面全错；「算」把系数乘进相对分子质量，得到可用的比例数据；「列」把已知量与未知量放在对应位置，是同种物质上下对应；「答」给出带单位的最终结果，是卷面上的得分点。","explain":"这道题考的是「为什么这样写」，不是「怎么写」。回答时要抓住两点：一是系数代表分子个数，所以质量要乘系数；二是六步格式对应六个得分点，其中方程式与相对分子质量这两步决定整题的成败。只抄一遍格式步骤而不解释作用，通常只能拿到一半的分。","difficulty":3,"tags":["化学方程式计算","说理","解题格式"],"rubric":["说明系数表示分子个数，质量比要乘系数（2 分）","以电解水为例算出 36 : 4 : 32 并化简为 9 : 1 : 8（2 分）","逐条说明「设、写、算、列、答」各步作用（3 分）","指出方程式配平错误会导致全题失分（1 分）"]},{"id":"chem-equation-4-q10","type":"short","stem":"下面是某同学解答「电解 18 g 水可生成多少克氧气」的过程，请指出其中不规范或错误的地方，并写出完整规范的解答。\n2H₂O —通电→ 2H₂ + O₂\n36 32\n18 g x\n36/32 = 18 g/x，x = 16 g","answer":"不规范或错误之处：化学方程式漏标反应条件「通电」，生成的气体漏标气体符号 ↑；没有设未知量；没有列比例式的说明与求解过程；最后没有作答。完整规范解答：设生成氧气的质量为 x；2H₂O —通电→ 2H₂↑ + O₂↑；2H₂O 为 36，O₂ 为 32；36/32 = 18 g/x；x = 18 g × 32 ÷ 36 = 16 g；答：18 g 水完全电解可生成氧气 16 g。","explain":"这位同学的比例式与数值结果都正确，但格式分几乎全掉了，这正是中考化学计算题最常见的失分方式。判断这类题要按「设、写、算、列、解、答」六步逐条对照：本题缺「设」与「答」，方程式缺条件与气体符号，共四处问题。","difficulty":2,"tags":["化学方程式计算","解题格式","书写题"],"rubric":["指出方程式漏写条件「通电」（1 分）","指出生成气体漏标 ↑（1 分）","指出没有设未知量、没有作答（1 分）","写出完整的规范解答并算出 16 g（3 分）"],"answerFigure":{"id":"fig-chem-equation-4-q10-a","title":"参考答案：完整规范的解答","caption":"六步格式齐全，方程式条件与气体符号正确","view":"wide","alt":"板书给出一道化学计算题的完整规范解答，包含设未知量、写方程式、算相对分子质量、列比例式、求解与作答","prims":[{"t":"text","x":50,"y":9,"text":"解：设生成氧气的质量为 x","size":3.2},{"t":"text","x":50,"y":19,"text":"2H₂O —通电→ 2H₂↑ + O₂↑","size":3.4},{"t":"text","x":50,"y":29,"text":"36　　　　　　　32","size":3.4},{"t":"text","x":50,"y":39,"text":"18 g　　　　　　x","size":3.4},{"t":"text","x":50,"y":49,"text":"36/32 = 18 g/x　x = 16 g","size":3.4},{"t":"text","x":50,"y":59,"text":"答：18 g 水完全电解生成氧气 16 g","size":3.2,"tone":"accent"}]}},{"id":"chem-equation-4-m1-q1","type":"short","stem":"指出材料一中解答过程的错误并改正，说明规范的解题格式应当包括哪几步。（5 分）","answer":"错误：没有设未知量；相对分子质量没有乘系数，把 2KClO₃ 写成 122.5 而不是 245，把 3O₂ 写成 96 而左边配错（245 才对应 96，122.5 对应的应是 48），导致结果 19.2 g 错误。规范格式包括：设未知量（设生成氧气的质量为 x）、写方程式（配平且条件正确）、算相对分子质量（要乘系数）、列比例式、求解、作答。改正后：245/96 = 24.5 g/x，x = 9.6 g，答：生成氧气 9.6 g。","explain":"","tags":["化学方程式计算","解题格式","常见错误"],"rubric":["指出没有设未知量（1 分）","指出相对分子质量漏乘系数（122.5 应为 245）（2 分）","正确算出 9.6 g 并写出答句（1 分）","写出规范格式的六步（1 分）"]},{"id":"chem-equation-4-m1-q2","type":"short","stem":"另取 13 g 锌与足量稀硫酸充分反应，求生成氢气的质量和消耗硫酸的质量。（5 分）","answer":"生成氢气 0.4 g，消耗硫酸 19.6 g。","explain":"","tags":["化学方程式计算","锌与稀硫酸"],"rubric":["设未知量并写出配平正确的方程式（1 分）","算对 65、98、2（1.5 分）","求出氢气 0.4 g（1 分）","求出硫酸 19.6 g（1 分）","答案带单位、有答句（0.5 分）"],"steps":["设未知量：设生成氢气的质量为 x，消耗硫酸的质量为 y。","写出化学方程式：Zn + H₂SO₄ —→ ZnSO₄ + H₂↑。","算相对分子质量：Zn 为 65，H₂SO₄ 为 98，H₂ 为 2。","列比例式：65/2 = 13 g/x，解得 x = 0.4 g。","列比例式：65/98 = 13 g/y，解得 y = 19.6 g。","作答：生成氢气 0.4 g，消耗硫酸 19.6 g。"]},{"id":"chem-equation-4-m1-q3","type":"short","stem":"请解释：为什么计算时要把相对分子质量乘上化学式前面的系数？为什么样品中的杂质质量不能直接代入？（4 分）","answer":"系数表示分子的个数，2 个水分子当然比 1 个水分子质量大一倍，所以质量比必须用「相对分子质量 × 系数」，如 2KClO₃ 是 245 而不是 122.5。方程式描述的是纯净物之间的质量关系，杂质不参加反应，把它的质量代入就会使算出的生成物质量偏大，因此必须先用纯度把样品质量换算成纯物质质量。","explain":"","tags":["化学方程式计算","说理","纯度"],"rubric":["说明系数表示分子个数，质量比要乘系数（2 分）","说明杂质不参加反应，代入会使结果偏大（1 分）","指出应先按纯度换算纯物质质量（1 分）"]}]},{"id":"chem-equation-5","title":"含杂质物质的计算与综合计算","subtitle":"人教版九年级 · 中考专题 · 化学方程式与计算 · all","grade":"all","tags":["人教版九年级 · 中考专题 · 化学方程式与计算"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 中考专题 · 化学方程式与计算 · all"},{"type":"note","title":"问题切入","text":"石灰石、赤铁矿、稀盐酸这些「不是纯物质」的东西，为什么不能把称到的质量直接写进方程式？样品、溶液、多步反应三种情形各该怎么换算？"},{"type":"note","title":"一句话抓住关键","text":"化学方程式只描述纯净物之间的质量关系，所以代入前必须把「拿到手的东西」换算成「真正参加反应的纯物质」：样品按纯度换算，溶液按溶质质量分数换算。两个换算公式是纯度 = 纯物质质量 ÷ 样品质量 × 100%、溶质质量 = 溶液质量 × 溶质质量分数。多步反应可以用元素守恒串起来。"},{"type":"h","text":"【宏观】一、拿到手的不等于参加反应的"},{"type":"p","text":"取一块石灰石放进稀盐酸里，冒出来的气泡是碳酸钙与盐酸反应生成的二氧化碳，而石灰石里的二氧化硅等杂质既不与盐酸反应，也不溶解，最后仍留在瓶里。如果直接把「石灰石的质量」当成「碳酸钙的质量」写进方程式，算出来的二氧化碳一定偏多。所以含杂质的题第一件事永远是：先把样品质量换算成纯物质质量。"},{"type":"figure","figure":{"id":"fig-chem-equation-5-macro","title":"石灰石与稀盐酸反应","caption":"瓶底的固体中只有碳酸钙参加反应，杂质既不反应也不溶解","view":"wide","alt":"锥形瓶中盛有稀盐酸，瓶底沉着石灰石固体颗粒，液面上不断冒出气泡","prims":[{"t":"flask","x":34,"y":38,"kind":"conical","h":30,"w":26,"liquid":0.5,"color":"colorless","label":"锥形瓶"},{"t":"dot","x":30,"y":48,"r":1.8},{"t":"dot","x":37,"y":49,"r":1.8},{"t":"dot","x":34,"y":46,"r":1.6},{"t":"dot","x":28,"y":42,"hollow":true},{"t":"dot","x":38,"y":39,"hollow":true},{"t":"text","x":74,"y":22,"text":"稀盐酸中参加反应的","size":3.1},{"t":"text","x":74,"y":29,"text":"只是溶质氯化氢","size":3.1},{"t":"text","x":74,"y":38,"text":"石灰石中参加反应的","size":3.1},{"t":"text","x":74,"y":45,"text":"只是碳酸钙","size":3.1}]}},{"type":"note","title":"","text":"「足量盐酸」「过量盐酸」说明样品中的碳酸钙能全部反应，可以用样品换算出的纯碳酸钙来计算；若盐酸不足，则要用盐酸中溶质的质量来算。"},{"type":"h","text":"【微观】二、微观上只有溶质粒子参加反应"},{"type":"p","text":"把稀盐酸放大看：里面绝大多数是水分子，少数是氯化氢分子（在水中电离成离子）。真正与碳酸钙发生反应的是氯化氢，水分子只是「陪跑」的。所以「溶液质量」这个数里包含大量水的质量，把 100 g 稀盐酸整体代入方程式，等于把水也算成了反应物，结果必然离谱。样品与杂质的关系也是如此：只有参加反应的那部分粒子才有固定的质量关系。"},{"type":"figure","figure":{"id":"fig-chem-equation-5-micro","title":"溶液中只有溶质参加反应","caption":"水分子不参加反应，只有氯化氢粒子与碳酸钙发生反应","view":"wide","alt":"虚线框内代表稀盐酸，里面散布着水分子与氯化氢粒子，氯化氢粒子用较醒目的点标出","prims":[{"t":"rect","x":8,"y":14,"w":84,"h":38,"dashed":true},{"t":"text","x":50,"y":9,"text":"稀盐酸（溶液）","size":3.6},{"t":"molecule","x":18,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":2.6},{"dx":-2.8,"dy":-3,"symbol":"H","r":2},{"dx":2.8,"dy":-3,"symbol":"H","r":2}],"bonds":[[0,1],[0,2]]},{"t":"molecule","x":40,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":2.6},{"dx":-2.8,"dy":-3,"symbol":"H","r":2},{"dx":2.8,"dy":-3,"symbol":"H","r":2}],"bonds":[[0,1],[0,2]]},{"t":"molecule","x":62,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":2.6},{"dx":-2.8,"dy":-3,"symbol":"H","r":2},{"dx":2.8,"dy":-3,"symbol":"H","r":2}],"bonds":[[0,1],[0,2]]},{"t":"molecule","x":84,"y":42,"atoms":[{"dx":0,"dy":0,"symbol":"O","color":"red","r":2.6},{"dx":-2.8,"dy":-3,"symbol":"H","r":2},{"dx":2.8,"dy":-3,"symbol":"H","r":2}],"bonds":[[0,1],[0,2]]},{"t":"dot","x":26,"y":24,"r":2,"tone":"accent"},{"t":"text","x":26,"y":31,"text":"HCl","size":3},{"t":"dot","x":52,"y":22,"r":2,"tone":"accent"},{"t":"text","x":52,"y":29,"text":"HCl","size":3},{"t":"dot","x":78,"y":24,"r":2,"tone":"accent"},{"t":"text","x":78,"y":31,"text":"HCl","size":3},{"t":"text","x":50,"y":58,"text":"水分子（下方）不参加反应，只有 HCl（上方）参加反应","size":3}]}},{"type":"note","title":"","text":"「溶液质量」包含水的质量，只有溶质的质量能代入方程式；题目给「溶质质量分数」就是让我们把溶液质量换算成溶质质量。"},{"type":"h","text":"【符号】三、两个换算公式与规范写法"},{"type":"p","text":"样品与溶液的换算只用到两个式子：纯度（纯物质的质量分数）= 纯物质质量 ÷ 样品质量 × 100%；溶质质量 = 溶液质量 × 溶质质量分数。写解答时先把换算写在前面，再写方程式与比例式，阅卷老师一眼就能看到「他有没有换算」。例如 12.5 g 石灰石样品中碳酸钙的质量分数为 80%，则 m(CaCO₃) = 12.5 g × 80% = 10 g，然后才能把 10 g 代入方程式。"},{"type":"figure","figure":{"id":"fig-chem-equation-5-formula","title":"先换算，再代入","caption":"样品与溶液都要先换算成参加反应的纯物质质量","view":"wide","alt":"板书给出由样品质量与纯度算纯物质质量、由溶液质量与溶质质量分数算溶质质量的换算过程","prims":[{"t":"text","x":50,"y":10,"text":"样品：纯物质质量 = 样品质量 × 纯度","size":3.4},{"t":"text","x":50,"y":20,"text":"12.5 g × 80% = 10 g（碳酸钙）","size":3.2},{"t":"text","x":50,"y":32,"text":"溶液：溶质质量 = 溶液质量 × 溶质质量分数","size":3.4},{"t":"text","x":50,"y":42,"text":"100 g × 7.3% = 7.3 g（氯化氢）","size":3.2},{"t":"text","x":50,"y":54,"text":"只有换算后的纯物质质量才能代入化学方程式","size":3.2,"tone":"accent"}]}},{"type":"note","title":"","text":"纯度与溶质质量分数都可以写成百分数或小数，计算时保持一致即可（80% = 0.8）。换算出来的纯物质质量必须带单位，且要与方程式中的质量单位统一。"},{"type":"h","text":"【应用】四、多步反应与综合计算"},{"type":"p","text":"有些题目要连过几步：矿石 → 主要成分 → 其中某种元素 → 产品。这时用元素守恒把几步串起来最快，例如用含氧化铁 80% 的赤铁矿 20 t 炼铁，先算出氧化铁 20 t × 80% = 16 t，再按 Fe₂O₃ 与 Fe 的关系 160 : 112 算得铁 11.2 t。也可以分步写方程式一步步算，但每一步都要重新做纯度或溶质的换算，最后再用质量守恒检查结果是否合理。"},{"type":"figure","figure":{"id":"fig-chem-equation-5-multi","title":"多步计算：矿石 → 氧化铁 → 铁","caption":"用元素守恒把「矿石—主要成分—产品」串起来","view":"wide","alt":"板书展示由赤铁矿质量与纯度算出氧化铁质量，再由氧化铁算出铁的质量的两步计算过程","prims":[{"t":"text","x":50,"y":10,"text":"赤铁矿 20 t（含 Fe₂O₃ 80%）","size":3.4},{"t":"text","x":50,"y":22,"text":"第一步：Fe₂O₃ 的质量 = 20 t × 80% = 16 t","size":3.2},{"t":"text","x":50,"y":34,"text":"第二步：Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂","size":3.2},{"t":"text","x":50,"y":44,"text":"160 : 112 = 16 t : x，x = 11.2 t","size":3.2},{"t":"text","x":50,"y":56,"text":"答：理论上可炼出铁 11.2 t","size":3.4,"tone":"accent"}]}},{"type":"note","title":"","text":"多步计算每一步都要重新检查单位与纯量：第一步换算的是矿石的纯度，第二步用的才是氧化铁的质量，不能把 20 t 直接代入方程式。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["纯度（物质的质量分数）","纯度 = 纯物质的质量 ÷ 样品的总质量 × 100%","质量单位统一为 g 或 t；结果用百分数表示 · 适用于石灰石、赤铁矿、粗盐等含杂质的固体样品。注意杂质必须是不参加反应的物质；若杂质也参加反应（如石灰石中混有碳酸镁），这个式子算出的就不是真正的碳酸钙含量，题目一般会说明「杂质不与酸反应」。"],["溶质质量与溶质质量分数","溶质质量 = 溶液质量 × 溶质质量分数；溶液质量 = 溶质质量 + 溶剂质量","质量单位统一为 g；溶质质量分数是百分数 · 适用于稀盐酸、稀硫酸、氢氧化钠溶液等一切溶液参与的反应。代入方程式的必须是算出来的溶质质量，溶液质量与溶剂质量都不能代入。若题目给的是溶液的体积和密度，要先用质量 = 密度 × 体积换算成质量。"],["由气体质量反求纯物质质量","m(纯物质) = m(气体) × 纯物质的相对分子质量 ÷ 气体的相对分子质量","质量单位统一为 g · 适用于质量差法、排水法收集气体等「已知气体质量求固体或液体质量」的题目，如由二氧化碳质量求碳酸钙质量（×100/44）。使用前提是气体完全逸出且被全部收集或称量到，方程式必须配平，系数要乘进相对分子质量。"],["多步计算（元素守恒）","原料中某元素的质量 = 产品中该元素的质量（元素在转化过程中不消失、不增加）","质量单位统一；矿石与产品可用 t，中间换算保持一致 · 适用于「矿石 → 产品」的多步转化（如赤铁矿炼铁、石灰石制生石灰）。用它可以跳过中间步骤直接列关系式，但必须保证中间没有损失（题目会写「理论上」）；若题目给出损失率，要先按损失率折减。"]]},{"type":"h","text":"应用 · 由生成的二氧化碳求样品中碳酸钙的质量分数"},{"type":"note","title":"情境","text":"取 12.5 g 石灰石样品（杂质不与盐酸反应）与足量稀盐酸充分反应，共收集到 4.4 g 二氧化碳。求样品中碳酸钙的质量分数。"},{"type":"list","title":"解答步骤","items":["设参加反应的碳酸钙质量为 x。","写出化学方程式：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量：CaCO₃ 为 100，CO₂ 为 44。","列比例式：100/44 = x/4.4 g，解得 x = 10 g。","求质量分数：10 g ÷ 12.5 g × 100% = 80%。","作答：样品中碳酸钙的质量分数为 80%（杂质 2.5 g）。"]},{"type":"note","title":"结论","text":"样品中碳酸钙的质量分数为 80%。"},{"type":"h","text":"应用 · 由稀盐酸的溶质质量分数求气体质量"},{"type":"note","title":"情境","text":"100 g 溶质质量分数为 7.3% 的稀盐酸与足量碳酸钙充分反应，能生成多少克二氧化碳？"},{"type":"list","title":"解答步骤","items":["换算溶质质量：m(HCl) = 100 g × 7.3% = 7.3 g。","设生成二氧化碳的质量为 x，写出方程式 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量总和：2HCl 为 73，CO₂ 为 44。","列比例式：73/44 = 7.3 g/x，解得 x = 4.4 g。","作答：生成二氧化碳 4.4 g。"]},{"type":"note","title":"结论","text":"生成二氧化碳 4.4 g。"},{"type":"h","text":"应用 · 多步计算：由矿石质量求产品中铁的质量"},{"type":"note","title":"情境","text":"工业上用含氧化铁 80% 的赤铁矿 20 t 炼铁，理论上可以得到多少吨铁？"},{"type":"list","title":"解答步骤","items":["第一步换算纯物质：m(Fe₂O₃) = 20 t × 80% = 16 t。","写出化学方程式：Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂。","算相对分子质量总和：Fe₂O₃ 为 160，2Fe 为 112。","列比例式：160/112 = 16 t/x，解得 x = 11.2 t。","作答：理论上可以得到铁 11.2 t。"]},{"type":"note","title":"结论","text":"理论上可以得到铁 11.2 t。"},{"type":"h","text":"实验 1 · 用质量差法测定石灰石中碳酸钙的质量分数"},{"type":"note","title":"实验目的","text":"通过反应前后总质量的减少量求出二氧化碳的质量，再计算样品中碳酸钙的质量分数"},{"type":"list","title":"实验器材","items":["托盘天平","锥形瓶","稀盐酸（足量）","石灰石样品","药匙"]},{"type":"figure","figure":{"id":"fig-chem-equation-5-exp1","title":"质量差法测碳酸钙的质量分数","caption":"先在敞口锥形瓶中进行反应，反应前后各称量一次，减少的质量就是逸出的二氧化碳","view":"wide","alt":"锥形瓶中盛有稀盐酸和石灰石，液面冒出气泡，旁边标出反应前后称量总质量的示意","prims":[{"t":"flask","x":34,"y":38,"kind":"conical","h":30,"w":26,"liquid":0.5,"color":"colorless","label":"锥形瓶"},{"t":"dot","x":30,"y":48,"r":1.8},{"t":"dot","x":37,"y":49,"r":1.8},{"t":"dot","x":28,"y":42,"hollow":true},{"t":"dot","x":38,"y":39,"hollow":true},{"t":"text","x":74,"y":24,"text":"反应前称量 m₁，反应后","size":3.1},{"t":"text","x":74,"y":32,"text":"称量 m₂，m₁ − m₂ 就是","size":3.1},{"t":"text","x":74,"y":40,"text":"逸出二氧化碳的质量","size":3.1},{"t":"text","x":74,"y":48,"text":"（装置敞口，气体可逸出）","size":3,"tone":"muted"}]}},{"type":"list","title":"实验步骤","items":["称量锥形瓶与足量稀盐酸的总质量 m₁。","把一定质量的石灰石样品（记为 m）用镊子小心放入锥形瓶，立即开始反应。","待不再产生气泡后再次称量总质量 m₂。","由 m₁ − m₂ 得到逸出的二氧化碳质量，按 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑ 算出碳酸钙质量。","用碳酸钙质量 ÷ 样品质量 × 100% 算出样品中碳酸钙的质量分数。"]},{"type":"note","title":"实验现象","text":"石灰石表面产生大量气泡并逐渐溶解，反应后称得的总质量比反应前小，减少的质量就是逸出的二氧化碳质量。"},{"type":"note","title":"实验结论","text":"碳酸钙的质量 = 二氧化碳质量 × 100/44，样品的纯度 = 碳酸钙质量 ÷ 样品质量 × 100%。"},{"type":"list","title":"注意事项","items":["盐酸必须足量，否则碳酸钙没有完全反应，算出的质量分数会偏小。","样品要塞成小块并稍稍研碎，让碳酸钙充分反应；反应要等到不再冒气泡为止。","必须用敞口装置（与验证质量守恒不同），因为这里恰恰需要让二氧化碳跑掉，用质量差求气体质量。","称量前要检查天平是否调平，样品不能洒落，反应后要等气流稳定再称量。","若样品中含有能与盐酸反应的其他成分（如碳酸镁），结果会偏大，因此该法只适用于杂质不与盐酸反应的石灰石。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","常温（不需加热）","固体逐渐溶解，表面产生大量气泡，气体使澄清石灰水变浑浊","配平要点：系数为 1、2、1、1、1。计算要点：CaCO₃ 为 100，2HCl 为 73，CO₂ 为 44。石灰石样品要先按纯度换算成碳酸钙的质量，稀盐酸要先按溶质质量分数换算成氯化氢的质量，两个数都不能直接代入。"],["CaCO₃ —高温→ CaO + CO₂↑","高温","固体逐渐分解，放出的气体使澄清石灰水变浑浊，得到白色固体氧化钙","配平要点：系数全为 1，只需检查两边钙、碳、氧原子个数（都是 1、1、3）。计算要点：CaCO₃ 为 100，CaO 为 56，CO₂ 为 44。工业上用石灰石制生石灰，原料中的杂质不分解，计算时同样要先算纯碳酸钙的质量。"],["Zn + H₂SO₄ —→ ZnSO₄ + H₂↑","常温（不需加热）","锌粒表面产生大量气泡并逐渐溶解，放出的气体能燃烧","配平要点：系数全为 1。计算要点：Zn 为 65，H₂SO₄ 为 98，H₂ 为 2。用稀硫酸时题目给的往往是「溶质质量分数」，如 100 g 9.8% 的稀硫酸中 H₂SO₄ 为 9.8 g，代入的必须是这 9.8 g。"],["Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂","高温","红棕色粉末逐渐变成黑色，澄清石灰水变浑浊","配平要点：先看 Fe₂O₃ 中的 3 个氧原子，每个 CO 只能夺走 1 个氧原子，故 CO 前配 3、CO₂ 前配 3，最后在 Fe 前配 2。计算要点：Fe₂O₃ 为 160，3CO 为 84，2Fe 为 112，3CO₂ 为 132。赤铁矿要先按纯度换算成氧化铁的质量；反应物中有气体 CO，生成的 CO₂ 不标 ↑。"],["NaOH + HCl —→ NaCl + H₂O","常温（不需加热）","无明显现象，反应放热（需借助指示剂或温度变化判断）","配平要点：系数全为 1，两边钠、氧、氢、氯原子个数相等。计算要点：NaOH 为 40，HCl 为 36.5，NaCl 为 58.5。溶液之间的反应，两种溶液都要先按溶质质量分数换算成溶质质量，再列比例式。"],["2NaOH + CO₂ —→ Na₂CO₃ + H₂O","常温（不需加热）","无明显现象，若用密闭装置可测出气体被吸收、质量减少","配平要点：NaOH 前配 2，使钠原子与生成物 Na₂CO₃ 中的 2 个钠对应，再数氢得 H₂O 前系数为 1。计算要点：2NaOH 为 80，CO₂ 为 44，Na₂CO₃ 为 106。这是用氢氧化钠溶液吸收二氧化碳的常用反应，多步计算里常与氢氧化钠溶液的溶质质量分数一起考查。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["取 12.5 g 石灰石与足量盐酸反应，就直接把 12.5 g 当作碳酸钙的质量代入方程式","要先按纯度换算成碳酸钙的质量（如 12.5 g × 80% = 10 g）再代入","石灰石中的杂质不参加反应，把它算进去会使算出的二氧化碳偏多。含杂质计算的第一个动作永远是换算，题目没给纯度时通常要通过实验数据先求出纯度。"],["100 g 稀盐酸与足量碳酸钙反应，就把 100 g 代入方程式计算二氧化碳","只有溶质氯化氢的质量才代入，如 100 g × 7.3% = 7.3 g","稀盐酸中大部分是水，水不参加反应。把溶液质量当溶质质量代入，算出的二氧化碳会偏大十几倍，这是综合计算题最常见的错误。"],["纯度就是物质中某元素的质量分数，两者是同一个概念","纯度是纯物质在样品中的质量分数；元素的质量分数是某元素在化合物（或样品）中的质量比例","如碳酸钙中钙元素的质量分数是 40/100 = 40%，而石灰石样品中碳酸钙的纯度可能是 80%，两者完全不同。计算时先分清问的是「多少碳酸钙」还是「多少钙元素」。"],["多步计算里，每一步都用最初那个样品的质量代入方程式就行","每一步都要用该步真正参加反应的纯物质质量，矿石、中间产物、产品各不相同","如赤铁矿炼铁：第一步要把矿石质量换算成氧化铁质量，第二步用的才是氧化铁的质量。一直用矿石质量代入，会把杂质也当成氧化铁，结果偏大。"]]},{"type":"table","title":"纯度与元素质量分数（两种「质量分数」分别指什么、怎么用）","head":["比较项","纯度（物质的质量分数）","元素的质量分数"],"rows":[["含义","样品中某种纯物质所占的质量比例","某元素在化合物（或样品）中所占的质量比例"],["计算式","纯物质质量 ÷ 样品质量 × 100%","该元素质量 ÷ 化合物（或样品）质量 × 100%"],["典型数值","石灰石中碳酸钙的纯度为 80%","碳酸钙中钙元素的质量分数为 40/100 = 40%"],["题目里的说法","「石灰石中碳酸钙的质量分数」「赤铁矿中氧化铁的纯度」","「样品中铁元素的质量分数」「多少吨铁」"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["含杂质样品的化学方程式计算","以石灰石、赤铁矿、粗锌为背景，给出纯度或需要通过实验数据求出纯度，再计算气体或产品的质量。评分标准里「先换算」是独立得分点，没有换算直接代入的解答即使数值巧合正确也扣分。"],["溶液参与的综合计算","给出溶液质量与溶质质量分数，或给出溶液体积与密度，要求先换算成溶质质量再计算。常见错误是把溶液质量当溶质质量代入，或把百分数当成了质量（把 7.3% 算成 7.3 g 的另一种错法）。"],["以质量差法为背景的实验加计算组合题","装置图 + 反应前后质量数据，要求先由质量差求出气体质量，再求样品纯度。答题时要区分两种装置：验证质量守恒要密闭，而用质量差求气体质量则必须让气体逸出，两者目的相反不能混用。"]]},{"type":"quote","text":"【材料一】化学小组要测定某石灰石样品中碳酸钙的质量分数。取该样品 25 g 放入烧杯中，分四次加入同一种稀盐酸，每次加入 100 g，每次充分反应后过滤、洗涤、干燥并称量剩余固体的质量，数据如下：第一次后剩余固体 15 g，第二次后剩余固体 5 g，第三次后剩余固体 5 g，第四次后剩余固体 5 g。\n【材料二】实验结束后老师提醒：样品中的杂质既不与稀盐酸反应，也不溶于水，因此剩余固体的质量就是杂质的质量；实验中每次加入的稀盐酸都是同一瓶中的同一种溶液。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】根据表中数据，求该石灰石样品中碳酸钙的质量分数。（4 分）","【设问】为什么第三次和第四次加入稀盐酸后，剩余固体的质量不再变化？（3 分）","【设问】求所用稀盐酸中溶质的质量分数（计算结果保留到 0.1%）。（5 分）"]}],"questions":[{"id":"chem-equation-5-q1","type":"choice","stem":"取 12.5 g 石灰石样品，测得其碳酸钙的质量分数为 80%（杂质不与盐酸反应）。样品中碳酸钙的质量是","answer":"B","explain":"纯物质质量 = 样品质量 × 纯度 = 12.5 g × 80% = 10 g，B 正确。A 错：没有做纯度换算，把样品质量直接当成了碳酸钙的质量。C 错：2.5 g 是杂质的质量，问的是碳酸钙却答成了杂质。D 错：8 g 是把 80% 与样品质量用错方式相乘得到的结果，纯物质质量应当用「样品质量 × 纯度」来算。","options":["12.5 g","10 g","2.5 g","8 g"],"difficulty":1,"tags":["含杂质计算","纯度"]},{"id":"chem-equation-5-q2","type":"choice","stem":"50 g 溶质质量分数为 9.8% 的稀硫酸与足量锌充分反应，生成氢气的质量是","answer":"D","explain":"先换算溶质：m(H₂SO₄) = 50 g × 9.8% = 4.9 g；再按 Zn + H₂SO₄ —→ ZnSO₄ + H₂↑ 列比例式 98/2 = 4.9 g/x，解得 x = 0.1 g，D 正确。A 错：0.2 g 是 9.8 g 硫酸对应的氢气质量，本题硫酸只有 4.9 g。B 错：漏乘了比例中的 2 或算错了倍数，得到的结果比正确答案还小。C 错：直接把溶质质量 4.9 g 当成了氢气质量，没有列比例式，也没有用相对分子质量之比。","options":["0.2 g","0.05 g","4.9 g","0.1 g"],"difficulty":2,"tags":["含杂质计算","溶质质量分数","化学方程式计算"]},{"id":"chem-equation-5-q3","type":"choice","stem":"关于含杂质物质的计算，下列说法正确的是","answer":"A","explain":"化学方程式只描述纯物质之间的质量关系，样品与溶液都必须先换算，A 正确。B 错：杂质一般不参加反应，把它算进去结果会偏大。C 错：题目最后常常要的是样品纯度或元素质量分数，算出的纯物质质量还要除以样品质量再乘 100%。D 错：纯度是纯物质在样品中的比例，元素质量分数是某元素在化合物中的比例，如碳酸钙中钙元素的质量分数是 40%，两者完全不同。","options":["必须先把样品的质量换算成参加反应的纯物质的质量，再代入化学方程式计算","样品中杂质的质量也会参加反应，所以样品的总质量可以直接代入","算出的纯物质质量就是样品的质量，不需要再换回质量分数","纯度就是物质中某元素的质量分数，两者是同一个概念"],"difficulty":1,"tags":["含杂质计算","纯度","概念辨析"]},{"id":"chem-equation-5-q4","type":"choice","stem":"8 g 碳酸钙与足量稀盐酸完全反应，生成二氧化碳的质量是","answer":"C","explain":"CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑，100/44 = 8 g/x，解得 x = 3.52 g，C 正确。A 错：4.4 g 是 10 g 碳酸钙生成的二氧化碳质量，题目给的是 8 g，属于套用了熟悉的数据而没有按比例算。B 错：直接把碳酸钙的质量当成了二氧化碳的质量，没有用质量比。D 错：0.88 g 是把质量比反过来用（44 : 100）算出的结果。","options":["4.4 g","8 g","3.52 g","0.88 g"],"difficulty":2,"tags":["含杂质计算","化学方程式计算"]},{"id":"chem-equation-5-q5","type":"choice","stem":"如图，把盛有足量稀盐酸的锥形瓶放在托盘天平上，再加入 10 g 石灰石样品（杂质不与盐酸反应），充分反应后再次称量。下列关于该实验方案的说法正确的是","answer":"B","explain":"这个装置是敞口的，生成的二氧化碳会逸出，减少的质量正好是二氧化碳的质量，等反应完全后再称量才能得到准确数据，B 正确。A 错：样品含杂质，必须先换算成碳酸钙的质量。C 错：减少的质量是二氧化碳的质量，不是碳酸钙的质量，碳酸钙质量要通过方程式换算。D 错：正因为气体逸出、质量减小，才可以用质量差法测出气体质量，进而求纯度。","options":["可以直接把 10 g 样品的质量代入方程式计算碳酸钙的质量","应当等不再产生气泡后再称量，用减少的质量求生成的二氧化碳质量","减少的质量就是参加反应的碳酸钙的质量","反应前后总质量不变，所以不能用这个方法测定碳酸钙的质量分数"],"difficulty":2,"tags":["含杂质计算","质量差法","实验方案"],"figure":{"id":"fig-chem-equation-5-q5","title":"质量差法测碳酸钙质量分数的装置","caption":"装置敞口，生成的二氧化碳逸出，用质量差求气体质量","view":"wide","alt":"锥形瓶中盛有稀盐酸与石灰石，液面冒出气泡，装置放在托盘天平上称量","prims":[{"t":"flask","x":34,"y":38,"kind":"conical","h":30,"w":26,"liquid":0.5,"color":"colorless","label":"锥形瓶"},{"t":"dot","x":30,"y":48,"r":1.8},{"t":"dot","x":37,"y":49,"r":1.8},{"t":"dot","x":28,"y":42,"hollow":true},{"t":"dot","x":38,"y":39,"hollow":true},{"t":"rect","x":64,"y":40,"w":30,"h":3,"fill":true,"tone":"muted"},{"t":"line","x1":79,"y1":40,"x2":79,"y2":30},{"t":"line","x1":68,"y1":30,"x2":90,"y2":30},{"t":"line","x1":70,"y1":30,"x2":70,"y2":35},{"t":"line","x1":88,"y1":30,"x2":88,"y2":35},{"t":"line","x1":64,"y1":35,"x2":76,"y2":35},{"t":"line","x1":82,"y1":35,"x2":94,"y2":35},{"t":"text","x":79,"y":54,"text":"托盘天平","size":3.2}]}},{"id":"chem-equation-5-q6","type":"fill","stem":"25 g 石灰石样品中碳酸钙的质量分数为 80%，样品中碳酸钙的质量是 ______ g。","answer":"20|20g|20 g","explain":"纯物质质量 = 样品质量 × 纯度 = 25 g × 80% = 20 g，杂质为 5 g。这类换算题不要忘记写单位；若算成 5 g，是把杂质的质量当成了碳酸钙的质量；若直接用 25 g，则没有做纯度换算。","difficulty":1,"tags":["含杂质计算","纯度"]},{"id":"chem-equation-5-q7","type":"short","stem":"取 20 g 石灰石样品与足量稀盐酸充分反应，共收集到 6.6 g 二氧化碳（样品中的杂质不与盐酸反应）。求样品中碳酸钙的质量分数。","answer":"样品中碳酸钙的质量分数为 75%。","explain":"这道题是「已知气体质量求样品纯度」的典型：先用方程式把二氧化碳换算成碳酸钙（100 : 44），再除以样品质量求百分数。最容易被扣分的是最后一步只写 15 g 就结束，题目问的是质量分数，必须再除以 20 g 乘 100%。","difficulty":2,"tags":["含杂质计算","化学方程式计算","纯度"],"rubric":["设未知量并写出配平正确的方程式","算对 CaCO₃ 为 100、CO₂ 为 44（气体符号不遗漏）","列比例式求出碳酸钙 15 g","用「碳酸钙质量 ÷ 样品质量 × 100%」求出 75%","答案带单位（百分号）并有完整答句"],"steps":["设参加反应的碳酸钙质量为 x。","写出化学方程式：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量：CaCO₃ 为 100，CO₂ 为 44。","列比例式：100/44 = x/6.6 g，解得 x = 6.6 g × 100 ÷ 44 = 15 g。","求质量分数：15 g ÷ 20 g × 100% = 75%。","作答：样品中碳酸钙的质量分数为 75%（杂质 5 g）。"]},{"id":"chem-equation-5-q8","type":"short","stem":"用 200 g 溶质质量分数为 7.3% 的稀盐酸与足量碳酸钙充分反应。求：（1）生成二氧化碳的质量；（2）参加反应的碳酸钙的质量。","answer":"（1）生成二氧化碳 8.8 g；（2）参加反应的碳酸钙为 20 g。","explain":"两个比例式共用同一个分母 73（2HCl 的相对分子质量总和），因此可以同时求出两种物质的量。若忘记换算直接用 200 g，会算出二氧化碳 120 g 这样明显不合理的数字，所以算完要回头检查结果是否符合常识（200 g 稀盐酸里只有 14.6 g 真正参加反应）。","difficulty":2,"tags":["含杂质计算","溶质质量分数","化学方程式计算"],"rubric":["先把溶液质量换算成溶质氯化氢 14.6 g（1.5 分）","写出配平正确的方程式并算对 73、44、100（1.5 分）","列比例式求出二氧化碳 8.8 g（1 分）","求出碳酸钙 20 g（1 分）","答案带单位并有完整答句（1 分）"],"steps":["先换算溶质质量：m(HCl) = 200 g × 7.3% = 14.6 g。","设生成二氧化碳的质量为 x，参加反应的碳酸钙质量为 y。","写出化学方程式：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量总和：CaCO₃ 为 100，2HCl 为 73，CO₂ 为 44。","列比例式求二氧化碳：73/44 = 14.6 g/x，解得 x = 8.8 g。","列比例式求碳酸钙：73/100 = 14.6 g/y，解得 y = 20 g。","作答：生成二氧化碳 8.8 g，参加反应的碳酸钙为 20 g。"]},{"id":"chem-equation-5-q9","type":"short","stem":"某小组要用质量差法测定石灰石样品中碳酸钙的质量分数。请写出：需要测定的数据、实验装置与操作要点，以及若反应后有少量二氧化碳留在锥形瓶内未逸出，测出的质量分数会偏大还是偏小，为什么？","answer":"需要测定的数据：样品的质量 m、反应前锥形瓶与足量稀盐酸的总质量 m₁、反应后锥形瓶与其中物质的总质量 m₂（要等不再产生气泡后再称量）。装置与操作要点：用敞口锥形瓶（这样二氧化碳才能逸出），稀盐酸必须足量，样品要研碎以充分反应，天平要先调平，称量要在气流稳定后进行。若少量二氧化碳留在瓶内未逸出，则测得的 m₂ 偏大、由 m₁ − m₂ 算出的二氧化碳质量偏小，进而算出的碳酸钙质量偏小，样品中碳酸钙的质量分数会偏小。","explain":"误差分析要顺着「哪一步的数据变了 → 求出什么量偏大偏小 → 最终结果偏大偏小」这条链子说清楚，不能只写结论。本题中气体残留使 m₂ 偏大、气体质量偏小、碳酸钙偏小、质量分数偏小，一共四步推下来才算完整。另外要注意与验证质量守恒的实验区分：那个实验必须密闭，这个实验恰恰要敞口。","difficulty":3,"tags":["含杂质计算","实验探究","误差分析"],"rubric":["写出需要测定的三个数据（样品质量、反应前后总质量）（2 分）","说明用敞口装置、盐酸足量、样品研碎、等气泡停止后称量（2 分）","判断质量分数偏小（1 分）","说明理由：二氧化碳未完全逸出使算出的气体质量偏小（1 分）"]},{"id":"chem-equation-5-q10","type":"short","stem":"取 25 g 石灰石样品（杂质不与盐酸反应）与足量稀盐酸充分反应，共收集到 8.8 g 二氧化碳。请写出完整的规范解答过程，求样品中碳酸钙的质量分数。","answer":"样品中碳酸钙的质量分数为 80%。","explain":"完整解答要把「样品 → 纯量 → 气体」的换算链条写出来：先由二氧化碳求碳酸钙（方程式计算），再由碳酸钙求质量分数（纯度换算）。只写 20 g 而没有最后一步换算是这类题最典型的失分方式，题目问的是质量分数就必须答质量分数。","difficulty":2,"tags":["含杂质计算","化学方程式计算","书写题"],"rubric":["设未知量并写清物质与单位","化学方程式配平、气体符号正确","算对 100 与 44，列比例式求出碳酸钙 20 g","用 20 g ÷ 25 g × 100% 求出 80%","答案带百分号并有完整答句"],"steps":["设参加反应的碳酸钙质量为 x。","写出化学方程式：CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量：CaCO₃ 为 100，CO₂ 为 44。","列比例式：100/44 = x/8.8 g，解得 x = 8.8 g × 100 ÷ 44 = 20 g。","把纯物质质量换算回质量分数：20 g ÷ 25 g × 100% = 80%。","作答：样品中碳酸钙的质量分数为 80%。"],"answerFigure":{"id":"fig-chem-equation-5-q10-a","title":"参考答案：完整规范的解答过程","caption":"先按方程式算出碳酸钙 20 g，再换算成质量分数 80%","view":"wide","alt":"板书给出一道含杂质计算的完整解答，包含设未知量、写方程式、算相对分子质量、列比例式、求纯物质质量和换算质量分数","prims":[{"t":"text","x":50,"y":9,"text":"解：设参加反应的碳酸钙质量为 x","size":3.1},{"t":"text","x":50,"y":19,"text":"CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑","size":3.3},{"t":"text","x":50,"y":29,"text":"100　　　　　　　　　　　　　44","size":3.3},{"t":"text","x":50,"y":39,"text":"x　　　　　　　　　　　　　　8.8 g","size":3.3},{"t":"text","x":50,"y":49,"text":"100/44 = x/8.8 g　x = 20 g","size":3.3},{"t":"text","x":50,"y":58,"text":"20 g ÷ 25 g × 100% = 80%","size":3.3,"tone":"accent"}]}},{"id":"chem-equation-5-m1-q1","type":"short","stem":"根据表中数据，求该石灰石样品中碳酸钙的质量分数。（4 分）","answer":"样品中碳酸钙的质量为 25 g − 5 g = 20 g，质量分数 = 20 g ÷ 25 g × 100% = 80%。","explain":"","tags":["含杂质计算","纯度","数据分析"],"rubric":["判断出剩余 5 g 是杂质的质量（2 分）","算出碳酸钙 20 g（1 分）","算得质量分数 80% 并作答（1 分）"],"steps":["分析数据：第三、四次剩余固体都是 5 g，说明第二次后碳酸钙已经完全反应，剩余 5 g 是不反应的杂质。","求碳酸钙质量：m(CaCO₃) = 25 g − 5 g = 20 g。","求质量分数：20 g ÷ 25 g × 100% = 80%。","作答：该石灰石样品中碳酸钙的质量分数为 80%。"]},{"id":"chem-equation-5-m1-q2","type":"short","stem":"为什么第三次和第四次加入稀盐酸后，剩余固体的质量不再变化？（3 分）","answer":"第二次加入稀盐酸后，样品中的碳酸钙已经全部反应完，剩余的 5 g 是不与盐酸反应也不溶于水的杂质。第三次、第四次再加入盐酸时已经没有碳酸钙可以反应，所以剩余固体的质量保持不变；这也说明第二次之后的盐酸已经过量。","explain":"","tags":["含杂质计算","数据分析","过量判断"],"rubric":["指出碳酸钙已完全反应（1.5 分）","指出剩余固体是不反应的杂质，且此时盐酸过量（1.5 分）"]},{"id":"chem-equation-5-m1-q3","type":"short","stem":"求所用稀盐酸中溶质的质量分数（计算结果保留到 0.1%）。（5 分）","answer":"所用稀盐酸中溶质的质量分数约为 7.3%。","explain":"","tags":["含杂质计算","溶质质量分数","化学方程式计算"],"rubric":["由第一次数据算出参加反应的碳酸钙 10 g（2 分）","写出配平的方程式并算对 100 与 73（1.5 分）","求出氯化氢 7.3 g（1 分）","求出溶质质量分数 7.3% 并作答（0.5 分）"],"steps":["第一次加入 100 g 稀盐酸后，固体由 25 g 减少到 15 g，说明参加反应的碳酸钙为 25 g − 15 g = 10 g。","设 100 g 稀盐酸中氯化氢的质量为 x，写出方程式 CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑。","算相对分子质量：CaCO₃ 为 100，2HCl 为 73。","列比例式：100/73 = 10 g/x，解得 x = 7.3 g。","求溶质质量分数：7.3 g ÷ 100 g × 100% = 7.3%。","作答：所用稀盐酸中溶质的质量分数为 7.3%。"]}]},{"id":"chem-equation-6","title":"反应类型与方程式分类整理","subtitle":"人教版九年级 · 中考专题 · 化学方程式与计算 · all","grade":"all","tags":["人教版九年级 · 中考专题 · 化学方程式与计算"],"blocks":[{"type":"note","title":"教材位置","text":"人教版九年级 · 中考专题 · 化学方程式与计算 · all"},{"type":"note","title":"问题切入","text":"同样是「生成两种物质」，为什么有的叫分解反应、有的叫复分解反应？氧化反应和化合反应是一回事吗？拿到一个方程式，怎么快速判断它属于哪一类？"},{"type":"note","title":"一句话抓住关键","text":"四种基本反应类型看「反应物与生成物的种类形式」：化合是一变多（多变一），分解是一变多（一变多），置换是「单质 + 化合物 → 新单质 + 新化合物」，复分解是两种化合物互相交换成分生成另外两种化合物。氧化反应与还原反应不是基本反应类型，它们看的是「得氧与失氧」，与化合、分解可能重叠。"},{"type":"h","text":"【宏观】一、从物质类别看四种基本反应类型"},{"type":"p","text":"化合反应：A + B → AB，多种物质变成一种，如 2Mg + O₂ —点燃→ 2MgO。分解反应：AB → A + B，一种物质变成多种，如 CaCO₃ —高温→ CaO + CO₂↑。置换反应：A + BC → AC + B，一种单质与一种化合物反应，生成另一种单质和另一种化合物，如 Fe + CuSO₄ —→ FeSO₄ + Cu。复分解反应：AB + CD → AD + CB，两种化合物互相交换成分生成另外两种化合物，如 NaOH + HCl —→ NaCl + H₂O。判断时先看反应物与生成物各有几种、是不是单质，再看形式对不对。"},{"type":"figure","figure":{"id":"fig-chem-equation-6-types","title":"四种基本反应类型","caption":"按反应物与生成物的种类形式判断，不看现象","view":"wide","alt":"板书列出四种基本反应类型的形式，化合是多变一，分解是一变多，置换是单质与化合物反应，复分解是两种化合物交换成分","prims":[{"t":"text","x":50,"y":10,"text":"化合：A + B → AB（多变一）","size":3.4},{"t":"text","x":50,"y":21,"text":"分解：AB → A + B（一变多）","size":3.4},{"t":"text","x":50,"y":32,"text":"置换：A + BC → AC + B（单质换单质）","size":3.4},{"t":"text","x":50,"y":43,"text":"复分解：AB + CD → AD + CB（交换成分）","size":3.4},{"t":"text","x":50,"y":56,"text":"先数物质种类，再看有没有单质，最后核对形式","size":3.2,"tone":"accent"}]}},{"type":"note","title":"","text":"置换反应中一定有单质参加、也一定有单质生成，这是它与复分解反应最明显的区别；复分解反应的两种反应物必须都是化合物。"},{"type":"h","text":"【微观】二、置换反应的微观特征"},{"type":"p","text":"把置换反应画成粒子：一个化合物分子 AB 与一个单质原子 C 相遇，C 把 B「挤」出来，自己与 A 结合成 AC，B 变成单独的原子（在实际反应中会结合成分子或离子）。所以置换反应的微观本质是「一种单质把化合物里的某种元素置换出来」，反应前后都有单质存在。复分解反应则完全不同：两种化合物只是互相交换合作伙伴，没有任何单质出现，各元素的化合价也不改变。"},{"type":"figure","figure":{"id":"fig-chem-equation-6-micro","title":"置换反应的微观过程","caption":"单质 C 把化合物 AB 中的 B 置换出来，生成新单质 B 与新化合物 AC","view":"wide","alt":"反应前一个由 A 和 B 组成的化合物分子与一个单独的 C 原子，反应后变成一个由 A 和 C 组成的分子与一个单独的 B 原子","prims":[{"t":"molecule","x":16,"y":22,"atoms":[{"dx":-2.6,"dy":0,"symbol":"A"},{"dx":2.6,"dy":0,"symbol":"B"}],"bonds":[[0,1]],"label":"AB"},{"t":"atom","x":16,"y":46,"symbol":"C","label":"单质"},{"t":"arrow","x1":30,"y1":32,"x2":46,"y2":32,"label":"反应","labelDy":-4},{"t":"molecule","x":68,"y":22,"atoms":[{"dx":-2.6,"dy":0,"symbol":"A"},{"dx":2.6,"dy":0,"symbol":"C"}],"bonds":[[0,1]],"label":"AC"},{"t":"atom","x":68,"y":46,"symbol":"B","label":"单质"},{"t":"text","x":50,"y":58,"text":"反应前后都有单质：单质 + 化合物 → 新单质 + 新化合物","size":3}]}},{"type":"note","title":"","text":"铁与硫酸铜溶液反应就是典型的置换反应：铁原子把铜离子中的铜置换出来，铁变成亚铁离子进入溶液，溶液由蓝色变成浅绿色。"},{"type":"h","text":"【符号】三、把常见方程式分类整理"},{"type":"p","text":"化合：2Mg + O₂ —点燃→ 2MgO、CaO + H₂O —→ Ca(OH)₂。分解：2H₂O₂ —MnO₂→ 2H₂O + O₂↑、CaCO₃ —高温→ CaO + CO₂↑、2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑。置换：Fe + CuSO₄ —→ FeSO₄ + Cu、Zn + H₂SO₄ —→ ZnSO₄ + H₂↑。复分解：NaOH + HCl —→ NaCl + H₂O、CaCO₃ + 2HCl —→ CaCl₂ + H₂O + CO₂↑、Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH。整理时把它们写在四栏里，考试时判断起来就是「对号入座」。"},{"type":"figure","figure":{"id":"fig-chem-equation-6-classify","title":"常见方程式的分类整理","caption":"四大类各选典型式子，反应条件一并记住","view":"wide","alt":"板书把常见化学方程式分成四类，分别列出化合、分解、置换、复分解的典型反应","prims":[{"t":"text","x":50,"y":9,"text":"化合：2Mg + O₂ —点燃→ 2MgO","size":3},{"t":"text","x":50,"y":19,"text":"分解：2H₂O₂ —MnO₂→ 2H₂O + O₂↑","size":3},{"t":"text","x":50,"y":29,"text":"置换：Fe + CuSO₄ —→ FeSO₄ + Cu","size":3},{"t":"text","x":50,"y":39,"text":"复分解：Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH","size":3},{"t":"text","x":50,"y":51,"text":"多数化合与分解反应同时属于氧化还原反应","size":3,"tone":"accent"},{"t":"text","x":50,"y":60,"text":"复分解反应中各元素化合价不变","size":3}]}},{"type":"note","title":"","text":"复分解反应发生的条件：生成物中有沉淀、气体或水（三者之一即可）。三条都不满足时反应不能发生，如 NaCl 溶液与 KNO₃ 溶液混合就没有反应。"},{"type":"h","text":"【应用】四、氧化反应与还原反应：另一套分类标准"},{"type":"p","text":"氧化反应指物质与氧发生的反应，还原反应指含氧化合物里的氧被夺去的反应，两者是「同一个反应的两个方面」，统称氧化还原反应。它们与四种基本反应类型是两套不同的分类标准：有氧气参加的化合反应（2Mg + O₂）既属于化合反应又属于氧化反应；甲烷燃烧 CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O 是氧化反应但不是化合反应；CaO + H₂O —→ Ca(OH)₂ 是化合反应却不是氧化反应。在 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂ 中，CO 夺取氧被氧化（作还原剂），Fe₂O₃ 失去氧被还原（作氧化剂）。"},{"type":"figure","figure":{"id":"fig-chem-equation-6-redox","title":"氧化反应与还原反应","caption":"得氧被氧化，失氧被还原；它与基本反应类型是两套标准","view":"wide","alt":"板书说明一氧化碳还原氧化铁中一氧化碳得到氧被氧化、氧化铁失去氧被还原，并指出氧化反应与化合反应不是一回事","prims":[{"t":"text","x":50,"y":10,"text":"Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂","size":3.6},{"t":"text","x":50,"y":22,"text":"CO 得到氧 → 被氧化 → 作还原剂","size":3.2},{"t":"text","x":50,"y":31,"text":"Fe₂O₃ 失去氧 → 被还原 → 作氧化剂","size":3.2},{"t":"text","x":50,"y":43,"text":"化合反应不一定是氧化反应：CaO + H₂O —→ Ca(OH)₂","size":3},{"t":"text","x":50,"y":52,"text":"氧化反应不一定是化合反应：CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O","size":3},{"t":"text","x":50,"y":61,"text":"置换反应一定是氧化还原反应","size":3,"tone":"accent"}]}},{"type":"note","title":"","text":"两套标准不能混：说「化合」「分解」「置换」「复分解」时看的是物质种类与形式；说「氧化」「还原」时看的是得氧与失氧（或化合价升降）。同一种反应可以同时占两套标准里的两项。"},{"type":"table","title":"公式与计算关系","head":["公式/关系","表达式","单位与用法"],"rows":[["四种基本反应类型的判断","化合：多变一；分解：一变多；置换：单质 + 化合物 → 新单质 + 新化合物；复分解：两种化合物互相交换成分","无 · 用于方程式的分类整理与反应类型填空。判断时先数物质种数，再看有没有单质；置换反应一定有单质参加和生成。注意 2NaOH + CO₂ —→ Na₂CO₃ + H₂O 不属于复分解反应，因为反应物不是两种化合物互相交换成分。"],["复分解反应发生的条件","两种化合物互相交换成分后，生成物中有沉淀、气体或水，反应才能发生","无 · 用于判断复分解反应能否发生，如 NaOH + HCl 生成水、CaCO₃ + 2HCl 生成气体、Na₂CO₃ + Ca(OH)₂ 生成沉淀都能反应；NaCl 与 KNO₃ 交换后没有沉淀、气体或水，反应不能发生。复分解反应中各元素化合价不变。"],["氧化反应与还原反应","物质得到氧 → 被氧化 → 作还原剂；含氧化合物失去氧 → 被还原 → 作氧化剂","无 · 用于判断氧化还原关系，如 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂ 中 CO 是还原剂、Fe₂O₃ 是氧化剂。它是与基本反应类型不同的另一套分类标准，两者可以同时适用，如置换反应一定属于氧化还原反应。"],["反应中的能量与现象对应","燃烧类反应都放出大量热；化合反应多放热（CaO + H₂O 明显放热）","无 · 用于判断现象与描述实验事实。注意现象描述要看真实反应：硫在氧气中燃烧发出明亮的蓝紫色火焰，铁丝在氧气中燃烧火星四射并生成黑色固体，不能说成「生成黑色气体」；放热是现象，不能用来判断反应类型。"]]},{"type":"h","text":"应用 · 给一批方程式分类"},{"type":"note","title":"情境","text":"把下列反应按四种基本反应类型归类：① 2Mg + O₂ —点燃→ 2MgO；② CaCO₃ —高温→ CaO + CO₂↑；③ Fe + CuSO₄ —→ FeSO₄ + Cu；④ NaOH + HCl —→ NaCl + H₂O；⑤ 2NaOH + CO₂ —→ Na₂CO₃ + H₂O。"},{"type":"list","title":"解答步骤","items":["① 两种物质生成一种：化合反应，同时是氧化反应。","② 一种物质生成两种：分解反应。","③ 单质 + 化合物 → 新单质 + 新化合物：置换反应。","④ 两种化合物互相交换成分生成两种新化合物：复分解反应。","⑤ 虽然生成两种化合物，但反应物是酸性氧化物与碱，不是互相交换成分：不属于复分解反应，属于非基本反应类型。"]},{"type":"note","title":"结论","text":"①②③④ 依次属于化合、分解、置换、复分解反应；⑤ 不属于四种基本反应类型。"},{"type":"h","text":"应用 · 置换反应的计算"},{"type":"note","title":"情境","text":"用一氧化碳还原 8 g 氧化铁（Fe₂O₃），理论上可以得到多少克铁？需要多少克一氧化碳？"},{"type":"list","title":"解答步骤","items":["设未知量：设生成铁的质量为 x，需要一氧化碳的质量为 y。","写出化学方程式：Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂。","算相对分子质量总和：Fe₂O₃ 为 160，3CO 为 84，2Fe 为 112。","列比例式求铁：160/112 = 8 g/x，解得 x = 5.6 g。","列比例式求一氧化碳：160/84 = 8 g/y，解得 y = 4.2 g。","作答：可得到铁 5.6 g，需要一氧化碳 4.2 g。"]},{"type":"note","title":"结论","text":"理论可得铁 5.6 g，需要一氧化碳 4.2 g。"},{"type":"h","text":"应用 · 氧化反应与化合反应的关系"},{"type":"note","title":"情境","text":"有人说「化合反应就是氧化反应，因为它们都要跟氧气反应」。这句话对吗？请举例说明。"},{"type":"list","title":"解答步骤","items":["反例一：CaO + H₂O —→ Ca(OH)₂ 是化合反应，但没有氧气参加，不是氧化反应。","反例二：CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O 是氧化反应，但生成两种物质，不是化合反应。","正例：2Mg + O₂ —点燃→ 2MgO 既是化合反应又是氧化反应。","结论：两者是交叉关系，不能互相代替。"]},{"type":"note","title":"结论","text":"这句话不对：化合反应不一定是氧化反应，氧化反应也不一定是化合反应，只有一部分反应同时属于两者。"},{"type":"h","text":"实验 1 · 铁钉与硫酸铜溶液反应（置换反应的证据）"},{"type":"note","title":"实验目的","text":"通过现象判断该反应属于置换反应，并观察溶液颜色的变化"},{"type":"list","title":"实验器材","items":["试管","铁钉（用砂纸打磨光亮）","硫酸铜溶液"]},{"type":"figure","figure":{"id":"fig-chem-equation-6-exp1","title":"铁钉与硫酸铜溶液反应","caption":"铁钉表面出现红色物质，溶液由蓝色变成浅绿色，属于置换反应","view":"wide","alt":"试管中盛有蓝色的硫酸铜溶液，一根铁钉浸在溶液中，铁钉表面出现红色的铜","prims":[{"t":"testTube","x":40,"y":32,"h":38,"w":12,"liquid":0.6,"color":"blue","label":"硫酸铜溶液"},{"t":"line","x1":40,"y1":14,"x2":40,"y2":44,"width":1.6},{"t":"dot","x":40,"y":40,"r":1.8},{"t":"dot","x":40,"y":36,"r":1.8},{"t":"text","x":68,"y":22,"text":"铁钉表面出现红色物质","size":3},{"t":"text","x":68,"y":31,"text":"溶液由蓝色变成浅绿色","size":3},{"t":"text","x":68,"y":40,"text":"属于置换反应","size":3,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["用砂纸把铁钉打磨光亮，放入试管中。","向试管中倒入约三分之一容积的硫酸铜溶液，使铁钉浸没。","静置观察铁钉表面和溶液颜色的变化。","反应一段时间后取出铁钉，观察其表面覆盖物的颜色。"]},{"type":"note","title":"实验现象","text":"铁钉表面覆盖一层红色的铜，蓝色溶液逐渐变成浅绿色，铁钉质量增大。"},{"type":"note","title":"实验结论","text":"Fe + CuSO₄ —→ FeSO₄ + Cu，一种单质与一种化合物反应生成另一种单质和另一种化合物，属于置换反应。"},{"type":"list","title":"注意事项","items":["铁钉必须先用砂纸打磨，否则表面的铁锈会影响观察效果。","硫酸铜溶液不能倒入过多，浸没铁钉即可，便于观察溶液颜色变化。","不要用手直接接触硫酸铜溶液，实验后要洗手；试管要及时洗涤，避免铜附着难以清除。"]},{"type":"h","text":"实验 2 · 氢氧化钠溶液与硫酸铜溶液反应（复分解反应的证据）"},{"type":"note","title":"实验目的","text":"通过生成蓝色沉淀的现象判断该反应属于复分解反应，并认识原子团的转移"},{"type":"list","title":"实验器材","items":["试管","氢氧化钠溶液","硫酸铜溶液","胶头滴管"]},{"type":"figure","figure":{"id":"fig-chem-equation-6-exp2","title":"氢氧化钠溶液与硫酸铜溶液反应","caption":"产生蓝色絮状沉淀，两种化合物相互交换成分，属于复分解反应","view":"wide","alt":"试管中盛有蓝色溶液并产生蓝色絮状沉淀，旁边标出该反应属于复分解反应","prims":[{"t":"testTube","x":40,"y":32,"h":38,"w":12,"liquid":0.6,"color":"blue","label":"氢氧化钠与硫酸铜溶液"},{"t":"dot","x":38,"y":47,"r":1.6,"tone":"accent"},{"t":"dot","x":42,"y":48,"r":1.6,"tone":"accent"},{"t":"dot","x":40,"y":44,"r":1.6,"tone":"accent"},{"t":"text","x":70,"y":24,"text":"产生蓝色絮状沉淀","size":3},{"t":"text","x":70,"y":33,"text":"两种化合物交换成分","size":3},{"t":"text","x":70,"y":42,"text":"属于复分解反应","size":3,"tone":"accent"}]}},{"type":"list","title":"实验步骤","items":["取一支洁净的试管，加入约 2 mL 氢氧化钠溶液。","用胶头滴管向试管中逐滴加入硫酸铜溶液，边加边观察。","观察沉淀的颜色与状态，静置后观察上层清液的颜色。"]},{"type":"note","title":"实验现象","text":"立即产生蓝色絮状沉淀，上层清液接近无色。"},{"type":"note","title":"实验结论","text":"2NaOH + CuSO₄ —→ Cu(OH)₂↓ + Na₂SO₄，两种化合物互相交换成分生成两种新化合物，属于复分解反应，各元素化合价都没有改变。"},{"type":"list","title":"注意事项","items":["胶头滴管要垂直悬空滴加，不能伸入试管内，也不能接触试管壁。","两种药品的用量不宜过多，逐滴加入便于观察沉淀的生成过程。","氢氧化钠溶液有腐蚀性，使用时要小心，实验后及时洗手。"]},{"type":"table","title":"化学方程式","head":["化学方程式","反应条件","现象","说明"],"rows":[["2Mg + O₂ —点燃→ 2MgO","点燃","发出耀眼的白光，放出大量的热，生成白色固体","化合反应（多变一），同时属于氧化反应。配平要点：MgO 前配 2 把氧原子凑成偶数，再在 Mg 前配 2。"],["CaO + H₂O —→ Ca(OH)₂","常温（不需加热）","放出大量的热，块状固体变成粉末状","化合反应但不是氧化反应（没有氧气参加）。配平要点：系数全为 1，两边钙、氧、氢原子个数相等。生石灰常用作食品干燥剂，就是靠这个反应吸收水分。"],["2H₂O₂ —MnO₂→ 2H₂O + O₂↑","二氧化锰作催化剂","有大量气泡产生，带火星的木条复燃","分解反应（一变多），同时属于氧化还原反应。配平要点：奇偶配平法，先把 H₂O 前配 2，再配 H₂O₂ 与 O₂。"],["CaCO₃ —高温→ CaO + CO₂↑","高温","固体逐渐分解，放出能使澄清石灰水变浑浊的气体","分解反应，工业制生石灰的原理。配平要点：系数全为 1。注意条件写「高温」而不是「加热」，条件写错不给分。"],["Fe + CuSO₄ —→ FeSO₄ + Cu","常温（不需加热）","铁表面覆盖一层红色的铜，蓝色溶液逐渐变成浅绿色","置换反应（单质 + 化合物 → 新单质 + 新化合物），同时属于氧化还原反应。配平要点：系数全为 1，两边铁、铜、硫、氧原子个数相等。化学式 FeSO₄ 中的铁显 +2 价，不能写成 Fe₂(SO₄)₃。"],["Zn + H₂SO₄ —→ ZnSO₄ + H₂↑","常温（不需加热）","锌粒表面产生大量气泡，锌逐渐溶解，气体能燃烧","置换反应。配平要点：系数全为 1。反应物中没有气体，生成的气体要标 ↑；ZnSO₄ 中锌显 +2 价，化学式为 ZnSO₄。"],["NaOH + HCl —→ NaCl + H₂O","常温（不需加热）","无明显现象，反应放热，需借助指示剂或温度变化判断","复分解反应（两种化合物互相交换成分生成另外两种化合物），各元素化合价不变，不属于氧化还原反应。配平要点：系数全为 1。这就是中和反应的实质。"],["Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH","常温（不需加热）","产生白色沉淀","复分解反应，原子团 CO₃ 与 OH 各自整体转移到新物质里。配平要点：原子团整体配平，先看钠与钙的个数，再在 NaOH 前配 2。"],["Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂","高温","红棕色粉末逐渐变成黑色，澄清石灰水变浑浊","不属于四种基本反应类型，但是典型的氧化还原反应：CO 得氧被氧化（还原剂），Fe₂O₃ 失氧被还原（氧化剂）。配平要点：Fe₂O₃ 中 3 个氧原子各被 1 个 CO 夺走，故 CO 与 CO₂ 前都配 3，铁前配 2。反应物中有气体，生成的 CO₂ 不标 ↑。"],["2NaOH + CO₂ —→ Na₂CO₃ + H₂O","常温（不需加热）","无明显现象，密闭装置中可测得气体被吸收","不属于复分解反应：虽然生成两种化合物，但不是两种化合物互相交换成分，而是酸性氧化物与碱的反应，属于非基本反应类型。配平要点：NaOH 前配 2，H₂O 前配 1，两边钠、碳、氧、氢原子个数相等。这一条最容易被错判成复分解反应。"]]},{"type":"table","title":"易错辨析","head":["错误理解","正确理解","原因"],"rows":[["氧化反应就是化合反应，因为它们都要有氧气参加","两者是交叉关系：CaO + H₂O 是化合反应但不是氧化反应，CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O 是氧化反应但不是化合反应","化合反应看的是「多种物质变成一种」，氧化反应看的是「与氧发生反应」，两套标准不同。只有像 2Mg + O₂ —点燃→ 2MgO 这样的反应才同时属于两者。"],["2NaOH + CO₂ —→ Na₂CO₃ + H₂O 生成两种化合物，所以属于复分解反应","它不属于复分解反应，因为反应物不是两种化合物互相交换成分","复分解反应的形式是 AB + CD → AD + CB，两种反应物都必须能「拆开」互相交换。CO₂ 与 NaOH 的反应是酸性氧化物与碱的反应，属于非基本反应类型，这也是中考常见的陷阱。"],["置换反应与复分解反应都是「两种物质反应生成两种物质」，可以互相替代使用","置换反应一定有单质参加和生成，复分解反应的反应物与生成物都是化合物","判断时看物质类别：Fe + CuSO₄ —→ FeSO₄ + Cu 中有单质铁与单质铜，是置换反应；NaOH + HCl —→ NaCl + H₂O 中没有单质，是复分解反应。此外置换反应属于氧化还原反应，复分解反应中各元素化合价不变。"],["只要是分解反应就一定有气体生成","分解反应只要求「一变多」，生成物不一定是气体","如 2KMnO₄ —加热→ K₂MnO₄ + MnO₂ + O₂↑ 有气体生成，而 CaCO₃ —高温→ CaO + CO₂↑ 虽然也有气体，但都是因为产物恰好是气体；分解反应的定义与产物状态无关，不能把「有气体」当作判断分解反应的条件。"]]},{"type":"table","title":"化合反应与氧化反应（两种「分类标准」之间的关系）","head":["比较项","化合反应","氧化反应"],"rows":[["判断依据","反应物多种、生成物一种（多变一）","物质与氧发生反应（得氧被氧化）"],["属于哪套标准","四种基本反应类型之一","氧化还原的一类，不是基本反应类型"],["典型例子","CaO + H₂O —→ Ca(OH)₂（化合但不是氧化）","CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O（氧化但不是化合）"],["两者同时满足","2Mg + O₂ —点燃→ 2MgO、4P + 5O₂ —点燃→ 2P₂O₅","同上：这些反应既是化合反应又是氧化反应"]]},{"type":"table","title":"置换反应与复分解反应（两种都由两种物质生成两种物质的反应怎么区分）","head":["比较项","置换反应","复分解反应"],"rows":[["形式","A + BC → AC + B","AB + CD → AD + CB"],["物质类别","一种单质 + 一种化合物 → 新单质 + 新化合物","两种化合物 → 另外两种化合物"],["化合价","一定发生变化（属于氧化还原反应）","各元素化合价都不变"],["典型例子","Fe + CuSO₄ —→ FeSO₄ + Cu；Zn + H₂SO₄ —→ ZnSO₄ + H₂↑","NaOH + HCl —→ NaCl + H₂O；Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH"]]},{"type":"table","title":"命题角度","head":["命题角度","说明"],"rows":[["反应类型判断（含配图）","给出化学方程式或粒子模型图，要求判断属于哪种基本反应类型。带图的题目要按「粒子种类与个数」还原成物质类别，再套形式；非基本反应类型（如 CO₂ 与 NaOH 反应）是常见的设置陷阱。"],["方程式分类整理与默写","要求把一批方程式按化合、分解、置换、复分解归类，或按类别各写一个例子。评分时化学式、配平与条件都要正确，分类写错与方程式写错分别扣分。"],["氧化反应与还原反应的关系分析","考查「氧化反应不一定是化合反应」「复分解反应不是氧化还原反应」等判断题，或要求指出 3CO + Fe₂O₃ —高温→ 2Fe + 3CO₂ 中的氧化剂与还原剂。答题要说清得氧失氧与化合价的变化。"]]},{"type":"quote","text":"【材料一】某小组把学过的化学方程式整理成四组：\n甲组：2Mg + O₂ —点燃→ 2MgO；CaO + H₂O —→ Ca(OH)₂\n乙组：2H₂O₂ —MnO₂→ 2H₂O + O₂↑；CaCO₃ —高温→ CaO + CO₂↑\n丙组：Fe + CuSO₄ —→ FeSO₄ + Cu；Zn + H₂SO₄ —→ ZnSO₄ + H₂↑\n丁组：NaOH + HCl —→ NaCl + H₂O；Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH\n【材料二】小组同学还讨论了两个式子：2NaOH + CO₂ —→ Na₂CO₃ + H₂O 与 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂，对它们该归到哪一类产生了分歧。","source":"材料"},{"type":"list","title":"材料题设问（答案见下方练习）","items":["【设问】写出甲、乙、丙、丁四组分别属于哪种基本反应类型，并说明判断的依据。（4 分）","【设问】材料二中两个式子各属于什么类型？请分别说明理由。（4 分）","【设问】按 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂ 计算：用 8 g 氧化铁与足量一氧化碳反应，理论上可以得到多少克铁？需要多少克一氧化碳？（5 分）"]}],"questions":[{"id":"chem-equation-6-q1","type":"choice","stem":"图是用字母表示的粒子模型示意图。该反应属于","answer":"C","explain":"反应前是一种化合物 AB 与一种单质 C，反应后生成另一种化合物 AC 与另一种单质 B，符合「单质 + 化合物 → 新单质 + 新化合物」的形式，属于置换反应，C 正确。A 错：生成物有两种，不是多变一。B 错：反应物有两种，不是一变多。D 错：复分解反应要求反应物与生成物都是化合物，本图中有单质参加和生成。","options":["化合反应","分解反应","置换反应","复分解反应"],"difficulty":2,"tags":["反应类型","置换反应","微观粒子"],"figure":{"id":"fig-chem-equation-6-q1","title":"某反应的粒子模型示意图","caption":"反应前后都有单质粒子，符合置换反应的形式","view":"wide","alt":"反应前是一个由 A 和 B 组成的化合物粒子与一个单独的 C 粒子，反应后是一个由 A 和 C 组成的粒子与一个单独的 B 粒子","prims":[{"t":"molecule","x":16,"y":22,"atoms":[{"dx":-2.6,"dy":0,"symbol":"A"},{"dx":2.6,"dy":0,"symbol":"B"}],"bonds":[[0,1]],"label":"AB"},{"t":"atom","x":16,"y":46,"symbol":"C"},{"t":"arrow","x1":30,"y1":32,"x2":46,"y2":32,"label":"反应","labelDy":-4},{"t":"molecule","x":68,"y":22,"atoms":[{"dx":-2.6,"dy":0,"symbol":"A"},{"dx":2.6,"dy":0,"symbol":"C"}],"bonds":[[0,1]],"label":"AC"},{"t":"atom","x":68,"y":46,"symbol":"B"},{"t":"text","x":50,"y":58,"text":"单质 + 化合物 → 新单质 + 新化合物","size":3.1}]}},{"id":"chem-equation-6-q2","type":"choice","stem":"关于氧化反应与化合反应的关系，下列说法正确的是","answer":"A","explain":"甲烷燃烧是氧化反应，但生成物有两种，不是化合反应，A 正确。B 错：CaO + H₂O —→ Ca(OH)₂ 是化合反应，却没有氧气参加。C 错：有氧气参加的反应若生成多种物质就不是化合反应，如甲烷燃烧。D 错：四种基本反应类型是化合、分解、置换、复分解，氧化反应是另一套标准的分类。","options":["氧化反应不一定是化合反应，例如 CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O","化合反应一定是氧化反应，因为化合反应都要有氧气参加","有氧气参加的反应都是化合反应","氧化反应属于四种基本反应类型之一"],"difficulty":2,"tags":["反应类型","氧化反应","概念辨析"]},{"id":"chem-equation-6-q3","type":"choice","stem":"下列反应中，属于复分解反应的是","answer":"D","explain":"NaOH 与 HCl 是两种化合物互相交换成分生成两种新化合物，属于复分解反应，D 正确。A 错：有单质铁参加、有单质铜生成，是置换反应。B 错：一种物质生成两种物质，是分解反应。C 错：这是酸性氧化物与碱的反应，虽然生成两种化合物，但不是两种化合物互相交换成分，不属于复分解反应，这是最常见的误判。","options":["Fe + CuSO₄ —→ FeSO₄ + Cu","CaCO₃ —高温→ CaO + CO₂↑","2NaOH + CO₂ —→ Na₂CO₃ + H₂O","NaOH + HCl —→ NaCl + H₂O"],"difficulty":2,"tags":["反应类型","复分解反应"]},{"id":"chem-equation-6-q4","type":"choice","stem":"在 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂ 中，失去氧被还原（作氧化剂）的物质是","answer":"B","explain":"Fe₂O₃ 中的氧被 CO 夺走，它失去氧、被还原，作氧化剂，B 正确。A 错：CO 得到氧、被氧化，作还原剂，正好相反。C 错：Fe 是生成物中的单质，是新生成的产物，不是被还原的物质本身。D 错：CO₂ 是 CO 被氧化后的产物，不是氧化剂。","options":["CO","Fe₂O₃","Fe","CO₂"],"difficulty":3,"tags":["反应类型","氧化还原","还原剂"]},{"id":"chem-equation-6-q5","type":"choice","stem":"如图，把铁钉放入盛有硫酸铜溶液的试管中。下列判断正确的是","answer":"C","explain":"铁与硫酸铜反应生成铜和硫酸亚铁，有单质参加与生成，属于置换反应，现象正是铁钉表面覆盖红色的铜、溶液由蓝色变浅绿色，C 正确。A 错：反应物中有单质铁，且生成物中有单质铜，不是复分解反应。B 错：生成的是硫酸亚铁（浅绿色），不是黄色的硫酸铁。D 错：铁钉消耗 56 份质量、析出 64 份质量，铁钉质量增大，溶液质量减小。","options":["该反应属于复分解反应，因为生成了两种化合物","溶液由蓝色变成黄色，说明生成了硫酸铁","铁钉表面出现红色物质，溶液由蓝色逐渐变成浅绿色，该反应属于置换反应","反应前后铁钉的质量不变，溶液的质量也不变"],"difficulty":2,"tags":["反应类型","置换反应","现象描述"],"figure":{"id":"fig-chem-equation-6-q5","title":"铁钉放入硫酸铜溶液中","caption":"铁钉表面出现红色物质，溶液由蓝色逐渐变成浅绿色","view":"wide","alt":"试管中盛有蓝色的硫酸铜溶液，一根铁钉浸在溶液中，铁钉表面覆盖红色的铜","prims":[{"t":"testTube","x":46,"y":32,"h":38,"w":12,"liquid":0.6,"color":"blue","label":"硫酸铜溶液"},{"t":"line","x1":46,"y1":14,"x2":46,"y2":44,"width":1.6},{"t":"dot","x":46,"y":40,"r":1.8},{"t":"dot","x":46,"y":36,"r":1.8},{"t":"text","x":84,"y":22,"text":"铁钉","size":3.2},{"t":"text","x":84,"y":34,"text":"红色物质","size":3.2},{"t":"text","x":84,"y":46,"text":"浅绿色溶液","size":3.2}]}},{"id":"chem-equation-6-q6","type":"fill","stem":"铁与硫酸铜溶液反应生成硫酸亚铁和铜，该反应属于 ______ 反应（填基本反应类型）。","answer":"置换|置换反应","explain":"反应物中有单质铁、化合物硫酸铜，生成物中有化合物硫酸亚铁、单质铜，符合「单质 + 化合物 → 新单质 + 新化合物」的形式，属于置换反应。注意不能填「复分解」，因为复分解反应的反应物与生成物必须都是化合物；也不能填「氧化还原」，那不是基本反应类型。","difficulty":1,"tags":["反应类型","置换反应"]},{"id":"chem-equation-6-q7","type":"short","stem":"2.4 g 镁与足量稀盐酸完全反应。求：（1）生成氢气的质量；（2）消耗氯化氢的质量。","answer":"（1）生成氢气 0.2 g；（2）消耗氯化氢 7.3 g。","explain":"本题的反应属于置换反应（镁置换出酸中的氢）。两个比例式共用分母 24，可以同时求出氢气和氯化氢。常见错误是把 HCl 的相对分子质量当成 36.5 而没有乘系数 2，那样会算出氯化氢 3.65 g，与质量守恒（2.4 g + 7.3 g = 9.5 g + 0.2 g）对不上。","difficulty":2,"tags":["反应类型","化学方程式计算","置换反应"],"rubric":["设未知量并写出配平正确的方程式（Mg + 2HCl —→ MgCl₂ + H₂↑）","算对 24、73、2（系数乘入）","列比例式求出氢气 0.2 g","求出氯化氢 7.3 g","答案带单位并有完整答句"],"steps":["设未知量：设生成氢气的质量为 x，消耗氯化氢的质量为 y。","写出化学方程式并检查配平：Mg + 2HCl —→ MgCl₂ + H₂↑。","算相对分子质量总和：Mg 为 24，2HCl 为 73，H₂ 为 2。","列比例式求氢气：24/2 = 2.4 g/x，解得 x = 0.2 g。","列比例式求氯化氢：24/73 = 2.4 g/y，解得 y = 7.3 g。","作答：生成氢气 0.2 g，消耗氯化氢 7.3 g。"]},{"id":"chem-equation-6-q8","type":"short","stem":"把 5.6 g 铁粉放入足量稀盐酸中，充分反应后铁全部溶解。求：（1）生成氢气的质量；（2）生成氯化亚铁的质量。","answer":"（1）生成氢气 0.2 g；（2）生成氯化亚铁 12.7 g。","explain":"铁与盐酸反应生成的是氯化亚铁 FeCl₂（铁显 +2 价），不是 FeCl₃，这是本题最容易失分的地方：写成 FeCl₃ 相对分子质量会算成 162.5，结果全错。方程式中的 H₂ 要标 ↑，因为反应物中没有气体。","difficulty":2,"tags":["反应类型","化学方程式计算","置换反应"],"rubric":["设未知量并写出配平、气体符号正确的方程式","算对 FeCl₂ 为 127（下标 2 不能漏）","列比例式求出氢气 0.2 g","求出氯化亚铁 12.7 g","答案带单位并有完整答句"],"steps":["设未知量：设生成氢气的质量为 x，生成氯化亚铁的质量为 y。","写出化学方程式：Fe + 2HCl —→ FeCl₂ + H₂↑。","算相对分子质量：Fe 为 56，FeCl₂ 为 56 + 35.5×2 = 127，H₂ 为 2。","列比例式求氢气：56/2 = 5.6 g/x，解得 x = 0.2 g。","列比例式求氯化亚铁：56/127 = 5.6 g/y，解得 y = 12.7 g。","作答：生成氢气 0.2 g，生成氯化亚铁 12.7 g。"]},{"id":"chem-equation-6-q9","type":"short","stem":"四种基本反应类型与氧化反应、还原反应之间是什么关系？请各举一个例子说明「有氧气参加的反应」「化合反应」「氧化反应」这三者的区别与联系，并说明复分解反应是否属于氧化还原反应。","answer":"四种基本反应类型（化合、分解、置换、复分解）是按反应物与生成物的种类形式划分的；氧化反应与还原反应是按物质得氧、失氧（化合价升降）划分的，两者是两套互不替代的标准。有氧气参加的反应不一定是化合反应，如 CH₄ + 2O₂ —点燃→ CO₂ + 2H₂O 生成两种产物；化合反应不一定有氧气参加，如 CaO + H₂O —→ Ca(OH)₂；氧化反应也不一定是化合反应。三者可以交叉：2Mg + O₂ —点燃→ 2MgO 既是有氧气参加的反应，又是化合反应，也是氧化反应。复分解反应中两种化合物只是互相交换成分，各元素化合价都没有改变，因此不属于氧化还原反应。","explain":"这道题考的是两套标准的边界。答题要成对举例：一边举「是 A 不是 B」，一边举「是 B 不是 A」，再举一个「两者都是」的，关系就说明白了。只写「两者有区别」而不举例，拿不到分。","difficulty":3,"tags":["反应类型","氧化还原","说理"],"rubric":["说明两套分类标准各自依据什么（2 分）","举出「有氧气参加但不是化合反应」的例子（如甲烷燃烧）（1 分）","举出「是化合反应但没有氧气参加」的例子（如 CaO + H₂O）（1 分）","指出反应类型可以交叉，并举例（1 分）","说明复分解反应中化合价不变，不属于氧化还原反应（1 分）"]},{"id":"chem-equation-6-q10","type":"short","stem":"把下列化学方程式按四种基本反应类型分类整理（把序号填在对应的类别后）。\n① 2Mg + O₂ —点燃→ 2MgO　② CaCO₃ —高温→ CaO + CO₂↑　③ Fe + CuSO₄ —→ FeSO₄ + Cu　④ NaOH + HCl —→ NaCl + H₂O　⑤ 2H₂O₂ —MnO₂→ 2H₂O + O₂↑　⑥ Zn + H₂SO₄ —→ ZnSO₄ + H₂↑　⑦ Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH　⑧ CaO + H₂O —→ Ca(OH)₂","answer":"化合反应：①⑧；分解反应：②⑤；置换反应：③⑥；复分解反应：④⑦。其中 ① 同时属于氧化反应，③⑥ 同时属于氧化还原反应，④⑦ 中各元素化合价不变。","explain":"分类的判断动作有三步：先数反应物与生成物的种数（一变多仍是分解、多变一是化合），再看有没有单质（有单质参加和生成的是置换），最后看是不是两种化合物互相交换成分（是才是复分解）。⑦ 中 CO₃ 与 OH 两个原子团各自整体转移，正是复分解反应的典型特征。","difficulty":2,"tags":["反应类型","分类整理","书写题"],"rubric":["化合反应填 ①⑧（2 分）","分解反应填 ②⑤（2 分）","置换反应填 ③⑥（2 分）","复分解反应填 ④⑦（2 分）"],"answerFigure":{"id":"fig-chem-equation-6-q10-a","title":"参考答案：方程式的分类整理","caption":"四种基本反应类型各归各类","view":"wide","alt":"板书把八个化学方程式按化合、分解、置换、复分解四类分别归类","prims":[{"t":"text","x":50,"y":10,"text":"化合：① 2Mg + O₂ —点燃→ 2MgO　⑧ CaO + H₂O —→ Ca(OH)₂","size":3},{"t":"text","x":50,"y":21,"text":"分解：② CaCO₃ —高温→ CaO + CO₂↑　⑤ 2H₂O₂ —MnO₂→ 2H₂O + O₂↑","size":3},{"t":"text","x":50,"y":32,"text":"置换：③ Fe + CuSO₄ —→ FeSO₄ + Cu　⑥ Zn + H₂SO₄ —→ ZnSO₄ + H₂↑","size":3},{"t":"text","x":50,"y":43,"text":"复分解：④ NaOH + HCl —→ NaCl + H₂O","size":3},{"t":"text","x":50,"y":53,"text":"⑦ Na₂CO₃ + Ca(OH)₂ —→ CaCO₃↓ + 2NaOH","size":3},{"t":"text","x":50,"y":61,"text":"③⑥ 属于氧化还原反应，④⑦ 中化合价不变","size":3,"tone":"accent"}]}},{"id":"chem-equation-6-m1-q1","type":"short","stem":"写出甲、乙、丙、丁四组分别属于哪种基本反应类型，并说明判断的依据。（4 分）","answer":"甲组属于化合反应（两种或多种物质生成一种物质，多变一）；乙组属于分解反应（一种物质生成两种或多种物质，一变多）；丙组属于置换反应（一种单质与一种化合物反应，生成另一种单质和另一种化合物）；丁组属于复分解反应（两种化合物互相交换成分，生成另外两种化合物）。","explain":"","tags":["反应类型","分类整理"],"rubric":["甲组：化合反应并说明「多变一」（1 分）","乙组：分解反应并说明「一变多」（1 分）","丙组：置换反应并说明单质与化合物的变化（1 分）","丁组：复分解反应并说明「交换成分」（1 分）"]},{"id":"chem-equation-6-m1-q2","type":"short","stem":"材料二中两个式子各属于什么类型？请分别说明理由。（4 分）","answer":"2NaOH + CO₂ —→ Na₂CO₃ + H₂O 不属于复分解反应，因为它不是两种化合物互相交换成分，而是酸性氧化物与碱的反应，属于非基本反应类型。Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂ 也不属于四种基本反应类型，但它是典型的氧化还原反应：CO 得到氧被氧化（作还原剂），Fe₂O₃ 失去氧被还原（作氧化剂）。","explain":"","tags":["反应类型","氧化还原","概念辨析"],"rubric":["指出 CO₂ 与 NaOH 的反应不属于复分解反应并说明理由（2 分）","指出 CO 还原氧化铁不属于基本反应类型（1 分）","指出其中 CO 是还原剂、Fe₂O₃ 是氧化剂（1 分）"]},{"id":"chem-equation-6-m1-q3","type":"short","stem":"按 Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂ 计算：用 8 g 氧化铁与足量一氧化碳反应，理论上可以得到多少克铁？需要多少克一氧化碳？（5 分）","answer":"理论上可以得到铁 5.6 g，需要一氧化碳 4.2 g。","explain":"","tags":["反应类型","化学方程式计算","氧化还原"],"rubric":["设未知量并写出配平、条件正确的方程式（1.5 分）","算对相对分子质量总和 160、84、112（1.5 分）","求出铁 5.6 g（1 分）","求出一氧化碳 4.2 g（1 分）","答案带单位并有完整答句（1 分）"],"steps":["设未知量：设生成铁的质量为 x，需要一氧化碳的质量为 y。","写出化学方程式：Fe₂O₃ + 3CO —高温→ 2Fe + 3CO₂。","算相对分子质量总和：Fe₂O₃ 为 160，3CO 为 84，2Fe 为 112。","列比例式求铁：160/112 = 8 g/x，解得 x = 5.6 g。","列比例式求一氧化碳：160/84 = 8 g/y，解得 y = 4.2 g。","作答：可得到铁 5.6 g，需要一氧化碳 4.2 g。"]}]}];
